-- FSc Mathematics 12: 479 original MCQs, MTH-0600 to MTH-1078.
-- Chapters follow Mathematics 12 (PECTAA, Punjab, National Curriculum 2023), units 1 to 11.
-- Written for Markhor Prep from the topics of the textbook units, not copied from any book or other bank. Every key that
-- can be calculated was recomputed by a script (sympy) before this file was made.
--
-- FSc Mathematics is on the engineering tests only, so every question has questions.mdcat = 0 (out of the MDCAT bank and
-- mocks). Each is listed in its FSc Pre-Engineering part (eng1 for Mathematics 11, eng2 for Mathematics 12) and in the
-- ECAT and NUST NET banks, under its own textbook unit. Not in the free set. INSERT OR IGNORE keeps the file safe to run
-- twice; if the site owner's admin account doesn't exist (a fresh local database) nothing is inserted. Inserted in
-- batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0600', 'Graphs of functions', 'Quadratic from its graph', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.1)', 'A parabola cuts the x-axis at x = −1 and x = 4 and opens upward. Which could be its equation?', '["y = (x − 1)(x + 4)", "y = −(x + 1)(x − 4)", "y = (x + 1)(x − 4)", "y = x² + 3x − 4"]', 2, 'Zeros at −1 and 4 give the factors (x + 1) and (x − 4); a positive leading coefficient makes it open upward.', '{"0": "Its zeros are 1 and −4.", "1": "This opens downward.", "3": "x² + 3x − 4 = (x + 4)(x − 1), with zeros −4 and 1."}'),
  ('MTH-0601', 'Graphs of functions', 'Quadratic from its graph', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.2)', 'A parabola has zeros x = 1 and x = 5 and passes through (0, 10). Its equation is:', '["y = 2(x − 1)(x − 5)", "y = (x − 1)(x − 5)", "y = 10(x − 1)(x − 5)", "y = −2(x − 1)(x − 5)"]', 0, 'y = a(x − 1)(x − 5). At x = 0: 5a = 10, so a = 2.', '{"1": "Gives y = 5 at x = 0.", "2": "Gives y = 50 at x = 0.", "3": "Gives y = −10 at x = 0."}'),
  ('MTH-0602', 'Graphs of functions', 'Quadratic from its graph', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.2)', 'A parabola has vertex (2, −3) and passes through (0, 5). Its equation is:', '["y = (x − 2)² − 3", "y = 2(x − 2)² − 3", "y = 2(x + 2)² − 3", "y = 8(x − 2)² − 3"]', 1, 'y = a(x − 2)² − 3. At x = 0: 4a − 3 = 5, so a = 2.', '{"0": "Gives y = 1 at x = 0.", "2": "Its vertex is at x = −2.", "3": "Gives y = 29 at x = 0."}'),
  ('MTH-0603', 'Graphs of functions', 'Algebraic and transcendental functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.3)', 'Which of these is a transcendental function?', '["y = x³ − 2x", "y = √(x + 1)", "y = 2ˣ", "y = (x + 1)/(x − 1)"]', 2, 'Exponential, logarithmic, trigonometric and hyperbolic functions are transcendental. The others are built from x by algebraic operations only.', '{"0": "A polynomial is algebraic.", "1": "A root of a polynomial expression is algebraic.", "3": "A rational function is algebraic."}'),
  ('MTH-0604', 'Graphs of functions', 'Exponential functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.4.1)', 'The graph of y = aˣ (a > 0, a ≠ 1) always passes through:', '["(1, 0)", "(0, 0)", "(1, 1)", "(0, 1)"]', 3, 'a⁰ = 1 for every allowed a.', '{"0": "That point is on y = logₐ x.", "1": "aˣ is never 0.", "2": "a¹ = a, which is 1 only if a = 1."}'),
  ('MTH-0605', 'Graphs of functions', 'Exponential functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.4.1)', 'What is the range of y = eˣ?', '["y ≥ 0", "y > 0", "All real numbers", "y ≥ 1"]', 1, 'eˣ is always positive and takes every positive value, but never 0.', '{"0": "eˣ never equals 0.", "2": "eˣ is never negative.", "3": "eˣ < 1 for x < 0."}'),
  ('MTH-0606', 'Graphs of functions', 'Exponential functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.4.1)', 'The graph of y = (1/2)ˣ:', '["decreases as x increases", "increases as x increases", "is a straight line", "passes through (0, 0)"]', 0, 'For a base between 0 and 1, aˣ decreases; it is the reflection of y = 2ˣ in the y-axis.', '{"1": "That happens for bases greater than 1.", "2": "It is a curve.", "3": "(1/2)⁰ = 1."}'),
  ('MTH-0607', 'Graphs of functions', 'Exponential functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The horizontal asymptote of y = 3ˣ − 2 is:', '["y = 0", "y = 3", "x = −2", "y = −2"]', 3, '3ˣ → 0 as x → −∞, so y → −2. The graph of 3ˣ is shifted 2 down.', '{"0": "That is the asymptote of 3ˣ before the shift.", "1": "3 is the base; the asymptote comes from 3ˣ → 0.", "2": "The asymptote is horizontal, not vertical."}'),
  ('MTH-0608', 'Graphs of functions', 'Logarithmic functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.6)', 'What is the domain of y = ln x?', '["x ≥ 0", "All real numbers", "x > 0", "x ≥ 1"]', 2, 'The logarithm is defined only for positive numbers.', '{"0": "ln 0 is not defined.", "1": "Negative numbers have no real logarithm.", "3": "ln x is defined for 0 < x < 1 too."}'),
  ('MTH-0609', 'Graphs of functions', 'Logarithmic functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.6.2)', 'The graph of y = log₂ x passes through:', '["(0, 1) and (1, 2)", "(0, 0) and (2, 1)", "(1, 0) and (2, 1)", "(1, 1) and (2, 2)"]', 2, 'log₂ 1 = 0 and log₂ 2 = 1.', '{"0": "Those are on y = 2ˣ.", "1": "log₂ 0 is not defined.", "3": "log₂ 1 = 0, not 1."}'),
  ('MTH-0610', 'Graphs of functions', 'Logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.8)', 'The graphs of y = eˣ and y = ln x are reflections of each other in:', '["the x-axis", "the y-axis", "the origin", "the line y = x"]', 3, 'They are inverse functions, and the graph of an inverse is the reflection in y = x.', '{"0": "Reflection in the x-axis gives y = −eˣ.", "1": "Reflection in the y-axis gives y = e⁻ˣ.", "2": "Reflection in the origin gives y = −e⁻ˣ."}'),
  ('MTH-0611', 'Graphs of functions', 'Logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.6)', 'What is the domain of y = ln(4 − x²)?', '["x < −2 or x > 2", "−2 < x < 2", "−2 ≤ x ≤ 2", "x < 2"]', 1, 'Need 4 − x² > 0, i.e. x² < 4.', '{"0": "There 4 − x² < 0.", "2": "At x = ±2, ln 0 is undefined.", "3": "Fails for x ≤ −2."}'),
  ('MTH-0612', 'Graphs of functions', 'Logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The vertical asymptote of y = ln(x − 3) is:', '["x = 3", "x = 0", "x = −3", "y = 3"]', 0, 'ln(x − 3) is the graph of ln x moved 3 to the right; ln x has asymptote x = 0.', '{"1": "That is for ln x itself.", "2": "The shift is to the right.", "3": "The asymptote is vertical."}'),
  ('MTH-0613', 'Graphs of functions', 'Hyperbolic functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.1)', 'sinh x is defined as:', '["(eˣ + e⁻ˣ)/2", "(eˣ − e⁻ˣ)/(eˣ + e⁻ˣ)", "eˣ − e⁻ˣ", "(eˣ − e⁻ˣ)/2"]', 3, 'sinh x = (eˣ − e⁻ˣ)/2.', '{"0": "That is cosh x.", "1": "That is tanh x.", "2": "Missing the factor 1/2."}'),
  ('MTH-0614', 'Graphs of functions', 'Hyperbolic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.1)', 'cosh²x − sinh²x equals:', '["−1", "1", "cosh 2x", "0"]', 1, '[(eˣ + e⁻ˣ)² − (eˣ − e⁻ˣ)²]/4 = 4/4 = 1.', '{"0": "Sign error: compare cos²x + sin²x = 1.", "2": "cosh 2x = cosh²x + sinh²x.", "3": "The difference is not 0."}'),
  ('MTH-0615', 'Graphs of functions', 'Hyperbolic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.1)', 'What is the range of y = cosh x?', '["y ≥ 1", "y ≥ 0", "All real numbers", "−1 ≤ y ≤ 1"]', 0, 'cosh x = (eˣ + e⁻ˣ)/2 ≥ 1 by the A.M.–G.M. inequality, with equality at x = 0.', '{"1": "cosh x never falls below 1.", "2": "cosh x is never negative.", "3": "That is the range of cos x."}'),
  ('MTH-0616', 'Graphs of functions', 'Hyperbolic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.1)', 'Find cosh(ln 2).', '["3/4", "2", "5/4", "1/2"]', 2, 'cosh(ln 2) = (2 + 1/2)/2 = 5/4.', '{"0": "That is sinh(ln 2).", "1": "Takes cosh(ln 2) as 2.", "3": "Takes only 1/2."}'),
  ('MTH-0617', 'Graphs of functions', 'Hyperbolic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.1)', 'Which hyperbolic function is odd?', '["cosh x", "sech x", "none of them", "sinh x"]', 3, 'sinh(−x) = −sinh x. cosh and sech are even.', '{"0": "cosh(−x) = cosh x.", "1": "sech is 1/cosh, also even.", "2": "sinh, tanh, coth, cosech are odd."}'),
  ('MTH-0618', 'Graphs of functions', 'Inverse hyperbolic functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.2)', 'sinh⁻¹x equals:', '["ln(x + √(x² − 1))", "(1/2) ln[(1 + x)/(1 − x)]", "ln(x + √(x² + 1))", "ln(x − √(x² + 1))"]', 2, 'Solve x = (eʸ − e⁻ʸ)/2: e²ʸ − 2xeʸ − 1 = 0, so eʸ = x + √(x² + 1) (positive root).', '{"0": "That is cosh⁻¹x.", "1": "That is tanh⁻¹x.", "3": "That root is negative, so its log is not real."}'),
  ('MTH-0619', 'Graphs of functions', 'Inverse hyperbolic functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.5.2)', 'tanh⁻¹x (for |x| < 1) equals:', '["ln[(1 + x)/(1 − x)]", "(1/2) ln[(1 + x)/(1 − x)]", "(1/2) ln[(1 − x)/(1 + x)]", "ln(x + √(x² + 1))"]', 1, 'Solve x = (e²ʸ − 1)/(e²ʸ + 1): e²ʸ = (1 + x)/(1 − x).', '{"0": "Missing the factor 1/2.", "2": "Inverted fraction.", "3": "That is sinh⁻¹x."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0620', 'Graphs of functions', 'Modulus function', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.7)', 'The graph of y = |x − 2| has its corner (lowest point) at:', '["(2, 0)", "(−2, 0)", "(0, 2)", "(0, −2)"]', 0, '|x − 2| = 0 at x = 2, and it is positive elsewhere.', '{"1": "The shift is to the right.", "2": "That is the y-intercept.", "3": "The graph is never below 0."}'),
  ('MTH-0621', 'Graphs of functions', 'Modulus function', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.7)', 'The graph of y = |x² − 4|:', '["is the same as y = x² − 4", "is the parabola y = x² − 4 with the part below the x-axis reflected upward", "is a V shape", "never touches the x-axis"]', 1, 'Taking the modulus reflects the negative part (−2 < x < 2) above the axis.', '{"0": "They differ for −2 < x < 2.", "2": "It is curved.", "3": "It touches at x = ±2."}'),
  ('MTH-0622', 'Graphs of functions', 'Inverse functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.8)', 'If f(x) = 2x + 3, then f⁻¹(x) is:', '["(x + 3)/2", "2x − 3", "1/(2x + 3)", "(x − 3)/2"]', 3, 'y = 2x + 3 gives x = (y − 3)/2; swap letters.', '{"0": "Sign error.", "1": "Undoes the operations in the wrong order.", "2": "That is the reciprocal, not the inverse."}'),
  ('MTH-0623', 'Graphs of functions', 'Inverse functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.8)', 'If f(x) = eˣ⁻¹, then f⁻¹(x) is:', '["1 + ln x", "ln x − 1", "ln(x + 1)", "e¹⁻ˣ"]', 0, 'y = eˣ⁻¹ gives x − 1 = ln y, x = 1 + ln y.', '{"1": "Sign error.", "2": "Wrong order of operations.", "3": "That is a reflection, not the inverse."}'),
  ('MTH-0624', 'Graphs of functions', 'Inverse functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.8)', 'A function has an inverse function exactly when it is:', '["continuous", "increasing everywhere", "one-to-one (on its domain)", "a polynomial"]', 2, 'Each output must come from exactly one input for the inverse to be a function.', '{"0": "Continuous functions like x² may not be one-to-one.", "1": "A decreasing function also has an inverse.", "3": "x² is a polynomial without an inverse on ℝ."}'),
  ('MTH-0625', 'Graphs of functions', 'Transformations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The graph of y = f(x) + 3 is the graph of y = f(x):', '["moved 3 units up", "moved 3 units down", "moved 3 units right", "stretched by 3"]', 0, 'Adding a constant outside f moves every point up.', '{"1": "That is f(x) − 3.", "2": "That is f(x − 3).", "3": "That is 3f(x)."}'),
  ('MTH-0626', 'Graphs of functions', 'Transformations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The graph of y = f(x + 2) is the graph of y = f(x) moved:', '["2 units right", "2 units up", "2 units left", "2 units down"]', 2, 'Replacing x by x + 2 moves the graph left.', '{"0": "That is f(x − 2).", "1": "That is f(x) + 2.", "3": "That is f(x) − 2."}'),
  ('MTH-0627', 'Graphs of functions', 'Transformations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The graph of y = −f(x) is the reflection of y = f(x) in:', '["the y-axis", "the x-axis", "the line y = x", "the origin"]', 1, 'Each y-value changes sign.', '{"0": "That is f(−x).", "2": "That gives the inverse.", "3": "That is −f(−x)."}'),
  ('MTH-0628', 'Graphs of functions', 'Transformations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The graph of y = 3f(x) is the graph of y = f(x):', '["stretched horizontally by factor 3", "moved 3 up", "compressed vertically by factor 3", "stretched vertically by factor 3"]', 3, 'Every y-value is multiplied by 3.', '{"0": "That is f(x/3).", "1": "That is f(x) + 3.", "2": "That is f(x)/3."}'),
  ('MTH-0629', 'Graphs of functions', 'Transformations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'The graph of y = f(2x) is the graph of y = f(x):', '["stretched horizontally by factor 2", "stretched vertically by factor 2", "moved 2 left", "compressed horizontally by factor 2 (towards the y-axis)"]', 3, 'Each feature at x now appears at x/2.', '{"0": "That is f(x/2).", "1": "That is 2f(x).", "2": "That is f(x + 2)."}'),
  ('MTH-0630', 'Graphs of functions', 'Transformations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.9)', 'Starting from y = √x, which sequence gives y = 2√(x − 1) + 3?', '["Shift 1 left, stretch vertically by 2, shift 3 up", "Shift 1 right, stretch horizontally by 2, shift 3 up", "Shift 1 right, stretch vertically by 2, shift 3 up", "Shift 3 right, stretch by 2, shift 1 up"]', 2, 'x − 1 moves right 1; the factor 2 stretches vertically; +3 moves up.', '{"0": "x − 1 means right.", "1": "The 2 multiplies the output.", "3": "Mixes up the shifts."}'),
  ('MTH-0631', 'Graphs of functions', 'Exponential and log equations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.10)', 'Solve 2ˣ⁺¹ = 32.', '["x = 5", "x = 4", "x = 16", "x = 3"]', 1, '32 = 2⁵, so x + 1 = 5.', '{"0": "Forgets the +1.", "2": "Divides 32 by 2.", "3": "Off by one in the other direction."}'),
  ('MTH-0632', 'Graphs of functions', 'Exponential and log equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.10)', 'Solve log₃(x + 4) = 2.', '["x = 5", "x = 2", "x = 9", "x = −1"]', 0, 'x + 4 = 3² = 9.', '{"1": "Uses 2 × 3 − 4.", "2": "Forgets to subtract 4.", "3": "Uses 3 − 4."}'),
  ('MTH-0633', 'Graphs of functions', 'Exponential and log equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.10)', 'Solve log x + log(x − 3) = 1 (base 10).', '["x = −2", "x = 5 or x = −2", "x = 10", "x = 5"]', 3, 'x(x − 3) = 10 gives x² − 3x − 10 = 0 = (x − 5)(x + 2). x = −2 makes log x undefined, so x = 5.', '{"0": "log of a negative number is undefined.", "1": "−2 must be rejected.", "2": "Ignores the second log."}'),
  ('MTH-0634', 'Graphs of functions', 'Exponential and log equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.10)', 'Solve 3^(2x) − 4 · 3ˣ + 3 = 0.', '["x = 1 or x = 3", "x = 0 or x = 1", "x = 1 only", "x = 0 only"]', 1, 'With y = 3ˣ: y² − 4y + 3 = 0 gives y = 1 or 3, so x = 0 or 1.', '{"0": "Those are the values of 3ˣ.", "2": "Misses x = 0.", "3": "Misses x = 1."}'),
  ('MTH-0635', 'Graphs of functions', 'Exponential and log equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.10)', 'Solve eˣ = 5 to 3 decimal places.', '["1.609", "0.699", "2.303", "148.413"]', 0, 'x = ln 5 ≈ 1.609.', '{"1": "That is log₁₀ 5.", "2": "That is ln 10.", "3": "That is e⁵."}'),
  ('MTH-0636', 'Graphs of functions', 'Applications', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.11)', 'A population grows as P = 2000e^(0.05t) (t in years). What is it after 20 years (to the nearest whole number)?', '["4000", "2100", "5437", "3000"]', 2, '2000e¹ ≈ 2000 × 2.71828 ≈ 5437.', '{"0": "Doubles instead of multiplying by e.", "1": "Uses simple growth for one year.", "3": "Uses 1.5 as the factor."}'),
  ('MTH-0637', 'Graphs of functions', 'Applications', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.11)', 'A radioactive substance decays as N = N₀e^(−kt). If half remains after 10 years, find k.', '["10 ln 2", "(ln 2)/10", "1/20", "ln 10/2"]', 1, '1/2 = e^(−10k) gives 10k = ln 2.', '{"0": "Inverted.", "2": "Treats decay as linear.", "3": "Wrong logarithm."}'),
  ('MTH-0638', 'Graphs of functions', 'Applications', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.11)', 'Rs 10,000 is invested at 8% a year compounded continuously: A = 10000e^(0.08t). About how long does it take to double?', '["12.5 years", "5 years", "16 years", "8.7 years"]', 3, 'e^(0.08t) = 2 gives t = ln 2/0.08 ≈ 0.693/0.08 ≈ 8.7 years.', '{"0": "That is 100/8 (simple interest).", "1": "Too short.", "2": "Doubles the answer."}'),
  ('MTH-0639', 'Graphs of functions', 'Applications', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.11)', 'On the Richter scale, M = log₁₀(I/I₀). How many times stronger is a magnitude 7 earthquake than a magnitude 5 one?', '["100", "2", "20", "10"]', 0, 'A difference of 2 in log₁₀ means a factor 10² = 100.', '{"1": "Subtracts the magnitudes only.", "2": "Multiplies 2 by 10.", "3": "That is one step."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0640', 'Graphs of functions', 'Graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.4.1)', 'How many solutions does eˣ = −x have?', '["0", "2", "1", "infinitely many"]', 2, 'eˣ increases from 0 to ∞ and −x decreases from ∞ to −∞, so their graphs cross exactly once (near x ≈ −0.57).', '{"0": "The graphs do cross.", "1": "One is increasing and the other decreasing.", "3": "Only once."}'),
  ('MTH-0641', 'Graphs of functions', 'Modulus function', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.7)', 'Solve |2x − 3| = x.', '["x = 3 only", "x = 1 only", "x = 1 or x = 3", "x = −3"]', 2, '2x − 3 = x gives x = 3; 2x − 3 = −x gives x = 1. Both are non-negative and check.', '{"0": "Misses the case 2x − 3 = −x.", "1": "Misses x = 3.", "3": "x must be non-negative since it equals a modulus."}'),
  ('MTH-0642', 'Graphs of functions', 'Exponential functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 1 Graphical Representation of Functions (§1.4)', 'Which is larger for very large x: x¹⁰⁰ or eˣ?', '["x¹⁰⁰", "they become equal", "it depends on the sign of x only", "eˣ"]', 3, 'Exponential growth eventually beats any power of x: x¹⁰⁰/eˣ → 0 as x → ∞.', '{"0": "True only for moderate x.", "1": "The ratio tends to 0.", "2": "Both are positive for large x."}'),
  ('MTH-0643', 'Further differentiation', 'Rules of differentiation', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.1)', 'If y = 4x³ − 5x + 7, then dy/dx is:', '["12x² − 5x", "12x² − 5", "4x² − 5", "12x³ − 5"]', 1, 'Power rule term by term: 4·3x² − 5 + 0.', '{"0": "The derivative of 5x is 5, not 5x.", "2": "The power 3 must also multiply the coefficient.", "3": "The power drops by one."}'),
  ('MTH-0644', 'Further differentiation', 'Rules of differentiation', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.1)', 'The derivative of √x with respect to x is:', '["1/(2√x)", "2√x", "1/√x", "√x/2"]', 0, '√x = x^(1/2), so the derivative is (1/2)x^(−1/2) = 1/(2√x).', '{"1": "That is the inverse of the right answer.", "2": "The factor 1/2 is missing.", "3": "The power must drop from 1/2 to −1/2."}'),
  ('MTH-0645', 'Further differentiation', 'Rules of differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.1)', 'If y = (2x + 1)/(x − 3), then dy/dx is:', '["−7/(x − 3)²", "7/(x − 3)²", "2", "−5/(x − 3)²"]', 0, 'Quotient rule: [2(x − 3) − (2x + 1)·1]/(x − 3)² = (2x − 6 − 2x − 1)/(x − 3)² = −7/(x − 3)².', '{"1": "The sign is lost: the numerator is −7.", "2": "Dividing the derivatives is not the quotient rule.", "3": "−6 − 1 is −7, not −5."}'),
  ('MTH-0646', 'Further differentiation', 'Rules of differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.1)', 'If y = x²(x − 1)³, then dy/dx is:', '["6x(x − 1)²", "x(x − 1)²(5x − 2)", "x(x − 1)²(5x + 2)", "2x(x − 1)³"]', 1, 'Product rule: 2x(x − 1)³ + 3x²(x − 1)² = x(x − 1)²[2(x − 1) + 3x] = x(x − 1)²(5x − 2).', '{"0": "Multiplying the two derivatives is not the product rule.", "2": "2(x − 1) + 3x = 5x − 2, not 5x + 2.", "3": "Only one term of the product rule."}'),
  ('MTH-0647', 'Further differentiation', 'Derivatives of trigonometric functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'd/dx (tan x) equals:', '["sec x tan x", "−cosec²x", "sec²x", "cot x"]', 2, 'd/dx (tan x) = sec²x.', '{"0": "That is the derivative of sec x.", "1": "That is the derivative of cot x.", "3": "cot x is the reciprocal, not the derivative."}'),
  ('MTH-0648', 'Further differentiation', 'Derivatives of trigonometric functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'd/dx (cosec x) equals:', '["cosec x cot x", "−cot²x", "sec x tan x", "−cosec x cot x"]', 3, 'd/dx (cosec x) = −cosec x cot x.', '{"0": "The minus sign is missing.", "1": "−cot²x = 1 − cosec²x; that is not the derivative of cosec x.", "2": "That is the derivative of sec x."}'),
  ('MTH-0649', 'Further differentiation', 'Derivatives of trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'If y = sin 3x cos 3x, then dy/dx is:', '["6 cos 6x", "−9 sin 3x cos 3x", "3 cos 3x − 3 sin 3x", "3 cos 6x"]', 3, 'y = (1/2) sin 6x, so dy/dx = (1/2)(6 cos 6x) = 3 cos 6x.', '{"0": "The factor 1/2 from sin 6x = 2 sin 3x cos 3x is lost.", "1": "Product of the two derivatives, not the product rule.", "2": "Each factor was differentiated and added; that is not the product rule."}'),
  ('MTH-0650', 'Further differentiation', 'Derivatives of trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'If y = sin²x, then dy/dx is:', '["2 sin x", "cos²x", "sin 2x", "2 cos x"]', 2, 'Chain rule: 2 sin x · cos x = sin 2x.', '{"0": "The factor cos x from the inner function is missing.", "1": "Squared the derivative instead of using the chain rule.", "3": "Only the derivative of the inside, doubled."}'),
  ('MTH-0651', 'Further differentiation', 'Derivatives of trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'If y = x sin x, then dy/dx at x = π is:', '["π", "−π", "0", "1"]', 1, 'dy/dx = sin x + x cos x. At x = π: 0 + π(−1) = −π.', '{"0": "cos π = −1, not 1.", "2": "Only sin π was used; the x cos x term is missing.", "3": "That is cos 0, not the derivative at π."}'),
  ('MTH-0652', 'Further differentiation', 'Derivatives of trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'If y = sec x + tan x, then dy/dx equals:', '["y sec x", "y tan x", "sec²x", "y²"]', 0, 'dy/dx = sec x tan x + sec²x = sec x(tan x + sec x) = y sec x.', '{"1": "Factor sec x, not tan x, from sec x tan x + sec²x.", "2": "That is only the derivative of tan x.", "3": "y² = sec²x + 2 sec x tan x + tan²x, not the same."}'),
  ('MTH-0653', 'Further differentiation', 'Derivatives of trigonometric functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'If y = cos x/(1 + sin x), then dy/dx is:', '["1/(1 + sin x)", "−cos x/(1 + sin x)²", "−1/(1 + sin x)", "−sin x/cos x"]', 2, 'Numerator of the quotient rule: −sin x(1 + sin x) − cos x·cos x = −sin x − 1 = −(1 + sin x). Dividing by (1 + sin x)² gives −1/(1 + sin x).', '{"0": "The sign is wrong.", "1": "Only the cos²x part of the numerator was kept.", "3": "Dividing the two derivatives is not the quotient rule."}'),
  ('MTH-0654', 'Further differentiation', 'Derivatives of trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.2)', 'd/dx (cot 2x) at x = π/8 equals:', '["−4", "4", "−2", "−1"]', 0, 'd/dx cot 2x = −2 cosec²2x. At x = π/8, 2x = π/4 and cosec²(π/4) = 2, giving −4.', '{"1": "The minus sign is missing.", "2": "The chain factor 2 was used but cosec²(π/4) = 2 was taken as 1.", "3": "Both the factor 2 and cosec² = 2 were left out."}'),
  ('MTH-0655', 'Further differentiation', 'Chain rule', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3)', 'If y = (3x − 2)⁵, then dy/dx is:', '["5(3x − 2)⁴", "(3x − 2)⁴", "15(3x − 2)⁵", "15(3x − 2)⁴"]', 3, 'Chain rule: 5(3x − 2)⁴ · 3.', '{"0": "The inner derivative 3 is missing.", "1": "Both the power and the inner derivative are missing.", "2": "The power must drop to 4."}'),
  ('MTH-0656', 'Further differentiation', 'Chain rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3)', 'If y = √(x² + 9), then dy/dx at x = 4 is:', '["1/10", "4/5", "8/5", "4/25"]', 1, 'dy/dx = x/√(x² + 9). At x = 4: 4/√25 = 4/5.', '{"0": "The inner derivative 2x was left out.", "2": "The factor 1/2 was dropped.", "3": "Divided by 25 instead of √25."}'),
  ('MTH-0657', 'Further differentiation', 'Chain rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.1)', 'If y = u³ and u = 2x + 1, then dy/dx at x = 1 is:', '["27", "54", "18", "9"]', 1, 'dy/dx = 3u² · 2 = 6u². At x = 1, u = 3, so dy/dx = 54.', '{"0": "The factor du/dx = 2 is missing.", "2": "Used u = 3 but 6u in place of 6u².", "3": "u² alone."}'),
  ('MTH-0658', 'Further differentiation', 'Chain rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.1)', 'If f(x) = x² and g(x) = sin x, then d/dx [f(g(x))] is:', '["2x cos x", "cos(x²) · 2x", "2 sin x", "2 sin x cos x"]', 3, 'f(g(x)) = sin²x, whose derivative is 2 sin x cos x.', '{"0": "Mixed up: x and sin x combined wrongly.", "1": "That is the derivative of g(f(x)) = sin x².", "2": "The inner derivative cos x is missing."}'),
  ('MTH-0659', 'Further differentiation', 'Chain rule', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3)', 'If y = sin³(2x), then dy/dx is:', '["6 sin²(2x) cos(2x)", "3 sin²(2x) cos(2x)", "6 sin²(2x)", "3 cos³(2x)"]', 0, 'Two layers: 3 sin²(2x) · cos(2x) · 2.', '{"1": "The innermost factor 2 is missing.", "2": "The factor cos(2x) is missing.", "3": "cos(2x) is the derivative of the inner sine, not a replacement for it; the outer power drops to 2."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0660', 'Further differentiation', 'Parametric differentiation', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.2)', 'If x = t² and y = 2t, then dy/dx is:', '["t", "2t", "1/t", "1/(2t)"]', 2, 'dy/dt = 2 and dx/dt = 2t, so dy/dx = 2/(2t) = 1/t.', '{"0": "That is dx/dy.", "1": "That is y, not dy/dx.", "3": "Used dy/dt = 1."}'),
  ('MTH-0661', 'Further differentiation', 'Parametric differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.2)', 'If x = a cos θ and y = a sin θ, then dy/dx is:', '["cot θ", "−tan θ", "−cot θ", "tan θ"]', 2, 'dy/dθ = a cos θ and dx/dθ = −a sin θ, so dy/dx = −cos θ/sin θ = −cot θ.', '{"0": "The minus sign from dx/dθ is lost.", "1": "That is dx/dy.", "3": "That is −dx/dy with the sign lost."}'),
  ('MTH-0662', 'Further differentiation', 'Parametric differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.2)', 'If x = t + 1/t and y = t − 1/t, then dy/dx at t = 2 is:', '["3/5", "1", "−5/3", "5/3"]', 3, 'dy/dt = 1 + 1/t² and dx/dt = 1 − 1/t². At t = 2: (5/4)/(3/4) = 5/3.', '{"0": "That is dx/dy.", "1": "The two derivatives are 5/4 and 3/4, not equal.", "2": "Both derivatives are positive at t = 2."}'),
  ('MTH-0663', 'Further differentiation', 'Parametric differentiation', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.2)', 'If x = 3t² and y = 2t³, then the slope of the curve at the point (12, 16) is:', '["1/2", "2", "4", "16/12"]', 1, 'At (12, 16), t = 2 (3t² = 12 and 2t³ = 16). dy/dx = 6t²/(6t) = t = 2.', '{"0": "That is dx/dy.", "2": "Used dy/dx = t² instead of t.", "3": "The slope is not y/x."}'),
  ('MTH-0664', 'Further differentiation', 'Implicit differentiation', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.3)', 'If x² + y² = 25, then dy/dx is:', '["−x/y", "x/y", "−y/x", "−2x"]', 0, '2x + 2y dy/dx = 0, so dy/dx = −x/y.', '{"1": "The sign is lost.", "2": "x and y swapped.", "3": "The y term was not differentiated."}'),
  ('MTH-0665', 'Further differentiation', 'Implicit differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.3)', 'If xy = 4, then dy/dx at (2, 2) is:', '["−1", "1", "−2", "0"]', 0, 'y + x dy/dx = 0, so dy/dx = −y/x = −1 at (2, 2).', '{"1": "The sign is lost.", "2": "That is −y/x at (4, 2), a point not on the curve.", "3": "The slope of xy = 4 is never 0."}'),
  ('MTH-0666', 'Further differentiation', 'Implicit differentiation', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.3)', 'If x³ + y³ = 3xy, then dy/dx is:', '["(x² − y)/(y² − x)", "(y − x²)/(y² − x)", "(y − x²)/(x − y²)", "−x²/y²"]', 1, '3x² + 3y² y′ = 3y + 3x y′, so y′(y² − x) = y − x², giving y′ = (y − x²)/(y² − x).', '{"0": "The numerator''s sign is reversed.", "2": "The denominator''s sign is reversed.", "3": "The 3xy term was ignored."}'),
  ('MTH-0667', 'Further differentiation', 'Implicit differentiation', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.3.3)', 'The slope of the curve x² + xy + y² = 7 at the point (1, 2) is:', '["4/5", "−5/4", "−4/5", "−1/2"]', 2, '2x + y + x y′ + 2y y′ = 0, so y′ = −(2x + y)/(x + 2y) = −(2 + 2)/(1 + 4) = −4/5.', '{"0": "The sign is lost.", "1": "Numerator and denominator swapped.", "3": "The xy term was not differentiated by the product rule."}'),
  ('MTH-0668', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'd/dx (sin⁻¹x) equals:', '["−1/√(1 − x²)", "1/(1 + x²)", "1/(x√(x² − 1))", "1/√(1 − x²)"]', 3, 'd/dx sin⁻¹x = 1/√(1 − x²), for |x| < 1.', '{"0": "That is the derivative of cos⁻¹x.", "1": "That is the derivative of tan⁻¹x.", "2": "That is the derivative of sec⁻¹x (x > 1)."}'),
  ('MTH-0669', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'd/dx (tan⁻¹x) equals:', '["−1/(1 + x²)", "sec²x", "1/(1 + x²)", "1/√(1 + x²)"]', 2, 'd/dx tan⁻¹x = 1/(1 + x²).', '{"0": "That is the derivative of cot⁻¹x.", "1": "That is the derivative of tan x.", "3": "There is no square root."}'),
  ('MTH-0670', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'If y = tan⁻¹(2x), then dy/dx is:', '["1/(1 + 4x²)", "2/(1 + 2x²)", "2/(1 + x²)", "2/(1 + 4x²)"]', 3, 'Chain rule: [1/(1 + (2x)²)] · 2.', '{"0": "The inner derivative 2 is missing.", "1": "(2x)² = 4x², not 2x².", "2": "The inside must be squared as 2x."}'),
  ('MTH-0671', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'If y = sin⁻¹(x/3), then dy/dx is:', '["3/√(9 − x²)", "1/√(9 − x²)", "1/(3√(9 − x²))", "1/√(1 − x²)"]', 1, '(1/3)/√(1 − x²/9) = (1/3)/(√(9 − x²)/3) = 1/√(9 − x²).', '{"0": "The 3 should cancel, not multiply.", "2": "Both 3s should cancel.", "3": "The inside is x/3, not x."}'),
  ('MTH-0672', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'If y = sin⁻¹x + cos⁻¹x, then dy/dx is:', '["0", "2/√(1 − x²)", "π/2", "1"]', 0, 'sin⁻¹x + cos⁻¹x = π/2, a constant, so its derivative is 0. (Also 1/√(1 − x²) − 1/√(1 − x²) = 0.)', '{"1": "The derivative of cos⁻¹x carries a minus sign.", "2": "π/2 is the value of y, not of dy/dx.", "3": "A constant has derivative 0."}'),
  ('MTH-0673', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'If y = tan⁻¹(eˣ), then dy/dx at x = 0 is:', '["1", "1/4", "2", "1/2"]', 3, 'dy/dx = eˣ/(1 + e²ˣ). At x = 0: 1/(1 + 1) = 1/2.', '{"0": "Missing the denominator 1 + e²ˣ.", "1": "Squared the denominator.", "2": "Inverted the answer."}'),
  ('MTH-0674', 'Further differentiation', 'Derivatives of inverse trigonometric functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.4)', 'd/dx (sec⁻¹x), for x > 1, equals:', '["−1/(x√(x² − 1))", "1/(x√(x² − 1))", "1/√(x² − 1)", "sec x tan x"]', 1, 'd/dx sec⁻¹x = 1/(x√(x² − 1)) for x > 1.', '{"0": "That is the derivative of cosec⁻¹x.", "2": "The factor x in the denominator is missing.", "3": "That is the derivative of sec x."}'),
  ('MTH-0675', 'Further differentiation', 'Derivatives of exponential functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.5)', 'd/dx (e^(3x)) equals:', '["3e^(3x)", "e^(3x)", "3x e^(3x − 1)", "e^(3x)/3"]', 0, 'Chain rule: e^(3x) · 3.', '{"1": "The inner derivative 3 is missing.", "2": "The power rule does not apply to eˣ.", "3": "Divided instead of multiplied."}'),
  ('MTH-0676', 'Further differentiation', 'Derivatives of exponential functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.5)', 'd/dx (2ˣ) equals:', '["x · 2ˣ⁻¹", "2ˣ", "2ˣ ln 2", "2ˣ/ln 2"]', 2, 'd/dx aˣ = aˣ ln a.', '{"0": "The power rule does not apply when x is in the exponent.", "1": "Only eˣ is its own derivative.", "3": "ln 2 multiplies, it does not divide."}'),
  ('MTH-0677', 'Further differentiation', 'Derivatives of exponential functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.5)', 'If y = x²eˣ, then dy/dx is:', '["2xeˣ", "x²eˣ", "eˣ(x² + 2)", "xeˣ(x + 2)"]', 3, 'Product rule: 2xeˣ + x²eˣ = xeˣ(x + 2).', '{"0": "Only one term of the product rule.", "1": "Only the other term.", "2": "2x, not 2, is the derivative of x²."}'),
  ('MTH-0678', 'Further differentiation', 'Derivatives of exponential functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.5)', 'If y = e^(sin x), then dy/dx is:', '["e^(cos x)", "cos x · e^(sin x)", "sin x · e^(sin x − 1)", "e^(sin x)"]', 1, 'Chain rule: e^(sin x) · cos x.', '{"0": "The exponent is not differentiated in place.", "2": "The power rule does not apply.", "3": "The inner derivative cos x is missing."}'),
  ('MTH-0679', 'Further differentiation', 'Derivatives of exponential functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.5)', 'If y = e^(−x²), then the value of x at which dy/dx = 0 is:', '["x = 0", "x = 1", "x = −1", "No such x"]', 0, 'dy/dx = −2x e^(−x²). Since e^(−x²) > 0, dy/dx = 0 only when x = 0.', '{"1": "dy/dx = −2e⁻¹ at x = 1.", "2": "dy/dx = 2e⁻¹ at x = −1.", "3": "x = 0 works."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0680', 'Further differentiation', 'Derivatives of logarithmic functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'd/dx (ln 5x) equals:', '["5/x", "1/(5x)", "1/x", "5"]', 2, 'ln 5x = ln 5 + ln x, so the derivative is 1/x. (Or (1/5x) · 5.)', '{"0": "The 5 cancels: (1/5x)·5 = 1/x.", "1": "The inner derivative 5 was left out.", "3": "That is the inner derivative alone."}'),
  ('MTH-0681', 'Further differentiation', 'Derivatives of logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'If y = ln(x² + 1), then dy/dx is:', '["2x/(x² + 1)", "1/(x² + 1)", "2x", "1/(2x)"]', 0, 'Chain rule: [1/(x² + 1)] · 2x.', '{"1": "The inner derivative 2x is missing.", "2": "Only the inner derivative.", "3": "That inverts the inner derivative instead of dividing by x² + 1."}'),
  ('MTH-0682', 'Further differentiation', 'Derivatives of logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'd/dx (log₁₀ x) equals:', '["1/x", "ln 10/x", "1/(x ln 10)", "10/x"]', 2, 'logₐ x = ln x/ln a, so the derivative is 1/(x ln a).', '{"0": "That is only for the natural log.", "1": "ln 10 divides, it does not multiply.", "3": "The factor is 1/ln 10, not 10."}'),
  ('MTH-0683', 'Further differentiation', 'Derivatives of logarithmic functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'If y = ln(sin x), then dy/dx is:', '["tan x", "cot x", "1/sin x", "cos x"]', 1, '(1/sin x) · cos x = cot x.', '{"0": "cos x/sin x is cot x, not tan x.", "2": "The inner derivative cos x is missing.", "3": "The factor 1/sin x is missing."}'),
  ('MTH-0684', 'Further differentiation', 'Derivatives of logarithmic functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'If y = xˣ (x > 0), then dy/dx is:', '["x · xˣ⁻¹", "xˣ ln x", "xˣ", "xˣ(1 + ln x)"]', 3, 'ln y = x ln x. Differentiating: y′/y = ln x + 1, so y′ = xˣ(1 + ln x).', '{"0": "The power rule needs a constant exponent.", "1": "That treats x as a constant base.", "2": "The derivative of x ln x is ln x + 1."}'),
  ('MTH-0685', 'Further differentiation', 'Derivatives of logarithmic functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.6)', 'If y = ln[(x + 1)/(x − 1)], then dy/dx is:', '["2/(x² − 1)", "1/(x + 1) + 1/(x − 1)", "(x − 1)/(x + 1)", "−2/(x² − 1)"]', 3, 'y = ln(x + 1) − ln(x − 1), so y′ = 1/(x + 1) − 1/(x − 1) = [(x − 1) − (x + 1)]/(x² − 1) = −2/(x² − 1).', '{"0": "The sign is lost.", "1": "The log of a quotient is a difference.", "2": "That is just the reciprocal of the inside."}'),
  ('MTH-0686', 'Further differentiation', 'Tangent and normal', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.7)', 'The slope of the tangent to y = x² at x = 3 is:', '["9", "6", "3", "2"]', 1, 'dy/dx = 2x = 6 at x = 3.', '{"0": "That is the y-value.", "2": "That is the x-value, not the slope.", "3": "That is the slope at x = 1."}'),
  ('MTH-0687', 'Further differentiation', 'Tangent and normal', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.7)', 'The equation of the tangent to y = x³ at (1, 1) is:', '["y = 3x − 2", "y = 3x + 1", "y = x", "y = 3x − 3"]', 0, 'Slope 3x² = 3 at x = 1. y − 1 = 3(x − 1) gives y = 3x − 2.', '{"1": "Does not pass through (1, 1).", "2": "Wrong slope.", "3": "Does not pass through (1, 1)."}'),
  ('MTH-0688', 'Further differentiation', 'Tangent and normal', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.7)', 'The slope of the normal to y = x² − 4x at x = 3 is:', '["2", "1/2", "−1/2", "−2"]', 2, 'Tangent slope 2x − 4 = 2 at x = 3. The normal''s slope is −1/2.', '{"0": "That is the tangent''s slope.", "1": "The normal''s slope is the negative reciprocal.", "3": "Negated but not inverted."}'),
  ('MTH-0689', 'Further differentiation', 'Tangent and normal', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.7)', 'At which point on y = x² − 6x + 10 is the tangent parallel to the x-axis?', '["(3, 10)", "(0, 10)", "(3, 1)", "(6, 10)"]', 2, 'dy/dx = 2x − 6 = 0 at x = 3, and y = 9 − 18 + 10 = 1.', '{"0": "y(3) = 1, not 10.", "1": "The slope there is −6.", "3": "The slope there is 6."}'),
  ('MTH-0690', 'Further differentiation', 'Tangent and normal', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.7)', 'The equation of the normal to y = eˣ at x = 0 is:', '["x + y = 1", "y = x + 1", "x − y = 1", "x + y = 0"]', 0, 'At x = 0, y = 1 and the tangent slope is e⁰ = 1, so the normal slope is −1: y − 1 = −(x − 0), i.e. x + y = 1.', '{"1": "That is the tangent.", "2": "Does not pass through (0, 1).", "3": "Does not pass through (0, 1)."}'),
  ('MTH-0691', 'Further differentiation', 'Higher derivatives', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If y = x⁴, then d²y/dx² is:', '["4x³", "12x³", "24x", "12x²"]', 3, 'y′ = 4x³, y″ = 12x².', '{"0": "That is the first derivative.", "1": "The power must drop twice.", "2": "That is the third derivative."}'),
  ('MTH-0692', 'Further differentiation', 'Higher derivatives', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If y = sin 2x, then d²y/dx² equals:', '["4y", "−4y", "−2y", "−y"]', 1, 'y′ = 2 cos 2x, y″ = −4 sin 2x = −4y.', '{"0": "The sign is lost.", "2": "Each derivative brings out a factor 2, so 2·2 = 4.", "3": "The chain factors are missing."}'),
  ('MTH-0693', 'Further differentiation', 'Higher derivatives', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If y = e^(2x), then the 4th derivative of y is:', '["8e^(2x)", "2e^(2x)", "4e^(2x)", "16e^(2x)"]', 3, 'Each derivative multiplies by 2, so the nth derivative is 2ⁿe^(2x); 2⁴ = 16.', '{"0": "That is the 3rd derivative.", "1": "That is the 1st derivative.", "2": "That is the 2nd derivative."}'),
  ('MTH-0694', 'Further differentiation', 'Higher derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If y = ln x, then the nth derivative of y is:', '["(−1)ⁿ n!/xⁿ", "(n − 1)!/xⁿ", "(−1)ⁿ⁻¹(n − 1)!/xⁿ", "(−1)ⁿ(n − 1)!/xⁿ"]', 2, 'y′ = 1/x, y″ = −1/x², y‴ = 2/x³, y⁗ = −6/x⁴: the pattern is (−1)ⁿ⁻¹(n − 1)!/xⁿ.', '{"0": "Gives −1/x for n = 1.", "1": "The signs alternate.", "3": "Gives −1/x for n = 1."}'),
  ('MTH-0695', 'Further differentiation', 'Higher derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If y = a cos x + b sin x, then y″ + y equals:', '["2y", "0", "−2y", "a + b"]', 1, 'y″ = −a cos x − b sin x = −y, so y″ + y = 0.', '{"0": "y″ = −y, not y.", "2": "y″ + y cancels; it is not doubled.", "3": "The constants do not survive."}'),
  ('MTH-0696', 'Further differentiation', 'Higher derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.8)', 'If x = t² and y = t³, then d²y/dx² is:', '["3/(4t)", "3t/2", "3/2", "6t"]', 0, 'dy/dx = 3t²/(2t) = 3t/2. Then d²y/dx² = d/dt(3t/2) ÷ dx/dt = (3/2)/(2t) = 3/(4t).', '{"1": "That is dy/dx.", "2": "Differentiated 3t/2 by t without dividing by dx/dt.", "3": "That is d²y/dt²."}'),
  ('MTH-0697', 'Further differentiation', 'Increasing and decreasing functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9)', 'A function is increasing on an interval where:', '["f′(x) < 0", "f′(x) = 0", "f″(x) > 0", "f′(x) > 0"]', 3, 'A positive slope means f rises as x increases.', '{"0": "That makes it decreasing.", "1": "That marks a stationary point.", "2": "That is about concavity, not increase."}'),
  ('MTH-0698', 'Further differentiation', 'Increasing and decreasing functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9)', 'On which interval is f(x) = x² − 4x + 1 decreasing?', '["x > 2", "x < −2", "x < 2", "All real x"]', 2, 'f′(x) = 2x − 4 < 0 when x < 2.', '{"0": "There f′ > 0, so f increases.", "1": "The turning point is at x = 2, not −2.", "3": "A parabola increases on one side."}'),
  ('MTH-0699', 'Further differentiation', 'Increasing and decreasing functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9)', 'The function f(x) = x³ − 3x is decreasing on:', '["x < −1", "−1 < x < 1", "x > 1", "x > 0"]', 1, 'f′(x) = 3x² − 3 = 3(x − 1)(x + 1) < 0 when −1 < x < 1.', '{"0": "There f′ > 0.", "2": "There f′ > 0.", "3": "f′ > 0 for x > 1."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0700', 'Further differentiation', 'Increasing and decreasing functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9.1)', 'The stationary points of f(x) = 2x³ − 9x² + 12x are at:', '["x = 1 and x = 2", "x = −1 and x = −2", "x = 0 and x = 3", "x = 2 and x = 3"]', 0, 'f′(x) = 6x² − 18x + 12 = 6(x − 1)(x − 2) = 0.', '{"1": "Signs of the roots reversed.", "2": "f′(0) = 12, not 0.", "3": "f′(3) = 12, not 0."}'),
  ('MTH-0701', 'Further differentiation', 'Increasing and decreasing functions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9.1)', 'Which statement about f(x) = x³ is true?', '["x = 0 is a local minimum", "x = 0 is a stationary point but not an extremum", "x = 0 is a local maximum", "f has no stationary point"]', 1, 'f′(x) = 3x² = 0 at x = 0, but f′ ≥ 0 on both sides, so f keeps increasing: a point of inflexion, not an extremum.', '{"0": "f(x) < 0 just left of 0.", "2": "f(x) > 0 just right of 0.", "3": "f′(0) = 0, so x = 0 is stationary."}'),
  ('MTH-0702', 'Further differentiation', 'Increasing and decreasing functions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.9.2)', 'A critical point of f(x) = |x − 2| is at:', '["x = 0, where f′ = 0", "x = 2, where f′ = 0", "There is no critical point", "x = 2, where f′ does not exist"]', 3, 'A critical point is where f′ = 0 or f′ does not exist. |x − 2| has a corner at x = 2.', '{"0": "f′(0) = −1.", "1": "At a corner f′ does not exist; it is not 0.", "2": "x = 2 is critical because f′ fails to exist there."}'),
  ('MTH-0703', 'Further differentiation', 'Maxima and minima', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10.4)', 'If f′(c) = 0 and f″(c) < 0, then at x = c, f has a:', '["local maximum", "local minimum", "point of inflexion", "zero"]', 0, 'Second derivative test: f″ < 0 means the curve is concave down, so c is a local maximum.', '{"1": "That needs f″(c) > 0.", "2": "The test gives an extremum when f″(c) ≠ 0.", "3": "f′(c) = 0 says nothing about f(c)."}'),
  ('MTH-0704', 'Further differentiation', 'Maxima and minima', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10.4)', 'The minimum value of f(x) = x² − 6x + 13 is:', '["3", "13", "4", "0"]', 2, 'f′ = 2x − 6 = 0 at x = 3; f(3) = 9 − 18 + 13 = 4. f″ = 2 > 0, so it is a minimum.', '{"0": "That is where the minimum occurs, not its value.", "1": "That is f(0).", "3": "The parabola never reaches 0."}'),
  ('MTH-0705', 'Further differentiation', 'Maxima and minima', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10.4)', 'The local maximum value of f(x) = x³ − 3x² + 4 is:', '["0", "2", "−6", "4"]', 3, 'f′ = 3x² − 6x = 3x(x − 2) = 0 at x = 0, 2. f″ = 6x − 6: f″(0) = −6 < 0, so x = 0 is the maximum, f(0) = 4.', '{"0": "That is the local minimum value, f(2) = 0.", "1": "That is where the minimum occurs.", "2": "That is f″(0), which only shows that x = 0 is a maximum."}'),
  ('MTH-0706', 'Further differentiation', 'Maxima and minima', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10.3)', 'The absolute maximum of f(x) = x³ − 3x on the interval [0, 2] is:', '["0", "−2", "2", "4"]', 2, 'Critical point in the interval: x = 1, f(1) = −2. Endpoints: f(0) = 0, f(2) = 2. The largest is 2.', '{"0": "f(0) = 0 is smaller than f(2).", "1": "That is the absolute minimum.", "3": "That is f(2) doubled; f(2) = 8 − 6 = 2."}'),
  ('MTH-0707', 'Further differentiation', 'Maxima and minima', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10.4)', 'f(x) = x + 1/x (x > 0) has a minimum value of:', '["1", "2", "0", "4"]', 1, 'f′ = 1 − 1/x² = 0 at x = 1; f″ = 2/x³ > 0, so x = 1 gives the minimum f(1) = 2.', '{"0": "That is where the minimum occurs.", "2": "x + 1/x > 0 for x > 0.", "3": "f(1) = 1 + 1 = 2."}'),
  ('MTH-0708', 'Further differentiation', 'Maxima and minima', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.10)', 'The function f(x) = x e^(−x) has its maximum at:', '["x = 1", "x = 0", "x = −1", "x = e"]', 0, 'f′ = e^(−x)(1 − x) = 0 at x = 1, and f′ changes from positive to negative there.', '{"1": "f′(0) = 1, not 0.", "2": "f′(−1) = 2e, not 0.", "3": "f′(e) ≠ 0."}'),
  ('MTH-0709', 'Further differentiation', 'Linearization and differentials', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.11.1)', 'The linearization of f(x) = √x at x = 4 is:', '["L(x) = 2 + (x − 4)/2", "L(x) = 4 + (x − 4)/4", "L(x) = 2 + (x − 4)/4", "L(x) = (x − 4)/4"]', 2, 'L(x) = f(4) + f′(4)(x − 4) = 2 + (1/4)(x − 4), since f′(x) = 1/(2√x).', '{"0": "f′(4) = 1/4, not 1/2.", "1": "f(4) = 2, not 4.", "3": "The term f(4) is missing."}'),
  ('MTH-0710', 'Further differentiation', 'Linearization and differentials', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.12.1)', 'Using differentials, √26 is approximately:', '["5.1", "5.2", "5.01", "5.5"]', 0, 'With y = √x, x = 25, dx = 1: dy = dx/(2√x) = 1/10, so √26 ≈ 5 + 0.1 = 5.1.', '{"1": "dy = 1/10, not 1/5.", "2": "dy = 1/10, not 1/100.", "3": "√26 is only a little above √25 = 5."}'),
  ('MTH-0711', 'Further differentiation', 'Linearization and differentials', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.12)', 'If y = x³, x = 2 and dx = 0.1, then dy is:', '["1.261", "0.12", "0.3", "1.2"]', 3, 'dy = 3x² dx = 3(4)(0.1) = 1.2.', '{"0": "That is Δy = 2.1³ − 2³, the exact change.", "1": "3x², not 3x, multiplies dx.", "2": "x² = 4 was left out."}'),
  ('MTH-0712', 'Further differentiation', 'Linearization and differentials', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.13)', 'For y = x² with x = 3 and Δx = 0.1, the error Δy − dy is:', '["0.6", "0.01", "0.61", "0.1"]', 1, 'dy = 2x dx = 0.6. Δy = 3.1² − 9 = 0.61. Error = 0.61 − 0.6 = 0.01 (equal to (Δx)²).', '{"0": "That is dy.", "2": "That is Δy.", "3": "That is Δx."}'),
  ('MTH-0713', 'Further differentiation', 'Linearization and differentials', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.13)', 'The side of a cube is measured with a possible error of 1%. The approximate percentage error in its volume is:', '["3%", "1%", "2%", "6%"]', 0, 'V = s³, so dV/V = 3 ds/s = 3 × 1% = 3%.', '{"1": "The volume error is not the same as the side error.", "2": "That would be for area, s².", "3": "The factor is the power 3, not 6."}'),
  ('MTH-0714', 'Further differentiation', 'Linearization and differentials', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.13)', 'The radius of a circle is measured with a 2% error. The approximate percentage error in its area is:', '["2%", "4%", "π × 2%", "8%"]', 1, 'A = πr², so dA/A = 2 dr/r = 4%.', '{"0": "Area depends on r², which doubles the relative error.", "2": "π cancels in the ratio dA/A.", "3": "Squared the error instead of doubling it."}'),
  ('MTH-0715', 'Further differentiation', 'Linearization and differentials', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.11)', 'Using the tangent line at x = 0, sin(0.02) is approximately:', '["0.98", "1.02", "0.02", "0.0004"]', 2, 'Linearization of sin x at 0 is L(x) = x, so sin 0.02 ≈ 0.02.', '{"0": "That is closer to cos 0.02.", "1": "sin x near 0 is near 0, not 1.", "3": "That is (0.02)²."}'),
  ('MTH-0716', 'Further differentiation', 'Applications of extrema', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.14)', 'Two positive numbers add up to 20. The largest possible value of their product is:', '["99", "96", "200", "100"]', 3, 'P = x(20 − x); P′ = 20 − 2x = 0 at x = 10, giving P = 100.', '{"0": "That is 9 × 11, not the maximum.", "1": "That is 8 × 12.", "2": "That doubles the maximum; 10 × 10 = 100."}'),
  ('MTH-0717', 'Further differentiation', 'Applications of extrema', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.14)', 'A rectangle has perimeter 40 cm. Its greatest possible area is:', '["100 cm²", "96 cm²", "400 cm²", "64 cm²"]', 0, 'Sides x and 20 − x; A = x(20 − x) is greatest at x = 10, a square of side 10, so A = 100 cm².', '{"1": "That is for sides 8 and 12.", "2": "That uses side 20.", "3": "That is for sides 4 and 16."}'),
  ('MTH-0718', 'Further differentiation', 'Applications of extrema', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.14)', 'An open box is made from a 12 cm × 12 cm square sheet by cutting equal squares of side x from each corner and folding up the sides. The volume is greatest when x is:', '["3 cm", "2 cm", "4 cm", "6 cm"]', 1, 'V = x(12 − 2x)². V′ = (12 − 2x)(12 − 6x) = 0 gives x = 2 or x = 6; x = 6 leaves no base, so x = 2 (V = 128 cm³).', '{"0": "V(3) = 108 < 128.", "2": "V(4) = 64.", "3": "At x = 6 the base vanishes and V = 0."}'),
  ('MTH-0719', 'Further differentiation', 'Applications of extrema', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 2 Further Differentiation (§2.14)', 'A farmer fences three sides of a rectangular field with 100 m of wire; the fourth side is a straight river bank. The greatest area that can be enclosed is:', '["625 m²", "2500 m²", "1250 m²", "800 m²"]', 2, 'Sides x, x and 100 − 2x. A = x(100 − 2x); A′ = 100 − 4x = 0 at x = 25, so A = 25 × 50 = 1250 m².', '{"0": "That is a square of side 25 with four sides fenced.", "1": "That would need the long side 100 m and width 25 m.", "3": "That is for x = 10 (sides 10, 10 and 80)."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0720', 'Integration', 'Indefinite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.1)', '∫ x⁴ dx equals:', '["4x³ + c", "x⁵ + c", "x⁴/4 + c", "x⁵/5 + c"]', 3, 'Raise the power by one and divide by the new power.', '{"0": "That is the derivative.", "1": "The division by 5 is missing.", "2": "The power must go up to 5."}'),
  ('MTH-0721', 'Integration', 'Indefinite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ (1/x) dx, for x > 0, equals:', '["−1/x² + c", "x⁰/0 + c", "1/x² + c", "ln x + c"]', 3, 'The power rule fails for n = −1; the antiderivative of 1/x is ln|x|.', '{"0": "That is the derivative of 1/x.", "1": "Division by 0 is undefined.", "2": "Its derivative is −2/x³."}'),
  ('MTH-0722', 'Integration', 'Indefinite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ cos x dx equals:', '["−sin x + c", "sin x + c", "−cos x + c", "tan x + c"]', 1, 'd/dx sin x = cos x.', '{"0": "The derivative of −sin x is −cos x.", "2": "That is the integral of sin x.", "3": "The derivative of tan x is sec²x."}'),
  ('MTH-0723', 'Integration', 'Indefinite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ sec²x dx equals:', '["tan x + c", "sec x + c", "sec³x/3 + c", "−cot x + c"]', 0, 'd/dx tan x = sec²x.', '{"1": "d/dx sec x = sec x tan x.", "2": "The power rule does not apply to a trig function like this.", "3": "−cot x is the integral of cosec²x."}'),
  ('MTH-0724', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.1)', '∫ (3x² − 4x + 5) dx equals:', '["6x − 4 + c", "x³ − 4x² + 5x + c", "x³ − 2x² + 5x + c", "3x³ − 2x² + 5 + c"]', 2, 'Term by term: 3·x³/3 − 4·x²/2 + 5x.', '{"0": "That is the derivative.", "1": "4x integrates to 2x², not 4x².", "3": "The coefficient 3 should divide out, and 5 integrates to 5x."}'),
  ('MTH-0725', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.1)', '∫ √x dx equals:', '["(3/2)x^(3/2) + c", "1/(2√x) + c", "x^(3/2) + c", "(2/3)x^(3/2) + c"]', 3, 'x^(1/2) integrates to x^(3/2)/(3/2) = (2/3)x^(3/2).', '{"0": "Dividing by 3/2 means multiplying by 2/3.", "1": "That is the derivative.", "2": "The division by 3/2 is missing."}'),
  ('MTH-0726', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ e^(4x) dx equals:', '["4e^(4x) + c", "e^(4x)/4 + c", "e^(4x) + c", "e^(4x+1)/(4x + 1) + c"]', 1, 'Since d/dx e^(4x) = 4e^(4x), divide by 4.', '{"0": "That is the derivative.", "2": "The factor 1/4 is missing.", "3": "The power rule does not apply to eˣ."}'),
  ('MTH-0727', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ aˣ dx (a > 0, a ≠ 1) equals:', '["aˣ/ln a + c", "aˣ ln a + c", "aˣ⁺¹/(x + 1) + c", "aˣ + c"]', 0, 'd/dx aˣ = aˣ ln a, so divide by ln a.', '{"1": "That is the derivative.", "2": "The power rule does not apply.", "3": "Only eˣ integrates to itself."}'),
  ('MTH-0728', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.1)', '∫ (x + 1)²/x dx (x > 0) equals:', '["(x + 1)³/(3x) + c", "x²/2 + 2x + c", "x²/2 + 2x + ln x + c", "x + 2 + 1/x + c"]', 2, '(x + 1)²/x = x + 2 + 1/x, which integrates term by term.', '{"0": "A quotient cannot be integrated part by part like this.", "1": "The 1/x term gives ln x.", "3": "That is the integrand, not its integral."}'),
  ('MTH-0729', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ 1/(1 + x²) dx equals:', '["tan⁻¹x + c", "ln(1 + x²) + c", "sin⁻¹x + c", "−1/(1 + x²) + c"]', 0, 'd/dx tan⁻¹x = 1/(1 + x²).', '{"1": "Its derivative is 2x/(1 + x²).", "2": "Its derivative is 1/√(1 − x²).", "3": "Its derivative is 2x/(1 + x²)²."}'),
  ('MTH-0730', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ 1/√(1 − x²) dx equals:', '["cos⁻¹x + c", "sin⁻¹x + c", "tan⁻¹x + c", "√(1 − x²) + c"]', 1, 'd/dx sin⁻¹x = 1/√(1 − x²).', '{"0": "d/dx cos⁻¹x = −1/√(1 − x²).", "2": "That needs 1/(1 + x²).", "3": "Its derivative is −x/√(1 − x²)."}'),
  ('MTH-0731', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ sin²x dx equals:', '["sin³x/3 + c", "x/2 + (sin 2x)/4 + c", "x/2 − (sin 2x)/4 + c", "−cos²x + c"]', 2, 'sin²x = (1 − cos 2x)/2, which integrates to x/2 − sin 2x/4.', '{"0": "The power rule does not apply to sin x.", "1": "That is the integral of cos²x.", "3": "Its derivative is 2 sin x cos x."}'),
  ('MTH-0732', 'Integration', 'Indefinite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ tan²x dx equals:', '["tan³x/3 + c", "sec²x + c", "tan x + x + c", "tan x − x + c"]', 3, 'tan²x = sec²x − 1.', '{"0": "The power rule does not apply.", "1": "That is the derivative of tan x.", "2": "The 1 is subtracted, not added."}'),
  ('MTH-0733', 'Integration', 'Indefinite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1.2)', '∫ 1/(1 + cos x) dx equals:', '["ln(1 + cos x) + c", "cot(x/2) + c", "tan(x/2) + c", "x + sec x + c"]', 2, '1 + cos x = 2cos²(x/2), so the integrand is (1/2)sec²(x/2), whose integral is tan(x/2).', '{"0": "Its derivative is −sin x/(1 + cos x).", "1": "d/dx cot(x/2) = −(1/2)cosec²(x/2).", "3": "Its derivative is 1 + sec x tan x."}'),
  ('MTH-0734', 'Integration', 'Indefinite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.1)', 'If f′(x) = 2x + 3 and f(0) = 4, then f(x) is:', '["x² + 3x", "2x² + 3x + 4", "x² + 4", "x² + 3x + 4"]', 3, 'f(x) = x² + 3x + c, and f(0) = c = 4.', '{"0": "The constant is fixed by f(0) = 4.", "1": "2x integrates to x².", "2": "The 3x term is missing."}'),
  ('MTH-0735', 'Integration', 'Integration by substitution', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ (2x + 1)⁵ dx equals:', '["(2x + 1)⁶/6 + c", "(2x + 1)⁶/12 + c", "10(2x + 1)⁴ + c", "(2x + 1)⁶/2 + c"]', 1, 'Let u = 2x + 1, du = 2 dx: ∫u⁵ du/2 = u⁶/12.', '{"0": "The factor 1/2 from du = 2 dx is missing.", "2": "That is the derivative.", "3": "The division by 6 is missing."}'),
  ('MTH-0736', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ 2x(x² + 1)³ dx equals:', '["(x² + 1)⁴/4 + c", "(x² + 1)⁴/2 + c", "x²(x² + 1)⁴/4 + c", "6x(x² + 1)² + c"]', 0, 'u = x² + 1, du = 2x dx: ∫u³ du = u⁴/4.', '{"1": "The 2x is exactly du; there is no extra factor.", "2": "x² cannot be taken outside.", "3": "That is a derivative, not an integral."}'),
  ('MTH-0737', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ f′(x)/f(x) dx equals:', '["ln|f(x)| + c", "f(x)²/2 + c", "1/f(x) + c", "ln|f′(x)| + c"]', 0, 'With u = f(x), du = f′(x) dx, so the integral is ∫du/u = ln|u|.', '{"1": "That is ∫f f′ dx.", "2": "Its derivative is −f′/f².", "3": "The log is of f, not of f′."}'),
  ('MTH-0738', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ tan x dx equals:', '["sec²x + c", "ln|cos x| + c", "ln|sec x| + c", "−ln|sec x| + c"]', 2, 'tan x = sin x/cos x = −(−sin x)/cos x, so the integral is −ln|cos x| = ln|sec x|.', '{"0": "That is the derivative of tan x.", "1": "The sign is wrong: d/dx ln|cos x| = −tan x.", "3": "The sign is wrong."}'),
  ('MTH-0739', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ (2x + 3)/(x² + 3x + 5) dx equals:', '["(x² + 3x + 5)²/2 + c", "ln|x² + 3x + 5| + c", "1/(x² + 3x + 5) + c", "2 ln|x² + 3x + 5| + c"]', 1, 'The numerator is the derivative of the denominator, so the integral is ln|denominator|.', '{"0": "That is ∫(2x + 3)(x² + 3x + 5) dx.", "2": "Its derivative is −(2x + 3)/(x² + 3x + 5)².", "3": "There is no factor 2."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0740', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ sin⁴x cos x dx equals:', '["cos⁵x/5 + c", "−sin⁵x/5 + c", "4 sin³x cos²x + c", "sin⁵x/5 + c"]', 3, 'u = sin x, du = cos x dx: ∫u⁴ du = u⁵/5.', '{"0": "The power belongs to sin x.", "1": "The sign is wrong.", "2": "That is not an integral."}'),
  ('MTH-0741', 'Integration', 'Integration by substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ x e^(x²) dx equals:', '["e^(x²) + c", "2x e^(x²) + c", "x² e^(x²)/2 + c", "e^(x²)/2 + c"]', 3, 'u = x², du = 2x dx: (1/2)∫eᵘ du = e^(x²)/2.', '{"0": "The factor 1/2 is missing.", "1": "That is the derivative of e^(x²).", "2": "x² cannot be taken outside like that."}'),
  ('MTH-0742', 'Integration', 'Integration by substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ (ln x)/x dx equals:', '["ln(ln x) + c", "(ln x)²/2 + c", "1/x² + c", "x ln x − x + c"]', 1, 'u = ln x, du = dx/x: ∫u du = u²/2.', '{"0": "That is ∫dx/(x ln x).", "2": "Its derivative is −2/x³.", "3": "That is ∫ln x dx."}'),
  ('MTH-0743', 'Integration', 'Integration by substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ eˣ/(1 + e²ˣ) dx equals:', '["tan⁻¹(eˣ) + c", "ln(1 + e²ˣ) + c", "eˣ tan⁻¹x + c", "ln(1 + eˣ) + c"]', 0, 'u = eˣ, du = eˣ dx: ∫du/(1 + u²) = tan⁻¹u.', '{"1": "Its derivative is 2e²ˣ/(1 + e²ˣ).", "2": "Its derivative is eˣ tan⁻¹x + eˣ/(1 + x²).", "3": "Its derivative is eˣ/(1 + eˣ)."}'),
  ('MTH-0744', 'Integration', 'Integration by substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ 1/(x ln x) dx (x > 1) equals:', '["(ln x)²/2 + c", "ln x/x + c", "ln(ln x) + c", "1/ln x + c"]', 2, 'u = ln x, du = dx/x: ∫du/u = ln u.', '{"0": "That is ∫(ln x)/x dx.", "1": "Its derivative is (1 − ln x)/x².", "3": "Its derivative is −1/(x(ln x)²)."}'),
  ('MTH-0745', 'Integration', 'Integration by substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.2)', '∫ sec x dx equals:', '["sec x tan x + c", "ln|sec x| + c", "tan x + c", "ln|sec x + tan x| + c"]', 3, 'Multiply by (sec x + tan x)/(sec x + tan x): the numerator becomes the derivative of the denominator.', '{"0": "That is the derivative of sec x.", "1": "That is ∫tan x dx.", "2": "That is ∫sec²x dx."}'),
  ('MTH-0746', 'Integration', 'Trigonometric substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.3)', 'For ∫ dx/√(a² − x²), the suitable substitution is:', '["x = a tan θ", "x = a sin θ", "x = a sec θ", "x = a² sin θ"]', 1, 'a² − a²sin²θ = a²cos²θ, which removes the root.', '{"0": "That suits a² + x².", "2": "That suits x² − a².", "3": "The coefficient must be a, not a²."}'),
  ('MTH-0747', 'Integration', 'Trigonometric substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.3)', '∫ dx/√(9 − x²) equals:', '["sin⁻¹(x/3) + c", "(1/3) sin⁻¹(x/3) + c", "sin⁻¹(3x) + c", "(1/3) tan⁻¹(x/3) + c"]', 0, '∫dx/√(a² − x²) = sin⁻¹(x/a); here a = 3.', '{"1": "The 1/a factor belongs to the tan⁻¹ formula, not this one.", "2": "The argument is x/a.", "3": "That is ∫dx/(9 + x²)."}'),
  ('MTH-0748', 'Integration', 'Trigonometric substitution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.3)', '∫ dx/(4 + x²) equals:', '["tan⁻¹(x/2) + c", "(1/4) tan⁻¹(x/4) + c", "(1/2) tan⁻¹(x/2) + c", "ln(4 + x²) + c"]', 2, '∫dx/(a² + x²) = (1/a) tan⁻¹(x/a), with a = 2.', '{"0": "The factor 1/a is missing.", "1": "a = 2, not 4.", "3": "Its derivative is 2x/(4 + x²)."}'),
  ('MTH-0749', 'Integration', 'Trigonometric substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.3)', '∫ √(1 − x²) dx equals:', '["(2/3)(1 − x²)^(3/2) + c", "(1/2)[x√(1 − x²) + sin⁻¹x] + c", "x√(1 − x²) + c", "(1/2) sin⁻¹x + c"]', 1, 'With x = sin θ: ∫cos²θ dθ = θ/2 + sin 2θ/4 = (1/2)(sin⁻¹x + x√(1 − x²)).', '{"0": "Its derivative is −2x√(1 − x²).", "2": "Only one of the two terms, without the 1/2.", "3": "The x√(1 − x²) term is missing."}'),
  ('MTH-0750', 'Integration', 'Trigonometric substitution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.3)', '∫ dx/√(x² + 4) equals:', '["sin⁻¹(x/2) + c", "(1/2) tan⁻¹(x/2) + c", "√(x² + 4) + c", "ln|x + √(x² + 4)| + c"]', 3, 'With x = 2 tan θ, the integral becomes ∫sec θ dθ = ln|sec θ + tan θ|, which is ln|x + √(x² + 4)| plus a constant.', '{"0": "That needs 4 − x² under the root.", "1": "That is ∫dx/(x² + 4), without a root.", "2": "Its derivative is x/√(x² + 4)."}'),
  ('MTH-0751', 'Integration', 'Integration by parts', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', 'The formula for integration by parts is:', '["∫u dv = uv − ∫v du", "∫u dv = uv + ∫v du", "∫u dv = u′v′", "∫u dv = ∫u dx · ∫v dx"]', 0, 'It comes from the product rule d(uv) = u dv + v du.', '{"1": "The second term is subtracted.", "2": "That multiplies two derivatives; it does not come from the product rule.", "3": "The integral of a product is not the product of integrals."}'),
  ('MTH-0752', 'Integration', 'Integration by parts', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ x eˣ dx equals:', '["eˣ(x + 1) + c", "x²eˣ/2 + c", "eˣ(x − 1) + c", "xeˣ + c"]', 2, 'u = x, dv = eˣ dx: xeˣ − ∫eˣ dx = eˣ(x − 1).', '{"0": "The second term is subtracted.", "1": "Only x was integrated.", "3": "The −∫eˣ dx term is missing."}'),
  ('MTH-0753', 'Integration', 'Integration by parts', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ ln x dx equals:', '["1/x + c", "x ln x − x + c", "(ln x)²/2 + c", "x ln x + c"]', 1, 'u = ln x, dv = dx: x ln x − ∫x·(1/x) dx = x ln x − x.', '{"0": "That is the derivative.", "2": "That is ∫(ln x)/x dx.", "3": "The −x term is missing."}'),
  ('MTH-0754', 'Integration', 'Integration by parts', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ x cos x dx equals:', '["x sin x − cos x + c", "−x sin x + cos x + c", "(x²/2) sin x + c", "x sin x + cos x + c"]', 3, 'u = x, dv = cos x dx: x sin x − ∫sin x dx = x sin x + cos x.', '{"0": "−∫sin x dx = +cos x.", "1": "The first term is +x sin x.", "2": "Only x was integrated."}'),
  ('MTH-0755', 'Integration', 'Integration by parts', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ x² eˣ dx equals:', '["eˣ(x² − 2x + 2) + c", "eˣ(x² + 2x + 2) + c", "eˣ(x² − 2x) + c", "x³eˣ/3 + c"]', 0, 'Parts twice: x²eˣ − 2∫xeˣ dx = x²eˣ − 2eˣ(x − 1).', '{"1": "The signs alternate.", "2": "The +2 from the second step is missing.", "3": "Only x² was integrated."}'),
  ('MTH-0756', 'Integration', 'Integration by parts', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ tan⁻¹x dx equals:', '["x tan⁻¹x + (1/2) ln(1 + x²) + c", "1/(1 + x²) + c", "x tan⁻¹x − (1/2) ln(1 + x²) + c", "x tan⁻¹x − ln(1 + x²) + c"]', 2, 'u = tan⁻¹x, dv = dx: x tan⁻¹x − ∫x/(1 + x²) dx = x tan⁻¹x − (1/2)ln(1 + x²).', '{"0": "The second term is subtracted.", "1": "That is the derivative.", "3": "∫x/(1 + x²) dx carries a factor 1/2."}'),
  ('MTH-0757', 'Integration', 'Integration by parts', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ eˣ[f(x) + f′(x)] dx equals:', '["eˣ f′(x) + c", "eˣ[f(x) − f′(x)] + c", "eˣ f(x) + c", "eˣ + f(x) + c"]', 2, 'd/dx[eˣ f(x)] = eˣ f(x) + eˣ f′(x).', '{"0": "Its derivative is eˣ[f′ + f″].", "1": "Its derivative is eˣ[f − f″].", "3": "Its derivative is eˣ + f′."}'),
  ('MTH-0758', 'Integration', 'Integration by parts', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.4)', '∫ eˣ(sin x + cos x) dx equals:', '["eˣ cos x + c", "eˣ(sin x − cos x) + c", "−eˣ cos x + c", "eˣ sin x + c"]', 3, 'Here f = sin x and f′ = cos x, so the integral is eˣ sin x.', '{"0": "Its derivative is eˣ(cos x − sin x).", "1": "Its derivative is 2eˣ sin x.", "2": "Its derivative is eˣ(sin x − cos x)."}'),
  ('MTH-0759', 'Integration', 'Integration using partial fractions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.5)', '∫ dx/[(x − 1)(x + 1)] equals:', '["ln|(x − 1)(x + 1)| + c", "(1/2) ln|(x − 1)/(x + 1)| + c", "(1/2) ln|(x + 1)/(x − 1)| + c", "ln|(x − 1)/(x + 1)| + c"]', 1, '1/[(x − 1)(x + 1)] = (1/2)[1/(x − 1) − 1/(x + 1)].', '{"0": "The fractions are subtracted, with factor 1/2.", "2": "The fraction is upside down.", "3": "The factor 1/2 is missing."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0760', 'Integration', 'Integration using partial fractions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.5)', '∫ dx/(x² − 9) equals:', '["(1/6) ln|(x − 3)/(x + 3)| + c", "(1/3) ln|(x − 3)/(x + 3)| + c", "(1/6) ln|(x + 3)/(x − 3)| + c", "(1/3) tan⁻¹(x/3) + c"]', 0, '∫dx/(x² − a²) = (1/2a) ln|(x − a)/(x + a)|, with 2a = 6.', '{"1": "The factor is 1/(2a) = 1/6.", "2": "The fraction is upside down.", "3": "That is ∫dx/(x² + 9)."}'),
  ('MTH-0761', 'Integration', 'Integration using partial fractions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.5)', '∫ (x + 5)/[(x + 1)(x + 2)] dx equals:', '["3 ln|x + 1| − 4 ln|x + 2| + c", "4 ln|x + 1| + 3 ln|x + 2| + c", "4 ln|x + 1| − 3 ln|x + 2| + c", "ln|(x + 1)(x + 2)| + c"]', 2, '(x + 5)/[(x + 1)(x + 2)] = A/(x + 1) + B/(x + 2): x = −1 gives A = 4, x = −2 gives B = −3.', '{"0": "A and B swapped.", "1": "B = −3, not +3.", "3": "That needs A = B = 1, which would make the numerator 2x + 3."}'),
  ('MTH-0762', 'Integration', 'Integration using partial fractions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.5)', '∫ x/(x + 1) dx equals:', '["x − ln|x + 1| + c", "ln|x + 1| + c", "x + ln|x + 1| + c", "x²/(2(x + 1)) + c"]', 0, 'x/(x + 1) = 1 − 1/(x + 1).', '{"1": "The leading 1 from the division is missing.", "2": "The log term is subtracted.", "3": "A quotient is not integrated this way."}'),
  ('MTH-0763', 'Integration', 'Integration using partial fractions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.5)', '∫ dx/[x(x + 1)] equals:', '["ln|x(x + 1)| + c", "ln|(x + 1)/x| + c", "1/(x + 1) + c", "ln|x/(x + 1)| + c"]', 3, '1/[x(x + 1)] = 1/x − 1/(x + 1).', '{"0": "The second log is subtracted.", "1": "The fraction is upside down.", "2": "Its derivative is −1/(x + 1)²."}'),
  ('MTH-0764', 'Integration', 'Definite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀² 3x² dx equals:', '["12", "8", "6", "24"]', 1, '[x³]₀² = 8.', '{"0": "That is 3x² at x = 2.", "2": "That integrates 3x² as 3x.", "3": "3 was not cancelled."}'),
  ('MTH-0765', 'Integration', 'Definite integrals', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀^π sin x dx equals:', '["0", "1", "2", "−2"]', 2, '[−cos x]₀^π = −(−1) − (−1) = 2.', '{"0": "sin x ≥ 0 on [0, π], so the area does not cancel.", "1": "That is ∫₀^(π/2).", "3": "The sign is wrong."}'),
  ('MTH-0766', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₁^e (1/x) dx equals:', '["e", "e − 1", "0", "1"]', 3, '[ln x]₁^e = 1 − 0.', '{"0": "ln e = 1.", "1": "The integral of 1/x is ln x, not x.", "2": "ln 1 = 0, ln e = 1."}'),
  ('MTH-0767', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀¹ eˣ dx equals:', '["e", "e − 1", "1", "e + 1"]', 1, '[eˣ]₀¹ = e − 1.', '{"0": "e⁰ = 1 must be subtracted.", "2": "That is e⁰, the lower-limit value alone.", "3": "The lower-limit value is subtracted, not added."}'),
  ('MTH-0768', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀^(π/4) sec²x dx equals:', '["1", "√2", "2", "π/4"]', 0, '[tan x]₀^(π/4) = 1 − 0.', '{"1": "That is sec(π/4).", "2": "That is sec²(π/4).", "3": "That is the length of the interval, the integral of 1."}'),
  ('MTH-0769', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀¹ dx/(1 + x²) equals:', '["π/4", "π/2", "1", "ln 2"]', 0, '[tan⁻¹x]₀¹ = π/4.', '{"1": "tan⁻¹1 = π/4.", "2": "1 is the upper limit, not tan⁻¹1.", "3": "That is ∫₀¹ 2x/(1 + x²) dx."}'),
  ('MTH-0770', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', '∫₀³ |x − 1| dx equals:', '["3/2", "5/2", "2", "3"]', 1, 'Split at x = 1: ∫₀¹(1 − x) dx + ∫₁³(x − 1) dx = 1/2 + 2 = 5/2.', '{"0": "That is ∫₀³(x − 1) dx, ignoring the absolute value.", "2": "Only the part from 1 to 3.", "3": "That is |3 − 1| + |0 − 1|, the end values, not the area."}'),
  ('MTH-0771', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', 'If ∫₀² f(x) dx = 5 and ∫₀² g(x) dx = 3, then ∫₀² [2f(x) − g(x)] dx equals:', '["2", "13", "7", "10"]', 2, 'Linearity: 2(5) − 3 = 7.', '{"0": "The 2 multiplies f''s integral.", "1": "That is 2(5) + 3.", "3": "That is 2 × 5 with g left out."}'),
  ('MTH-0772', 'Integration', 'Definite integrals', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', '∫ₐᵇ f(x) dx + ∫ᵇₐ f(x) dx equals:', '["2∫ₐᵇ f(x) dx", "∫ₐᵇ 2f(x) dx", "b − a", "0"]', 3, 'Swapping the limits changes the sign, so the two cancel.', '{"0": "∫ᵇₐ = −∫ₐᵇ, so they cancel.", "1": "This equals 2∫ₐᵇ f dx, the same slip of treating ∫ᵇₐ as ∫ₐᵇ.", "2": "That is ∫ₐᵇ 1 dx, the width of the interval."}'),
  ('MTH-0773', 'Integration', 'Definite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', 'If f is an odd function, then ∫₋ₐᵃ f(x) dx equals:', '["0", "2∫₀ᵃ f(x) dx", "a", "f(a) − f(−a)"]', 0, 'For odd f, the areas on the two sides of 0 are equal and opposite.', '{"1": "That is for an even function.", "2": "The integral does not depend on a alone.", "3": "For odd f, f(a) − f(−a) = 2f(a), which is not the integral."}'),
  ('MTH-0774', 'Integration', 'Definite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', '∫₋₁¹ (x³ + x²) dx equals:', '["0", "4/3", "2/3", "1/3"]', 2, 'x³ is odd and integrates to 0; x² is even: 2∫₀¹x² dx = 2/3.', '{"0": "Only the odd part vanishes.", "1": "Doubled once too many.", "3": "Forgot to double the even part."}'),
  ('MTH-0775', 'Integration', 'Definite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6.1)', '∫₀^(π/2) sin x/(sin x + cos x) dx equals:', '["π/2", "π/4", "1", "0"]', 1, 'Using ∫₀ᵃ f(x) dx = ∫₀ᵃ f(a − x) dx, I equals the same integral with cos x on top. Adding: 2I = ∫₀^(π/2) 1 dx = π/2, so I = π/4.', '{"0": "That is 2I.", "2": "By symmetry the integrand averages 1/2 over an interval of length π/2.", "3": "The integrand is positive on (0, π/2)."}'),
  ('MTH-0776', 'Integration', 'Definite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', 'Using u = x², ∫₀² x e^(x²) dx equals:', '["e⁴ − 1", "(e² − 1)/2", "e⁴/2", "(e⁴ − 1)/2"]', 3, 'u = x², du = 2x dx; limits 0 to 4: (1/2)∫₀⁴ eᵘ du = (e⁴ − 1)/2.', '{"0": "The factor 1/2 is missing.", "1": "The upper limit becomes 4, not 2.", "2": "e⁰ = 1 must be subtracted."}'),
  ('MTH-0777', 'Integration', 'Definite integrals', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.6)', '∫₀¹ x eˣ dx equals:', '["e", "1", "e − 1", "0"]', 1, '[eˣ(x − 1)]₀¹ = 0 − (−1) = 1.', '{"0": "That is [xeˣ]₀¹ alone; the −∫eˣ dx part is missing.", "2": "That is ∫₀¹eˣ dx.", "3": "The lower limit gives −1, which is subtracted."}'),
  ('MTH-0778', 'Integration', 'Area under a curve', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The area between y = x², the x-axis and the lines x = 0 and x = 3 is:', '["27", "3", "18", "9"]', 3, '∫₀³ x² dx = 27/3 = 9.', '{"0": "The division by 3 is missing.", "1": "That is the width of the interval.", "2": "That doubles the correct area."}'),
  ('MTH-0779', 'Integration', 'Area under a curve', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The area enclosed between y = x² and y = x is:', '["1/6", "1/2", "1/3", "5/6"]', 0, 'They meet at x = 0 and 1; area = ∫₀¹(x − x²) dx = 1/2 − 1/3 = 1/6.', '{"1": "That is the area under y = x alone.", "2": "That is the area under y = x² alone.", "3": "Added instead of subtracted."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0780', 'Integration', 'Area under a curve', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The area bounded by y = 4 − x² and the x-axis is:', '["16/3", "8", "32/3", "64/3"]', 2, 'Roots ±2: ∫₋₂²(4 − x²) dx = 2[4x − x³/3]₀² = 2(8 − 8/3) = 32/3.', '{"0": "That is only half of it, from 0 to 2.", "1": "That is the rectangle 4 × 2, not the area under the curve.", "3": "Doubled twice."}'),
  ('MTH-0781', 'Integration', 'Area under a curve', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The total area between y = x³ and the x-axis from x = −1 to x = 1 is:', '["1/2", "0", "1/4", "1"]', 0, 'The signed integral is 0, but area counts both parts as positive: 2∫₀¹x³ dx = 1/2.', '{"1": "That is the signed integral; the area below the axis must be counted as positive.", "2": "That is only one half.", "3": "That doubles the correct area."}'),
  ('MTH-0782', 'Integration', 'Area under a curve', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The area between y = sin x and the x-axis from x = 0 to x = 2π is:', '["0", "2", "4", "2π"]', 2, 'Each arch has area 2: ∫₀^π sin x dx = 2 and the part from π to 2π is below the axis with area 2.', '{"0": "That is the signed integral.", "1": "That is one arch.", "3": "That is the width of the interval."}'),
  ('MTH-0783', 'Integration', 'Area under a curve', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.1)', 'The area bounded by y = 1/x, the x-axis, x = 1 and x = e² is:', '["1", "2", "e²", "e² − 1"]', 1, '∫₁^(e²) dx/x = ln e² = 2.', '{"0": "ln e² = 2.", "2": "The integral of 1/x is ln x.", "3": "That is the width of the interval."}'),
  ('MTH-0784', 'Integration', 'Consumer and producer surplus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.2)', 'The demand function is p = 50 − x and the market price is 30. The consumer surplus is:', '["400", "600", "800", "200"]', 3, 'At p = 30, x₀ = 20. CS = ∫₀²⁰(50 − x) dx − 30 × 20 = (1000 − 200) − 600 = 200.', '{"0": "That forgot the −x² part: 1000 − 600.", "1": "That is p₀x₀, the amount spent.", "2": "That is ∫₀²⁰ D(x) dx, the total consumers would be willing to pay."}'),
  ('MTH-0785', 'Integration', 'Consumer and producer surplus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.2)', 'The supply function is p = 10 + 2x and the market price is 30. The producer surplus is:', '["100", "200", "300", "0"]', 0, 'At p = 30, x₀ = 10. PS = 30 × 10 − ∫₀¹⁰(10 + 2x) dx = 300 − 200 = 100.', '{"1": "That is ∫₀¹⁰ S(x) dx, the least revenue producers would accept.", "2": "That is p₀x₀.", "3": "Producers gain, since many would have sold below the market price."}'),
  ('MTH-0786', 'Integration', 'Consumer and producer surplus', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.2)', 'The market equilibrium point is where:', '["the demand curve meets the x-axis", "the demand and supply curves meet", "consumer surplus is zero", "price is zero"]', 1, 'At equilibrium, quantity demanded equals quantity supplied.', '{"0": "That is where price is zero.", "2": "Consumer surplus is usually positive there.", "3": "Price at equilibrium is positive."}'),
  ('MTH-0787', 'Integration', 'Volume of a solid of revolution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.3)', 'The volume formed by rotating y = f(x), a ≤ x ≤ b, about the x-axis is:', '["∫ₐᵇ y² dx", "2π∫ₐᵇ y dx", "π∫ₐᵇ y² dx", "π∫ₐᵇ y dx"]', 2, 'Each slice is a disc of radius y and thickness dx, with volume πy² dx.', '{"0": "π is missing.", "1": "That resembles the surface-area form 2π∫y ds; a volume needs πy² dx.", "3": "y must be squared."}'),
  ('MTH-0788', 'Integration', 'Volume of a solid of revolution', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.3)', 'The region under y = x from x = 0 to x = 3 is rotated about the x-axis. The volume is:', '["27π", "3π", "9π/2", "9π"]', 3, 'π∫₀³ x² dx = π · 9 = 9π. (A cone of radius 3 and height 3: (1/3)π(9)(3).)', '{"0": "The division by 3 is missing.", "1": "That divides by 3 twice.", "2": "That is π∫₀³ x dx."}'),
  ('MTH-0789', 'Integration', 'Volume of a solid of revolution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.3)', 'The region under y = √x from x = 0 to x = 4 is rotated about the x-axis. The volume is:', '["16π", "(16/3)π", "4π", "8π"]', 3, 'π∫₀⁴ (√x)² dx = π∫₀⁴ x dx = 8π.', '{"0": "Missing the division by 2.", "1": "That is π∫₀⁴ √x dx.", "2": "That halves the correct volume."}'),
  ('MTH-0790', 'Integration', 'Volume of a solid of revolution', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.7.3)', 'Rotating the semicircle y = √(r² − x²), −r ≤ x ≤ r, about the x-axis gives:', '["(2/3)πr³", "(4/3)πr³", "2πr³", "4πr²"]', 1, 'π∫₋ᵣʳ (r² − x²) dx = π(2r³ − 2r³/3) = (4/3)πr³, the volume of a sphere.', '{"0": "That is half of it.", "2": "The −x² term was not integrated: π∫₋ᵣʳ r² dx = 2πr³.", "3": "That is the surface area of the sphere."}'),
  ('MTH-0791', 'Integration', 'Applications of integration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.2)', 'A particle''s velocity is v(t) = 3t² m/s. Its displacement from t = 0 to t = 2 s is:', '["8 m", "12 m", "6 m", "24 m"]', 0, 's = ∫₀² 3t² dt = [t³]₀² = 8 m.', '{"1": "That is v(2).", "2": "That is the acceleration at t = 1 times 2.", "3": "The 3 was kept after integrating: 3 × 8."}'),
  ('MTH-0792', 'Integration', 'Applications of integration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.2)', 'A body starts from rest with acceleration a = 6t m/s². Its velocity at t = 3 s is:', '["18 m/s", "9 m/s", "27 m/s", "54 m/s"]', 2, 'v = ∫6t dt = 3t² (v(0) = 0), so v(3) = 27 m/s.', '{"0": "That is a(3).", "1": "That integrates 6t as t².", "3": "The 1/2 in ∫t dt = t²/2 was dropped."}'),
  ('MTH-0793', 'Integration', 'Applications of integration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.2)', 'A particle moves with v(t) = t − 2 m/s. The total distance travelled from t = 0 to t = 4 s is:', '["0 m", "2 m", "8 m", "4 m"]', 3, 'v < 0 for t < 2 and v > 0 after. Distance = ∫₀⁴|t − 2| dt = 2 + 2 = 4 m. (The displacement is 0.)', '{"0": "That is the displacement; distance counts both directions.", "1": "That is only one part.", "2": "That doubles each part."}'),
  ('MTH-0794', 'Integration', 'Applications of integration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.1)', 'The moment of inertia of a uniform rod of mass M and length L about a perpendicular axis through one end is:', '["ML²/12", "ML²/3", "ML²/2", "ML²"]', 1, 'I = ∫₀ᴸ x²(M/L) dx = (M/L)(L³/3) = ML²/3.', '{"0": "That is about the centre.", "2": "Integrated x² as x³/2.", "3": "That would put all the mass at the far end."}'),
  ('MTH-0795', 'Integration', 'Applications of integration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.4)', 'A drug''s concentration is C(t) mg/L. The total exposure (area under the curve) from t = 0 to t = T is:', '["∫₀ᵀ C(t) dt", "C(T) − C(0)", "C′(T)", "C(T) × T"]', 0, 'AUC adds concentration over time, so it is the integral of C.', '{"1": "That is the change in concentration.", "2": "That is a rate.", "3": "Only right if C is constant."}'),
  ('MTH-0796', 'Integration', 'Applications of integration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 3 Integration (§3.8.4)', 'The concentration of a drug is C(t) = 10e^(−0.2t) mg/L (t in hours). The total exposure from t = 0 to ∞ is:', '["10 mg·h/L", "2 mg·h/L", "50 mg·h/L", "200 mg·h/L"]', 2, '∫₀^∞ 10e^(−0.2t) dt = 10/0.2 = 50.', '{"0": "That is C(0).", "1": "That is 10 × 0.2.", "3": "That divides by 0.05; the decay constant is 0.2."}'),
  ('MTH-0797', 'Differential equations', 'Order and degree', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'The order of the differential equation d²y/dx² + 3(dy/dx)³ + y = 0 is:', '["3", "2", "1", "6"]', 1, 'The order is the highest derivative present, which is d²y/dx².', '{"0": "3 is the power of dy/dx, which affects degree, not order.", "2": "A second derivative is present.", "3": "Order is not a product of numbers in the equation."}'),
  ('MTH-0798', 'Differential equations', 'Order and degree', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'The degree of the differential equation (d²y/dx²)³ + (dy/dx)⁴ − y = 0 is:', '["4", "2", "7", "3"]', 3, 'The degree is the power of the highest-order derivative, d²y/dx², which is 3.', '{"0": "4 is the power of the lower derivative dy/dx.", "1": "2 is the order.", "2": "Powers are not added."}'),
  ('MTH-0799', 'Differential equations', 'Order and degree', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'The order and degree of (dy/dx)² + 5y = x are:', '["order 1, degree 2", "order 2, degree 1", "order 2, degree 2", "order 1, degree 1"]', 0, 'Only dy/dx appears (order 1), and it is squared (degree 2).', '{"1": "Order and degree are swapped.", "2": "There is no second derivative.", "3": "dy/dx is squared."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0800', 'Differential equations', 'Order and degree', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'Which differential equation is of first order and first degree?', '["(dy/dx)² = x + y", "d²y/dx² + y = 0", "dy/dx + xy = eˣ", "(d²y/dx²)² + dy/dx = 0"]', 2, 'Only the first derivative appears, and only to the power 1.', '{"0": "Degree 2.", "1": "Order 2.", "3": "Order 2 and degree 2."}'),
  ('MTH-0801', 'Differential equations', 'Order and degree', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'The degree of the differential equation d²y/dx² = √(1 + (dy/dx)²) is:', '["1", "2", "1/2", "Not defined"]', 1, 'Squaring to remove the root: (d²y/dx²)² = 1 + (dy/dx)². The highest derivative now has power 2.', '{"0": "The equation must first be free of radicals in the derivatives.", "2": "Degree must be a whole number.", "3": "After squaring it is a polynomial in the derivatives."}'),
  ('MTH-0802', 'Differential equations', 'Order and degree', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'The number of arbitrary constants in the general solution of a differential equation of order 3 is:', '["1", "2", "0", "3"]', 3, 'The general solution of an nth-order equation has n arbitrary constants.', '{"0": "Equal to the order, not always 1.", "1": "Equal to the order.", "2": "A general solution always contains constants."}'),
  ('MTH-0803', 'Differential equations', 'Forming differential equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1.1)', 'Eliminating c from y = cx gives the differential equation:', '["x dy/dx = y", "dy/dx = c", "dy/dx = x", "x dy/dx + y = 0"]', 0, 'dy/dx = c = y/x, so x dy/dx = y.', '{"1": "c has not been eliminated.", "2": "dy/dx = c, not x.", "3": "The sign is wrong."}'),
  ('MTH-0804', 'Differential equations', 'Forming differential equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1.1)', 'Eliminating c from y = c eˣ gives:', '["dy/dx = c", "dy/dx = eˣ", "dy/dx = y", "dy/dx = −y"]', 2, 'dy/dx = c eˣ = y.', '{"0": "c has not been eliminated.", "1": "That holds only when c = 1.", "3": "The sign is wrong."}'),
  ('MTH-0805', 'Differential equations', 'Forming differential equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1.1)', 'The family of circles x² + y² = r² (r arbitrary) satisfies:', '["x − y dy/dx = 0", "x + y dy/dx = 0", "dy/dx = r", "x dy/dx + y = 0"]', 1, 'Differentiating: 2x + 2y dy/dx = 0.', '{"0": "The sign is wrong.", "2": "r has not been eliminated.", "3": "x and y are mixed up."}'),
  ('MTH-0806', 'Differential equations', 'Forming differential equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1.1)', 'Eliminating A and B from y = A cos x + B sin x gives:', '["d²y/dx² + y = 0", "d²y/dx² − y = 0", "dy/dx + y = 0", "d²y/dx² = 0"]', 0, 'y″ = −A cos x − B sin x = −y.', '{"1": "That is for y = Aeˣ + Be⁻ˣ.", "2": "Two constants need a second-order equation.", "3": "That is for straight lines."}'),
  ('MTH-0807', 'Differential equations', 'Forming differential equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1.1)', 'Eliminating A and B from y = Ae²ˣ + Be⁻²ˣ gives:', '["d²y/dx² = −4y", "d²y/dx² = 2y", "dy/dx = 2y", "d²y/dx² = 4y"]', 3, 'y″ = 4Ae²ˣ + 4Be⁻²ˣ = 4y.', '{"0": "That is for cos 2x and sin 2x.", "1": "Each derivative brings out ±2, so the second gives 4.", "2": "Two constants need a second-order equation."}'),
  ('MTH-0808', 'Differential equations', 'Separable equations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = 2x is:', '["y = 2x² + c", "y = 2 + c", "y = x² + c", "y = x²"]', 2, 'Integrate both sides: y = x² + c.', '{"0": "2x integrates to x².", "1": "That is the derivative of the right side.", "3": "The arbitrary constant is missing."}'),
  ('MTH-0809', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = y is:', '["y = x + c", "y = eˣ + c", "y = ceˣ", "y = cx"]', 2, 'dy/y = dx gives ln|y| = x + k, so y = ceˣ.', '{"0": "Its derivative is 1, not y.", "1": "Its derivative eˣ is not y.", "3": "Its derivative c is not y."}'),
  ('MTH-0810', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = x/y is:', '["y² − x² = c", "y² + x² = c", "y = x + c", "y = cx"]', 0, 'y dy = x dx gives y²/2 = x²/2 + k, so y² − x² = c.', '{"1": "That solves dy/dx = −x/y.", "2": "Its slope is 1, not x/y.", "3": "Its slope y/x is not x/y in general."}'),
  ('MTH-0811', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = −y/x is:', '["y = cx", "x² + y² = c", "y = −x + c", "xy = c"]', 3, 'dy/y = −dx/x gives ln|y| = −ln|x| + k, so xy = c.', '{"0": "That solves dy/dx = y/x.", "1": "That solves dy/dx = −x/y.", "2": "Its slope is −1."}'),
  ('MTH-0812', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The solution of dy/dx = 3x², with y = 2 when x = 0, is:', '["y = x³", "y = x³ + 2", "y = 3x³ + 2", "y = x³ − 2"]', 1, 'y = x³ + c, and y(0) = c = 2.', '{"0": "The condition y(0) = 2 is ignored.", "2": "3x² integrates to x³.", "3": "The constant is +2."}'),
  ('MTH-0813', 'Differential equations', 'Separable equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = eˣ⁻ʸ is:', '["eʸ = eˣ + c", "y = x + c", "e⁻ʸ = eˣ + c", "y = eˣ + c"]', 0, 'dy/dx = eˣ/eʸ, so eʸ dy = eˣ dx and eʸ = eˣ + c.', '{"1": "Only when c = 0 (then eʸ = eˣ).", "2": "The sign on y is wrong.", "3": "The eʸ factor has not been separated."}'),
  ('MTH-0814', 'Differential equations', 'Separable equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of (1 + x²) dy/dx = 1 + y² is:', '["tan⁻¹y = x + c", "y = x + c", "tan⁻¹y = tan⁻¹x + c", "ln(1 + y²) = ln(1 + x²) + c"]', 2, 'dy/(1 + y²) = dx/(1 + x²), integrating both sides to tan⁻¹.', '{"0": "The x-side also has 1 + x² in the denominator.", "1": "Only one special solution (c = 0 gives y = x).", "3": "∫dy/(1 + y²) is tan⁻¹y, not a log."}'),
  ('MTH-0815', 'Differential equations', 'Separable equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The solution of x dy/dx = 2y passing through (1, 3) is:', '["y = 2x + 1", "y = 3x²", "y = x² + 2", "y = 3x"]', 1, 'dy/y = 2 dx/x gives y = cx². At (1, 3), c = 3.', '{"0": "Its x dy/dx = 2x, not 2y.", "2": "Its x dy/dx = 2x², not 2(x² + 2).", "3": "Its x dy/dx = 3x, not 6x."}'),
  ('MTH-0816', 'Differential equations', 'Separable equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'The general solution of dy/dx = y tan x is:', '["y = c cos x", "y = c tan x", "y = sec x + c", "y = c sec x"]', 3, 'dy/y = tan x dx gives ln|y| = ln|sec x| + k, so y = c sec x.', '{"0": "That solves dy/dx = −y tan x.", "1": "Its derivative c sec²x is not y tan x.", "2": "A constant added to sec x does not scale with y."}'),
  ('MTH-0817', 'Differential equations', 'Homogeneous equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.2)', 'A differential equation dy/dx = f(x, y) is homogeneous when f can be written as a function of:', '["x + y", "xy", "x only", "y/x"]', 3, 'Then the substitution y = vx turns it into a separable equation in v and x.', '{"0": "A function of x + y is not homogeneous in general.", "1": "A function of xy is not homogeneous in general.", "2": "That is already separable."}'),
  ('MTH-0818', 'Differential equations', 'Homogeneous equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.2)', 'For a homogeneous equation, the substitution y = vx gives dy/dx =', '["v", "x dv/dx", "v + x dv/dx", "v dv/dx"]', 2, 'Product rule on y = vx.', '{"0": "v depends on x, so its derivative appears.", "1": "The v term from the product rule is missing.", "3": "That is not the product rule."}'),
  ('MTH-0819', 'Differential equations', 'Homogeneous equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.2)', 'Which equation is homogeneous?', '["dy/dx = x + y²", "dy/dx = (x² + y²)/(xy)", "dy/dx = (x + 1)/y", "dy/dx = xy + 1"]', 1, '(x² + y²)/(xy) = x/y + y/x, a function of y/x. The others mix terms of different degrees.', '{"0": "x has degree 1 and y² degree 2.", "2": "The +1 breaks homogeneity.", "3": "xy has degree 2 and 1 has degree 0."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0820', 'Differential equations', 'Homogeneous equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.2)', 'Solving dy/dx = (x + y)/x with y = vx gives:', '["y = x ln|x| + cx", "y = ln|x| + c", "y = x² + cx", "y = cx"]', 0, 'v + x dv/dx = 1 + v, so x dv/dx = 1, v = ln|x| + c, and y = x ln|x| + cx.', '{"1": "That is v, not y = vx.", "2": "Its slope is not (x + y)/x.", "3": "That solves dy/dx = y/x."}'),
  ('MTH-0821', 'Differential equations', 'Homogeneous equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.2)', 'Solving x dy/dx = y + x (x > 0), with y = 0 at x = 1, gives:', '["y = ln x", "y = x ln x", "y = x − 1", "y = x² − x"]', 1, 'The general solution is y = x ln x + cx; y(1) = c = 0.', '{"0": "That is v = y/x.", "2": "Its x dy/dx = x, not y + x = 2x − 1.", "3": "Its x dy/dx = 2x² − x, not x²."}'),
  ('MTH-0822', 'Differential equations', 'Growth and decay', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'The differential equation for a quantity N that grows at a rate proportional to itself is:', '["dN/dt = k, k > 0", "dN/dt = −kN, k > 0", "dN/dt = kt", "dN/dt = kN, k > 0"]', 3, 'Rate proportional to amount.', '{"0": "That is constant growth.", "1": "That is decay.", "2": "That is proportional to time, not to N."}'),
  ('MTH-0823', 'Differential equations', 'Growth and decay', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'The solution of dN/dt = kN with N(0) = N₀ is:', '["N = N₀eᵏᵗ", "N = N₀ + kt", "N = N₀kt", "N = eᵏᵗ"]', 0, 'dN/N = k dt gives ln N = kt + c, so N = N₀eᵏᵗ.', '{"1": "That solves dN/dt = k.", "2": "Gives N(0) = 0.", "3": "Gives N(0) = 1."}'),
  ('MTH-0824', 'Differential equations', 'Growth and decay', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'A culture has 500 bacteria and doubles every 3 hours. After 9 hours there are:', '["1500", "3000", "4000", "2000"]', 2, '9 hours is 3 doubling periods: 500 × 2³ = 4000.', '{"0": "That is linear growth: 3 × 500.", "1": "That multiplies by 6.", "3": "That is only 2 doublings."}'),
  ('MTH-0825', 'Differential equations', 'Growth and decay', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'A population obeys dN/dt = kN and grows from 100 to 300 in 2 years. The value of k is:', '["3/2", "ln 3", "(ln 3)/2", "(ln 2)/3"]', 2, '300 = 100e²ᵏ, so e²ᵏ = 3 and k = (ln 3)/2.', '{"0": "k is found by taking a logarithm.", "1": "The time 2 must divide.", "3": "The factor is 3, not 2."}'),
  ('MTH-0826', 'Differential equations', 'Growth and decay', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'A radioactive substance decays as dM/dt = −kM. If its half-life is 10 years, k equals:', '["(ln 2)/10", "10 ln 2", "1/20", "ln 10"]', 0, '½ = e^(−10k), so 10k = ln 2.', '{"1": "ln 2 is divided by 10, not multiplied.", "2": "Halving is not linear.", "3": "Not connected with the half-life."}'),
  ('MTH-0827', 'Differential equations', 'Growth and decay', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'A sample of 80 g decays with half-life 5 days. After 15 days the mass left is:', '["20 g", "40 g", "0 g", "10 g"]', 3, '15 days is 3 half-lives: 80 × (1/2)³ = 10 g.', '{"0": "That is 2 half-lives.", "1": "That is 1 half-life.", "2": "Exponential decay never reaches 0."}'),
  ('MTH-0828', 'Differential equations', 'Newton''s law of cooling', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'Newton''s law of cooling for a body at temperature T in surroundings at temperature Tₛ is:', '["dT/dt = −kT", "dT/dt = −k(T − Tₛ)", "dT/dt = k(T + Tₛ)", "dT/dt = −k"]', 1, 'The rate of cooling is proportional to the temperature difference with the surroundings.', '{"0": "The surroundings'' temperature must appear.", "2": "The difference, not the sum, drives cooling.", "3": "Cooling is not at a constant rate."}'),
  ('MTH-0829', 'Differential equations', 'Newton''s law of cooling', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'The solution of dT/dt = −k(T − Tₛ) with T(0) = T₀ is:', '["T = Tₛ + (T₀ − Tₛ)e^(−kt)", "T = T₀e^(−kt)", "T = Tₛ + T₀e^(−kt)", "T = T₀ − kt"]', 0, 'Let u = T − Tₛ: du/dt = −ku, so u = (T₀ − Tₛ)e^(−kt).', '{"1": "That cools towards 0, not to Tₛ.", "2": "Gives T(0) = Tₛ + T₀.", "3": "Cooling is not linear."}'),
  ('MTH-0830', 'Differential equations', 'Newton''s law of cooling', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'Tea at 90 °C is left in a room at 30 °C. After 10 min it is at 60 °C. After another 10 min (by Newton''s law) it is at:', '["30 °C", "40 °C", "45 °C", "50 °C"]', 2, 'The excess over the room halves every 10 min: 60 → 30 → 15, so T = 30 + 15 = 45 °C.', '{"0": "It only approaches room temperature.", "1": "That treats the drop as 20 °C.", "3": "That treats the excess as falling by 20 °C."}'),
  ('MTH-0831', 'Differential equations', 'Applications of differential equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'In an RL circuit with emf E, resistance R and inductance L, the current satisfies L dI/dt + RI = E. With I(0) = 0, the current for large t approaches:', '["E/L", "E/R", "0", "EL/R"]', 1, 'I = (E/R)(1 − e^(−Rt/L)) → E/R as t → ∞; then dI/dt → 0 and RI = E.', '{"0": "L controls how fast, not the final value.", "2": "Current builds up from 0.", "3": "Units do not match a current."}'),
  ('MTH-0832', 'Differential equations', 'Applications of differential equations', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'The current in L dI/dt + RI = E (with I(0) = 0) is:', '["I = (E/R)e^(−Rt/L)", "I = (E/L)(1 − e^(−Lt/R))", "I = Et/L", "I = (E/R)(1 − e^(−Rt/L))"]', 3, 'Separating: dI/(E − RI) = dt/L gives I = (E/R)(1 − e^(−Rt/L)).', '{"0": "That starts at E/R, not 0.", "1": "R and L are swapped in both places.", "2": "That ignores the resistance."}'),
  ('MTH-0833', 'Differential equations', 'Applications of differential equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.3)', 'Money grows at a continuous rate of 5% a year, so dA/dt = 0.05A. The time for it to double is:', '["20 years", "0.05 ln 2 years", "(ln 2)/0.05 ≈ 13.9 years", "2/0.05 = 40 years"]', 2, '2 = e^(0.05t) gives t = (ln 2)/0.05 ≈ 13.86 years.', '{"0": "That treats growth as simple interest.", "1": "ln 2 is divided by the rate, not multiplied.", "3": "That divides 2, not ln 2, by the rate."}'),
  ('MTH-0834', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'Which function is a solution of d²y/dx² + 9y = 0?', '["y = e³ˣ", "y = sin 9x", "y = x³", "y = sin 3x"]', 3, 'y″ = −9 sin 3x = −9y.', '{"0": "That gives y″ = 9y.", "1": "That gives y″ = −81y.", "2": "y″ = 6x, not −9x³."}'),
  ('MTH-0835', 'Differential equations', 'Separable equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.2.1)', 'y = x² + c is the general solution of dy/dx = 2x. The particular solution through (1, 4) is:', '["y = x² + 4", "y = x² + 3", "y = x²", "y = 4x²"]', 1, '4 = 1 + c, so c = 3.', '{"0": "At x = 1 that gives 5.", "2": "That passes through (1, 1).", "3": "Its slope is 8x, not 2x."}'),
  ('MTH-0836', 'Differential equations', 'Order and degree', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 4 Differential Equations (§4.1)', 'A general solution and a particular solution differ because the particular solution:', '["has its arbitrary constants fixed by given conditions", "has more constants", "is not a solution of the equation", "is always zero at x = 0"]', 0, 'Initial or boundary conditions pick one member of the family.', '{"1": "It has none left free.", "2": "It still satisfies the equation.", "3": "Its value depends on the conditions."}'),
  ('MTH-0837', 'Analytical geometry', 'Distance, midpoint and slope', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The distance between (1, 2) and (4, 6) is:', '["7", "25", "√7", "5"]', 3, '√[(4 − 1)² + (6 − 2)²] = √(9 + 16) = 5.', '{"0": "That adds the differences 3 + 4.", "1": "That is the square of the distance.", "2": "√7 comes from adding 3 and 4 under the root."}'),
  ('MTH-0838', 'Analytical geometry', 'Distance, midpoint and slope', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The midpoint of the segment joining (−2, 5) and (6, −1) is:', '["(4, 4)", "(2, 2)", "(8, −6)", "(2, 3)"]', 1, '((−2 + 6)/2, (5 − 1)/2) = (2, 2).', '{"0": "The coordinates were added but not halved.", "2": "Those are the differences.", "3": "(5 − 1)/2 = 2."}'),
  ('MTH-0839', 'Analytical geometry', 'Distance, midpoint and slope', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The slope of the line through (2, −1) and (5, 8) is:', '["3", "1/3", "−3", "7/3"]', 0, '(8 − (−1))/(5 − 2) = 9/3 = 3.', '{"1": "That is run over rise.", "2": "The sign is lost.", "3": "That uses 8 − 1 instead of 8 − (−1)."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0840', 'Analytical geometry', 'Distance, midpoint and slope', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The points (1, 1), (3, 5) and (k, 9) are collinear when k equals:', '["7", "4", "5", "6"]', 2, 'Slope from (1, 1) to (3, 5) is 2; from (3, 5) to (k, 9) it must also be 2: 4/(k − 3) = 2, so k = 5.', '{"0": "That gives slope 1 for the second pair.", "1": "That gives slope 4.", "3": "That gives slope 4/3."}'),
  ('MTH-0841', 'Analytical geometry', 'Distance, midpoint and slope', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'A line makes an angle of 135° with the positive x-axis. Its slope is:', '["1", "−√3", "√3/3", "−1"]', 3, 'Slope = tan 135° = −1.', '{"0": "tan 45° = 1, but the line slopes the other way.", "1": "That is tan 120°.", "2": "That is tan 30°."}'),
  ('MTH-0842', 'Analytical geometry', 'Forms of the equation of a line', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line with slope 2 and y-intercept −3 is:', '["y = −3x + 2", "y = 2x + 3", "y = 2x − 3", "2y = x − 3"]', 2, 'Slope-intercept form y = mx + c.', '{"0": "Slope and intercept swapped.", "1": "The intercept is −3.", "3": "That has slope 1/2."}'),
  ('MTH-0843', 'Analytical geometry', 'Forms of the equation of a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line through (−1, 4) with slope −2 is:', '["2x + y + 2 = 0", "2x + y − 2 = 0", "2x − y + 6 = 0", "x + 2y − 7 = 0"]', 1, 'y − 4 = −2(x + 1), so y = −2x + 2, i.e. 2x + y − 2 = 0.', '{"0": "Does not pass through (−1, 4).", "2": "Has slope +2.", "3": "Has slope −1/2."}'),
  ('MTH-0844', 'Analytical geometry', 'Forms of the equation of a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line through (1, 2) and (3, 8) is:', '["y = 3x − 1", "y = 3x + 1", "y = 2x", "y = 6x − 4"]', 0, 'Slope = 6/2 = 3; y − 2 = 3(x − 1) gives y = 3x − 1.', '{"1": "Does not pass through (1, 2).", "2": "Wrong slope; it misses (3, 8).", "3": "Slope 6 is the rise alone."}'),
  ('MTH-0845', 'Analytical geometry', 'Forms of the equation of a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line with x-intercept 4 and y-intercept −2 is:', '["2x − y = 4", "x − 2y = 4", "x + 2y = 4", "4x − 2y = 1"]', 1, 'x/4 + y/(−2) = 1; multiply by 4: x − 2y = 4.', '{"0": "Its x-intercept is 2.", "2": "Its y-intercept is +2.", "3": "The intercepts go in the denominators."}'),
  ('MTH-0846', 'Analytical geometry', 'Forms of the equation of a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2.1)', 'The x- and y-intercepts of 3x − 4y + 12 = 0 are:', '["4 and −3", "3 and −4", "−3 and 4", "−4 and 3"]', 3, 'y = 0 gives x = −4; x = 0 gives y = 3.', '{"0": "The signs are reversed.", "1": "Swapped and with signs reversed.", "2": "Swapped."}'),
  ('MTH-0847', 'Analytical geometry', 'Forms of the equation of a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2.1)', 'The slope of the line 4x + 6y − 5 = 0 is:', '["−2/3", "2/3", "−3/2", "5/6"]', 0, '6y = −4x + 5, so y = −(2/3)x + 5/6.', '{"1": "The sign is lost.", "2": "That is −b/a, not −a/b.", "3": "That is the y-intercept."}'),
  ('MTH-0848', 'Analytical geometry', 'Forms of the equation of a line', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2.1)', 'The normal form of the line 3x + 4y − 10 = 0 is:', '["3x + 4y = 10", "(3/4)x + y = 5/2", "(3/5)x + (4/5)y = 2", "(4/5)x + (3/5)y = 2"]', 2, 'Divide by √(3² + 4²) = 5: x cos α + y sin α = p with cos α = 3/5, sin α = 4/5 and p = 2.', '{"0": "Not normalised: 3² + 4² ≠ 1.", "1": "Divided by 4, not by 5.", "3": "cos α and sin α are swapped."}'),
  ('MTH-0849', 'Analytical geometry', 'Forms of the equation of a line', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2.1)', 'In normal form x cos α + y sin α = p, p stands for:', '["the y-intercept", "the slope", "the perpendicular distance of the line from the origin", "the x-intercept"]', 2, 'p ≥ 0 is the length of the perpendicular from the origin; α is the angle that perpendicular makes with the x-axis.', '{"0": "The y-intercept is p/sin α.", "1": "The slope is −cot α.", "3": "The x-intercept is p/cos α."}'),
  ('MTH-0850', 'Analytical geometry', 'Distance from a point to a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2)', 'The distance of the point (2, 3) from the line 3x + 4y + 2 = 0 is:', '["4", "20", "4/5", "20/7"]', 0, '|3·2 + 4·3 + 2|/√(9 + 16) = 20/5 = 4.', '{"1": "Not divided by √(a² + b²) = 5.", "2": "Divided by 25, not 5.", "3": "Divided by 3 + 4."}'),
  ('MTH-0851', 'Analytical geometry', 'Distance from a point to a line', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2)', 'The distance of the origin from the line 5x − 12y + 26 = 0 is:', '["26", "26/17", "13", "2"]', 3, '|26|/√(25 + 144) = 26/13 = 2.', '{"0": "Not divided by 13.", "1": "Divided by 5 + 12.", "2": "That is √(5² + 12²), the divisor."}'),
  ('MTH-0852', 'Analytical geometry', 'Distance from a point to a line', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2)', 'The distance between the parallel lines 3x + 4y − 5 = 0 and 3x + 4y + 15 = 0 is:', '["2", "4", "4/5", "20"]', 1, '|c₁ − c₂|/√(a² + b²) = |−5 − 15|/5 = 4.', '{"0": "That uses |−5 + 15|.", "2": "Divided by 25 instead of 5.", "3": "Not divided by 5."}'),
  ('MTH-0853', 'Analytical geometry', 'Distance from a point to a line', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.2)', 'The point (1, k) is at distance 2 from the line 4x − 3y + 1 = 0. One value of k is:', '["1", "3", "−5", "5"]', 3, '|4 − 3k + 1|/5 = 2, so |5 − 3k| = 10, giving k = 5 or k = −5/3.', '{"0": "Gives distance 2/5.", "1": "Gives distance 4/5.", "2": "Gives distance 4."}'),
  ('MTH-0854', 'Analytical geometry', 'Parallel and perpendicular lines', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'Two lines with slopes m₁ and m₂ are perpendicular when:', '["m₁ = m₂", "m₁ + m₂ = 0", "m₁m₂ = −1", "m₁m₂ = 1"]', 2, 'Perpendicular (non-vertical) lines have slopes whose product is −1.', '{"0": "That is the condition for parallel lines.", "1": "That gives lines symmetric about a vertical, not perpendicular in general.", "3": "The product is −1, not 1."}'),
  ('MTH-0855', 'Analytical geometry', 'Parallel and perpendicular lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line through (2, −1) parallel to 3x − y + 7 = 0 is:', '["3x − y + 7 = 0", "3x − y − 7 = 0", "x + 3y + 1 = 0", "3x + y − 5 = 0"]', 1, 'A parallel line is 3x − y + k = 0; through (2, −1): 6 + 1 + k = 0, so k = −7.', '{"0": "That is the given line, not through (2, −1).", "2": "That is perpendicular.", "3": "Slope −3, not 3."}'),
  ('MTH-0856', 'Analytical geometry', 'Parallel and perpendicular lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The line through (1, 3) perpendicular to 2x + 3y − 6 = 0 is:', '["3x − 2y + 3 = 0", "2x + 3y − 11 = 0", "3x + 2y − 9 = 0", "3x − 2y − 3 = 0"]', 0, 'A perpendicular line is 3x − 2y + k = 0; through (1, 3): 3 − 6 + k = 0, so k = 3.', '{"1": "That is parallel to the given line.", "2": "Its slope −3/2 is not perpendicular.", "3": "Does not pass through (1, 3)."}'),
  ('MTH-0857', 'Analytical geometry', 'Parallel and perpendicular lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.1)', 'The lines 2x + ky = 5 and 3x − 6y = 1 are perpendicular when k equals:', '["−4", "1", "4", "−1"]', 1, 'Slopes −2/k and 1/2: (−2/k)(1/2) = −1 gives k = 1.', '{"0": "That makes them parallel.", "2": "Gives slopes −1/2 and 1/2, whose product is −1/4.", "3": "Gives slopes 2 and 1/2, whose product is +1."}'),
  ('MTH-0858', 'Analytical geometry', 'Medians, altitudes and bisectors', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'The centroid of the triangle with vertices (1, 2), (3, −4) and (5, 8) is:', '["(3, 2)", "(9, 6)", "(3, 3)", "(4, 2)"]', 0, '((1 + 3 + 5)/3, (2 − 4 + 8)/3) = (3, 2).', '{"1": "The sums were not divided by 3.", "2": "(2 − 4 + 8)/3 = 2.", "3": "(1 + 3 + 5)/3 = 3."}'),
  ('MTH-0859', 'Analytical geometry', 'Medians, altitudes and bisectors', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'The right bisector of the segment joining (0, 0) and (4, 2) is:', '["x − 2y = 0", "2x + y − 10 = 0", "x + 2y − 4 = 0", "2x + y − 5 = 0"]', 3, 'Midpoint (2, 1); the segment''s slope is 1/2, so the bisector has slope −2: y − 1 = −2(x − 2), i.e. 2x + y − 5 = 0.', '{"0": "That is the segment''s own line.", "1": "Does not pass through the midpoint (2, 1).", "2": "Slope −1/2 is not perpendicular."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0860', 'Analytical geometry', 'Medians, altitudes and bisectors', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'The three medians of a triangle meet at the:', '["orthocentre", "circumcentre", "centroid", "incentre"]', 2, 'Medians meet at the centroid, which divides each median 2 : 1.', '{"0": "Altitudes meet at the orthocentre.", "1": "Right bisectors meet at the circumcentre.", "3": "Angle bisectors meet at the incentre."}'),
  ('MTH-0861', 'Analytical geometry', 'Medians, altitudes and bisectors', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'The altitudes of a triangle meet at the:', '["centroid", "orthocentre", "circumcentre", "midpoint of the longest side"]', 1, 'An altitude runs from a vertex perpendicular to the opposite side; the three meet at the orthocentre.', '{"0": "Medians meet at the centroid.", "2": "Right bisectors meet at the circumcentre.", "3": "That is the circumcentre of a right triangle only."}'),
  ('MTH-0862', 'Analytical geometry', 'Medians, altitudes and bisectors', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'For the triangle A(0, 0), B(6, 0), C(2, 4), the altitude from C is:', '["y = 4", "x = 3", "y = x", "x = 2"]', 3, 'AB lies on the x-axis, so the altitude from C is vertical: x = 2.', '{"0": "That is the line through C parallel to AB.", "1": "That is the right bisector of AB.", "2": "Not perpendicular to AB."}'),
  ('MTH-0863', 'Analytical geometry', 'Medians, altitudes and bisectors', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.3)', 'For the triangle A(0, 0), B(6, 0), C(0, 8), the circumcentre is:', '["(3, 4)", "(2, 8/3)", "(0, 0)", "(6, 8)"]', 0, 'The angle at A is a right angle, so the circumcentre is the midpoint of the hypotenuse BC: (3, 4).', '{"1": "That is the centroid.", "2": "That is the orthocentre, the right-angle vertex.", "3": "That is the fourth corner of the rectangle: a point on the circle, not its centre."}'),
  ('MTH-0864', 'Analytical geometry', 'Concurrency of lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.4)', 'The lines x + y = 3, 2x − y = 0 and x − 2y + k = 0 are concurrent when k equals:', '["−3", "1", "3", "0"]', 2, 'The first two meet at (1, 2). Then 1 − 4 + k = 0 gives k = 3.', '{"0": "Gives 1 − 4 − 3 ≠ 0.", "1": "Gives 1 − 4 + 1 ≠ 0.", "3": "(1, 2) gives 1 − 4 = −3 ≠ 0."}'),
  ('MTH-0865', 'Analytical geometry', 'Concurrency of lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.4)', 'Three lines aᵢx + bᵢy + cᵢ = 0 (i = 1, 2, 3), no two parallel, are concurrent when:', '["the determinant of their coefficients aᵢ, bᵢ, cᵢ is zero", "a₁ + a₂ + a₃ = 0", "their slopes are equal", "c₁ = c₂ = c₃"]', 0, 'A common point exists exactly when |a₁ b₁ c₁; a₂ b₂ c₂; a₃ b₃ c₃| = 0.', '{"1": "Not a general condition.", "2": "Equal slopes make them parallel.", "3": "Equal constants do not force a common point."}'),
  ('MTH-0866', 'Analytical geometry', 'Concurrency of lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.5)', 'The line through the intersection of x + y − 4 = 0 and 2x − y − 2 = 0 and the origin is:', '["y = 2x", "x + y = 0", "y = x", "y = 3x"]', 2, 'x + y = 4 and 2x − y = 2 meet at (2, 2); the line through (2, 2) and the origin is y = x.', '{"0": "Passes through the origin but not through (2, 2).", "1": "Misses (2, 2).", "3": "Misses (2, 2)."}'),
  ('MTH-0867', 'Analytical geometry', 'Angle between two lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.6)', 'The acute angle between lines with slopes 1 and 0 is:', '["90°", "45°", "30°", "60°"]', 1, 'tan θ = |(1 − 0)/(1 + 0)| = 1, so θ = 45°.', '{"0": "The product of slopes is 0, not −1.", "2": "tan 30° = 1/√3.", "3": "tan 60° = √3."}'),
  ('MTH-0868', 'Analytical geometry', 'Angle between two lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.6)', 'The acute angle between y = √3 x and y = x/√3 is:', '["60°", "45°", "90°", "30°"]', 3, 'The lines make angles 60° and 30° with the x-axis, so the angle between them is 30°.', '{"0": "60° is the angle of the first line with the x-axis.", "1": "60° − 30° = 30°, not 45°.", "2": "The product of slopes is 1, not −1."}'),
  ('MTH-0869', 'Analytical geometry', 'Angle between two lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.6)', 'The acute angle between 2x − y + 3 = 0 and x − 3y + 1 = 0 is:', '["30°", "60°", "90°", "45°"]', 3, 'Slopes 2 and 1/3: tan θ = |(2 − 1/3)/(1 + 2/3)| = 1, so θ = 45°.', '{"0": "tan 30° = 1/√3.", "1": "tan 60° = √3.", "2": "The product of the slopes is 2/3, not −1."}'),
  ('MTH-0870', 'Analytical geometry', 'Area of a triangle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.7)', 'The area of the triangle with vertices (0, 0), (4, 0) and (0, 3) is:', '["12", "6", "7", "5"]', 1, 'Right triangle with legs 4 and 3: (1/2)(4)(3) = 6.', '{"0": "The 1/2 is missing.", "2": "That adds the legs.", "3": "That is the hypotenuse."}'),
  ('MTH-0871', 'Analytical geometry', 'Area of a triangle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.7)', 'The area of the triangle with vertices (1, 1), (4, 2) and (2, 5) is:', '["11/2", "11", "15/2", "21/2"]', 0, '(1/2)|1(2 − 5) + 4(5 − 1) + 2(1 − 2)| = (1/2)|−3 + 16 − 2| = 11/2.', '{"1": "The 1/2 is missing.", "2": "The sign of 2(1 − 2) was dropped.", "3": "The sign of 1(2 − 5) was dropped."}'),
  ('MTH-0872', 'Analytical geometry', 'Area of a triangle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.7)', 'The points (2, 3), (4, k) and (6, 7) are collinear when k equals:', '["4", "6", "5", "3"]', 2, 'Collinear points enclose zero area; the middle x is the average, so k = (3 + 7)/2 = 5.', '{"0": "Then (4, 4) lies below the line through the other two.", "1": "Then (4, 6) lies above that line.", "3": "That is the first point''s y-value."}'),
  ('MTH-0873', 'Analytical geometry', 'Pair of lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.8)', 'The equation x² − y² = 0 represents:', '["a circle", "a hyperbola", "the single line y = x", "the two lines y = x and y = −x"]', 3, 'x² − y² = (x − y)(x + y) = 0.', '{"0": "A circle needs x² + y².", "1": "A hyperbola needs a non-zero constant: x² − y² = a².", "2": "The factor x + y gives a second line."}'),
  ('MTH-0874', 'Analytical geometry', 'Pair of lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.8.1)', 'The lines represented by x² − 5xy + 6y² = 0 are:', '["x = −2y and x = −3y", "x = 2y and x = 3y", "y = 2x and y = 3x", "x = y and x = 6y"]', 1, 'x² − 5xy + 6y² = (x − 2y)(x − 3y).', '{"0": "The signs are wrong.", "2": "x and y swapped.", "3": "Those give x² − 7xy + 6y²."}'),
  ('MTH-0875', 'Analytical geometry', 'Pair of lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.9)', 'The lines given by ax² + 2hxy + by² = 0 are perpendicular when:', '["a + b = 0", "h² = ab", "a = b", "h = 0"]', 0, 'The angle formula tan θ = 2√(h² − ab)/(a + b) becomes undefined when a + b = 0, giving 90°.', '{"1": "That makes the two lines coincide.", "2": "That only makes the lines symmetric about y = x.", "3": "h = 0 makes the lines symmetric about the axes, not perpendicular."}'),
  ('MTH-0876', 'Analytical geometry', 'Pair of lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.9)', 'The two lines represented by ax² + 2hxy + by² = 0 coincide when:', '["a + b = 0", "h = 0", "h² = ab", "ab = 0"]', 2, 'Then tan θ = 0, so the angle between the lines is 0.', '{"0": "That makes them perpendicular.", "1": "h = 0 makes the lines symmetric about the axes.", "3": "Then one of the lines is an axis."}'),
  ('MTH-0877', 'Analytical geometry', 'Pair of lines', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.9)', 'The acute angle between the lines x² + 4xy + y² = 0 is:', '["45°", "30°", "60°", "90°"]', 2, 'a = 1, h = 2, b = 1: tan θ = 2√(4 − 1)/(1 + 1) = √3, so θ = 60°.', '{"0": "tan 45° = 1.", "1": "tan 30° = 1/√3.", "3": "a + b ≠ 0."}'),
  ('MTH-0878', 'Analytical geometry', 'Pair of lines', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.9)', 'Which equation represents a pair of perpendicular lines through the origin?', '["x² + 2xy + y² = 0", "x² + y² = 0", "2x² − xy − y² + 1 = 0", "3x² + 8xy − 3y² = 0"]', 3, 'a + b = 3 − 3 = 0, and h² − ab = 16 + 9 > 0, so it gives two real perpendicular lines.', '{"0": "h² = ab: two coincident lines.", "1": "Only the origin satisfies it.", "2": "The constant 1 means the lines do not pass through the origin."}'),
  ('MTH-0879', 'Analytical geometry', 'Applications of analytical geometry', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.10)', 'An aircraft flies in a straight line from (0, 0) km to (300, 400) km. The distance flown is:', '["700 km", "500 km", "350 km", "250 000 km"]', 1, '√(300² + 400²) = 500 km.', '{"0": "That adds the components.", "2": "That is their average.", "3": "That is the square of the distance."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0880', 'Analytical geometry', 'Applications of analytical geometry', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.10)', 'A road rises 15 m over a horizontal distance of 300 m. Its slope as a percentage is:', '["5%", "20%", "15%", "0.05%"]', 0, '15/300 = 0.05 = 5%.', '{"1": "That is run over rise.", "2": "That uses the rise alone.", "3": "0.05 as a percentage is 5%."}'),
  ('MTH-0881', 'Analytical geometry', 'Applications of analytical geometry', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 5 Analytical Geometry (§5.10)', 'A ship at (2, 3) sails along the line 3x + 4y = 18 (units in km). How far is a lighthouse at (6, 8) from this course?', '["8 km", "6.4 km", "32 km", "√41 km"]', 1, 'Distance from a point to a line: |3·6 + 4·8 − 18|/√(3² + 4²) = 32/5 = 6.4 km.', '{"0": "That divides by 4 instead of 5.", "2": "Not divided by √(3² + 4²) = 5.", "3": "That is the distance from the ship, not from its course."}'),
  ('MTH-0882', 'Conic sections', 'Circle', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1)', 'The equation of the circle with centre (2, −3) and radius 4 is:', '["(x + 2)² + (y − 3)² = 16", "(x − 2)² + (y + 3)² = 4", "(x − 2)² + (y − 3)² = 16", "(x − 2)² + (y + 3)² = 16"]', 3, '(x − h)² + (y − k)² = r² with h = 2, k = −3, r = 4.', '{"0": "The signs of the centre are reversed.", "1": "The right side is r², not r.", "2": "k = −3 gives (y + 3)²."}'),
  ('MTH-0883', 'Conic sections', 'Circle', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.3)', 'The centre and radius of x² + y² − 6x + 4y − 12 = 0 are:', '["(3, −2) and 5", "(−3, 2) and 5", "(3, −2) and 12", "(6, −4) and 5"]', 0, 'Centre (−g, −f) = (3, −2); r = √(9 + 4 + 12) = 5.', '{"1": "The centre is (−g, −f), and 2g = −6 gives g = −3.", "2": "r = √(g² + f² − c), not c.", "3": "The coefficients were not halved."}'),
  ('MTH-0884', 'Conic sections', 'Circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.3)', 'The radius of the circle 2x² + 2y² − 8x + 12y + 8 = 0 is:', '["2√11", "9", "3", "√17"]', 2, 'Divide by 2: x² + y² − 4x + 6y + 4 = 0. Centre (2, −3), r = √(4 + 9 − 4) = 3.', '{"0": "The equation must first be divided by 2.", "1": "That is r².", "3": "c = +4 is subtracted: r² = 4 + 9 − 4."}'),
  ('MTH-0885', 'Conic sections', 'Circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.4)', 'The circle with (1, 2) and (5, 8) as the ends of a diameter is:', '["(x − 1)(x − 5) + (y − 2)(y − 8) = 0", "(x + 1)(x + 5) + (y + 2)(y + 8) = 0", "(x − 1)(y − 2) + (x − 5)(y − 8) = 0", "(x − 3)² + (y − 5)² = 52"]', 0, 'For ends (x₁, y₁) and (x₂, y₂): (x − x₁)(x − x₂) + (y − y₁)(y − y₂) = 0.', '{"1": "The signs are wrong.", "2": "x and y factors are mixed.", "3": "The centre is right but r² = 13, not 52."}'),
  ('MTH-0886', 'Conic sections', 'Circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.1)', 'The parametric equations of the circle x² + y² = 9 are:', '["x = 9 cos θ, y = 9 sin θ", "x = 3 cos θ, y = 3 sin θ", "x = cos 3θ, y = sin 3θ", "x = 3 sec θ, y = 3 tan θ"]', 1, '(3 cos θ)² + (3 sin θ)² = 9.', '{"0": "That gives radius 9.", "2": "That gives radius 1.", "3": "Those satisfy x² − y² = 9, a hyperbola."}'),
  ('MTH-0887', 'Conic sections', 'Circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.2)', 'x² + y² + 2gx + 2fy + c = 0 represents a real circle only if:', '["g² + f² + c > 0", "c > 0", "g² + f² − c > 0", "g = f"]', 2, 'The radius is √(g² + f² − c), which must be real and positive.', '{"0": "The sign of c is wrong.", "1": "c can be negative.", "3": "g and f can be anything."}'),
  ('MTH-0888', 'Conic sections', 'Circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.5)', 'The circle with centre (3, 4) passing through the origin is:', '["x² + y² + 6x + 8y = 0", "x² + y² − 6x − 8y + 25 = 0", "x² + y² = 25", "x² + y² − 6x − 8y = 0"]', 3, 'r = 5, so (x − 3)² + (y − 4)² = 25, i.e. x² + y² − 6x − 8y = 0.', '{"0": "Centre (−3, −4).", "1": "Does not pass through the origin.", "2": "Centre at the origin."}'),
  ('MTH-0889', 'Conic sections', 'Circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.5)', 'The circle through (0, 0), (4, 0) and (0, 6) is:', '["x² + y² + 4x + 6y = 0", "x² + y² − 4x − 6y = 0", "x² + y² − 2x − 3y = 0", "x² + y² − 4x − 6y + 13 = 0"]', 1, 'Through the origin, c = 0. (4, 0): 16 + 8g = 0, g = −2. (0, 6): 36 + 12f = 0, f = −3.', '{"0": "Signs of g and f wrong.", "2": "That uses g and f as the coefficients of x and y.", "3": "c = 0 since the origin is on it."}'),
  ('MTH-0890', 'Conic sections', 'Circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.1.5)', 'A circle touches both axes and has its centre on the line x + y = 8 in the first quadrant. Its equation is:', '["(x − 4)² + (y − 4)² = 16", "(x − 8)² + (y − 8)² = 64", "(x − 4)² + (y − 4)² = 4", "(x − 2)² + (y − 6)² = 4"]', 0, 'Touching both axes in the first quadrant means centre (r, r); r + r = 8 gives r = 4.', '{"1": "(8, 8) is not on x + y = 8.", "2": "The radius is 4, so r² = 16.", "3": "Its centre is 6 from the x-axis but its radius is 2, so it does not touch the x-axis."}'),
  ('MTH-0891', 'Conic sections', 'Tangents to a circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.2)', 'The tangent to x² + y² = 25 at (3, 4) is:', '["4x + 3y = 25", "3x − 4y = 25", "3x + 4y = 5", "3x + 4y = 25"]', 3, 'The tangent to x² + y² = r² at (x₁, y₁) is xx₁ + yy₁ = r².', '{"0": "x₁ and y₁ are swapped.", "1": "The sign of y₁ is wrong.", "2": "The right side is r², not r."}'),
  ('MTH-0892', 'Conic sections', 'Tangents to a circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.3)', 'The normal to the circle x² + y² = 25 at (3, 4) is:', '["3x + 4y = 25", "3x − 4y = 0", "4x − 3y = 0", "4x + 3y = 24"]', 2, 'A normal to a circle passes through the centre, here the origin: the line through (0, 0) and (3, 4) is y = (4/3)x.', '{"0": "That is the tangent.", "1": "That has slope 3/4, not 4/3.", "3": "That does not pass through the centre."}'),
  ('MTH-0893', 'Conic sections', 'Tangents to a circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.4)', 'The point (2, 3) with respect to the circle x² + y² = 10 lies:', '["inside the circle", "on the circle", "outside the circle", "at the centre"]', 2, 'Substituting: 4 + 9 − 10 = 3 > 0, so the point is outside.', '{"0": "Inside would need a negative value.", "1": "On it would need 0.", "3": "The centre is (0, 0)."}'),
  ('MTH-0894', 'Conic sections', 'Tangents to a circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.8)', 'The length of the tangent from (5, 6) to the circle x² + y² − 2x − 4y − 4 = 0 is:', '["√23", "23", "√32", "√31"]', 0, 'Length = √S₁, where S₁ = 5² + 6² − 2(5) − 4(6) − 4 = 23.', '{"1": "That is the square of the length.", "2": "That is the distance to the centre (1, 2), not the tangent length.", "3": "The constant −4 was added instead of subtracted."}'),
  ('MTH-0895', 'Conic sections', 'Tangents to a circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.5)', 'The line y = mx + c is a tangent to x² + y² = r² when:', '["c = r(1 + m)", "c² = r²(1 − m²)", "c² = r² + m²", "c² = r²(1 + m²)"]', 3, 'The distance from the centre to the line, |c|/√(1 + m²), must equal r.', '{"0": "The square roots were not handled correctly.", "1": "The sign inside is +.", "2": "m² must multiply r²."}'),
  ('MTH-0896', 'Conic sections', 'Tangents to a circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.5)', 'The value of c for which y = x + c touches x² + y² = 8 is:', '["±8", "±4", "±2√2", "±16"]', 1, 'c² = r²(1 + m²) = 8 × 2 = 16, so c = ±4.', '{"0": "That is c²/2.", "2": "That is r.", "3": "That is c²."}'),
  ('MTH-0897', 'Conic sections', 'Tangents to a circle', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.5)', 'The line 3x + 4y = k touches the circle x² + y² = 4 when k equals:', '["±5", "±2", "±20", "±10"]', 3, 'Distance from the origin |k|/5 must equal 2.', '{"0": "That is the divisor √(3² + 4²).", "1": "That is the radius.", "2": "That doubles the correct value."}'),
  ('MTH-0898', 'Conic sections', 'Tangents to a circle', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.2.5)', 'The line x = 3 and the circle x² + y² = 9:', '["cut at two points", "touch at (3, 0)", "do not meet", "cut at (0, 3)"]', 1, 'The line is at distance 3 = r from the centre, so it is a tangent at (3, 0).', '{"0": "That needs the distance less than 3.", "2": "That needs the distance more than 3.", "3": "(0, 3) is not on x = 3."}'),
  ('MTH-0899', 'Conic sections', 'Parabola', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.2)', 'The focus of the parabola y² = 12x is:', '["(3, 0)", "(12, 0)", "(0, 3)", "(−3, 0)"]', 0, 'y² = 4ax with 4a = 12, so a = 3 and the focus is (a, 0).', '{"1": "4a = 12, not a = 12.", "2": "This parabola opens along the x-axis.", "3": "It opens to the right."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0900', 'Conic sections', 'Parabola', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.2)', 'The directrix of the parabola y² = 8x is:', '["x = 2", "y = −2", "x = −2", "x = −8"]', 2, '4a = 8, a = 2; the directrix is x = −a.', '{"0": "That is through the focus.", "1": "The directrix is vertical for y² = 4ax.", "3": "4a = 8, not a = 8."}'),
  ('MTH-0901', 'Conic sections', 'Parabola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.2)', 'The length of the latus rectum of x² = −16y is:', '["16", "4", "8", "−16"]', 0, 'x² = −4ay with 4a = 16; the latus rectum has length 4a = 16.', '{"1": "That is a.", "2": "That is 2a.", "3": "A length is never negative."}'),
  ('MTH-0902', 'Conic sections', 'Parabola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.3)', 'The parabola x² = −8y opens:', '["upward", "downward", "to the left", "to the right"]', 1, 'x² = −4ay (a > 0) opens downward; y ≤ 0 on the curve.', '{"0": "That is for x² = 4ay.", "2": "That is for y² = −4ax.", "3": "That is for y² = 4ax."}'),
  ('MTH-0903', 'Conic sections', 'Parabola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.3)', 'The parabola with focus (0, −3) and directrix y = 3 is:', '["x² = 12y", "y² = −12x", "x² = −12y", "x² = −3y"]', 2, 'Vertex at the origin, a = 3, opening downward: x² = −4ay = −12y.', '{"0": "It opens away from the directrix, so downward.", "1": "The axis is vertical.", "3": "4a = 12, not 3."}'),
  ('MTH-0904', 'Conic sections', 'Parabola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.3)', 'The vertex of the parabola (y − 2)² = 4(x + 1) is:', '["(1, −2)", "(2, −1)", "(0, 0)", "(−1, 2)"]', 3, 'Shifting Y² = 4X: X = x + 1 = 0 and Y = y − 2 = 0.', '{"0": "The signs are reversed.", "1": "x and y are swapped.", "2": "The parabola has been shifted."}'),
  ('MTH-0905', 'Conic sections', 'Parabola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.3)', 'The focus of the parabola y² − 4y − 8x + 20 = 0 is:', '["(2, 2)", "(4, 2)", "(2, 4)", "(4, −2)"]', 1, '(y − 2)² = 8x − 16 = 8(x − 2). Vertex (2, 2), a = 2, so the focus is (2 + 2, 2) = (4, 2).', '{"0": "That is the vertex.", "2": "x and y swapped.", "3": "The sign of the y-shift is wrong."}'),
  ('MTH-0906', 'Conic sections', 'Parabola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.5)', 'The tangent to y² = 4ax at (x₁, y₁) is:', '["yy₁ = 4a(x + x₁)", "yy₁ = 2a(x − x₁)", "xx₁ = 2a(y + y₁)", "yy₁ = 2a(x + x₁)"]', 3, 'Differentiating, dy/dx = 2a/y₁; the point-slope form simplifies (using y₁² = 4ax₁) to yy₁ = 2a(x + x₁).', '{"0": "The factor should be 2a, not 4a.", "1": "The sign should be +.", "2": "That is for x² = 4ay."}'),
  ('MTH-0907', 'Conic sections', 'Parabola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.5)', 'The line y = mx + c touches the parabola y² = 4ax when:', '["c = a/m", "c = am", "c = −a/m", "c = 4a/m"]', 0, 'Substituting gives a quadratic in x; equal roots give c = a/m.', '{"1": "m divides a; it does not multiply it.", "2": "The sign is +.", "3": "The factor 4 cancels."}'),
  ('MTH-0908', 'Conic sections', 'Parabola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3.5)', 'The tangent to y² = 8x with slope 2 is:', '["y = 2x + 4", "y = 2x − 1", "y = 2x + 1", "y = 2x + 2"]', 2, 'a = 2, so c = a/m = 1.', '{"0": "That uses c = am.", "1": "The sign is +.", "3": "That uses c = a."}'),
  ('MTH-0909', 'Conic sections', 'Parabola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.3)', 'The eccentricity of every parabola is:', '["1", "0", "between 0 and 1", "greater than 1"]', 0, 'For a parabola, the distance to the focus equals the distance to the directrix.', '{"1": "e = 0 is a circle.", "2": "That is an ellipse.", "3": "That is a hyperbola."}'),
  ('MTH-0910', 'Conic sections', 'Ellipse', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.1)', 'For x²/25 + y²/9 = 1, the lengths of the major and minor axes are:', '["5 and 3", "10 and 6", "25 and 9", "6 and 10"]', 1, 'a = 5 and b = 3; the axes are 2a and 2b.', '{"0": "Those are the semi-axes.", "2": "Those are a² and b².", "3": "The major axis is the longer one."}'),
  ('MTH-0911', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.1)', 'The foci of x²/25 + y²/16 = 1 are:', '["(±5, 0)", "(0, ±3)", "(±3, 0)", "(±4, 0)"]', 2, 'c² = a² − b² = 25 − 16 = 9, so c = 3; the major axis is along x.', '{"0": "Those are the vertices.", "1": "The major axis is horizontal here.", "3": "That is b."}'),
  ('MTH-0912', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.1)', 'The eccentricity of x²/25 + y²/16 = 1 is:', '["4/5", "5/3", "16/25", "3/5"]', 3, 'e = c/a = 3/5.', '{"0": "That is b/a.", "1": "An ellipse has e < 1.", "2": "That is b²/a²."}'),
  ('MTH-0913', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4)', 'For the ellipse x²/9 + y²/25 = 1, the major axis lies along:', '["the x-axis", "the line y = x", "the y-axis", "neither axis"]', 2, 'The larger denominator, 25, is under y², so the ellipse is longer in the y-direction.', '{"0": "The larger denominator is under y².", "1": "Standard ellipses have axes along the coordinate axes.", "3": "Its axes are the coordinate axes."}'),
  ('MTH-0914', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.2)', 'The length of the latus rectum of x²/16 + y²/9 = 1 is:', '["9/2", "9/4", "8", "3"]', 0, 'Latus rectum = 2b²/a = 2(9)/4 = 9/2.', '{"1": "That is b²/a, the semi-latus rectum.", "2": "That is 2a.", "3": "That is b."}'),
  ('MTH-0915', 'Conic sections', 'Ellipse', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.2)', 'The ellipse with foci (±4, 0) and vertices (±5, 0) is:', '["x²/25 + y²/16 = 1", "x²/16 + y²/9 = 1", "x²/9 + y²/25 = 1", "x²/25 + y²/9 = 1"]', 3, 'a = 5, c = 4, b² = a² − c² = 9.', '{"0": "b² = 25 − 16 = 9, not 16.", "1": "a must be 5.", "2": "The major axis is along x."}'),
  ('MTH-0916', 'Conic sections', 'Ellipse', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.1)', 'The ellipse 4x² + 9y² = 36 has eccentricity:', '["2/3", "√5/3", "5/9", "√13/3"]', 1, 'x²/9 + y²/4 = 1: a = 3, b = 2, c = √5, e = √5/3.', '{"0": "That is b/a.", "2": "That is c²/a².", "3": "That uses a² + b²."}'),
  ('MTH-0917', 'Conic sections', 'Ellipse', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.2)', 'The directrices of x²/25 + y²/16 = 1 are:', '["x = ±3", "x = ±25/3", "x = ±5", "x = ±16/3"]', 1, 'x = ±a/e = ±5/(3/5) = ±25/3.', '{"0": "Those are the foci.", "2": "Those are the vertices.", "3": "That uses b² instead of a²."}'),
  ('MTH-0918', 'Conic sections', 'Ellipse', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4)', 'For any point P on an ellipse with foci F₁ and F₂, |PF₁| + |PF₂| equals:', '["2b", "2c", "a²", "2a, the length of the major axis"]', 3, 'This constant sum is the defining property of an ellipse.', '{"0": "2b is the minor axis.", "1": "2c is the distance between the foci.", "2": "a² is an area, not a length."}'),
  ('MTH-0919', 'Conic sections', 'Ellipse', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4.3)', 'The tangent to x²/a² + y²/b² = 1 at (x₁, y₁) is:', '["xx₁/a² + yy₁/b² = 1", "xx₁/a² − yy₁/b² = 1", "xx₁ + yy₁ = a²", "x/x₁ + y/y₁ = 1"]', 0, 'Replace x² by xx₁ and y² by yy₁.', '{"1": "That is for a hyperbola.", "2": "That is for a circle.", "3": "That is the line with intercepts x₁ and y₁."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0920', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4)', 'The parametric equations of x²/a² + y²/b² = 1 are:', '["x = a sec θ, y = b tan θ", "x = at², y = 2at", "x = a cos θ, y = b sin θ", "x = a sin θ, y = a cos θ"]', 2, 'cos²θ + sin²θ = 1.', '{"0": "That is a hyperbola.", "1": "That is a parabola.", "3": "That is a circle of radius a."}'),
  ('MTH-0921', 'Conic sections', 'Ellipse', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4)', 'As the eccentricity of an ellipse approaches 0, the ellipse approaches:', '["a parabola", "a circle", "a straight line", "a hyperbola"]', 1, 'e = c/a → 0 means the foci merge at the centre and b → a.', '{"0": "e = 1 is a parabola.", "2": "That is the limit as e → 1 with the minor axis shrinking.", "3": "e > 1 is a hyperbola."}'),
  ('MTH-0922', 'Conic sections', 'Hyperbola', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.1)', 'The vertices of x²/16 − y²/9 = 1 are:', '["(0, ±3)", "(±5, 0)", "(±16, 0)", "(±4, 0)"]', 3, 'y = 0 gives x² = 16.', '{"0": "The curve does not cross the y-axis.", "1": "Those are the foci.", "2": "That is a², not a."}'),
  ('MTH-0923', 'Conic sections', 'Hyperbola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.1)', 'The foci of x²/16 − y²/9 = 1 are:', '["(±5, 0)", "(±√7, 0)", "(±4, 0)", "(0, ±5)"]', 0, 'For a hyperbola c² = a² + b² = 25.', '{"1": "That uses a² − b², the ellipse rule.", "2": "Those are the vertices.", "3": "The transverse axis is along x."}'),
  ('MTH-0924', 'Conic sections', 'Hyperbola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.1)', 'The eccentricity of x²/16 − y²/9 = 1 is:', '["4/5", "3/4", "5/4", "5/3"]', 2, 'e = c/a = 5/4.', '{"0": "A hyperbola has e > 1.", "1": "That is b/a.", "3": "That is c/b."}'),
  ('MTH-0925', 'Conic sections', 'Hyperbola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.2)', 'The asymptotes of x²/9 − y²/4 = 1 are:', '["y = ±(3/2)x", "y = ±(2/3)x", "y = ±(4/9)x", "x = ±3"]', 1, 'y = ±(b/a)x with a = 3 and b = 2.', '{"0": "That is ±(a/b)x.", "2": "That uses b²/a².", "3": "Those are vertical lines through the vertices."}'),
  ('MTH-0926', 'Conic sections', 'Hyperbola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5)', 'The hyperbola y²/16 − x²/9 = 1 has its transverse axis along:', '["the y-axis", "the x-axis", "the line y = x", "both axes"]', 0, 'The positive term is y², so the curve meets the y-axis at (0, ±4).', '{"1": "That is when the x² term is positive.", "2": "Standard forms have axes along the coordinate axes.", "3": "Only one axis is transverse."}'),
  ('MTH-0927', 'Conic sections', 'Hyperbola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5)', 'For any point P on a hyperbola with foci F₁ and F₂, ||PF₁| − |PF₂|| equals:', '["2b", "2c", "a + c", "2a"]', 3, 'The constant difference of focal distances defines the hyperbola.', '{"0": "2b is the conjugate axis.", "1": "2c is the distance between the foci.", "2": "That is the distance from a vertex to the far focus."}'),
  ('MTH-0928', 'Conic sections', 'Hyperbola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.2)', 'The hyperbola with vertices (±3, 0) and foci (±5, 0) is:', '["x²/9 − y²/25 = 1", "x²/25 − y²/9 = 1", "x²/9 − y²/16 = 1", "x²/9 + y²/16 = 1"]', 2, 'a = 3, c = 5, b² = c² − a² = 16.', '{"0": "b² = 25 − 9 = 16.", "1": "a = 3, not 5.", "3": "That is an ellipse."}'),
  ('MTH-0929', 'Conic sections', 'Hyperbola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5)', 'A rectangular hyperbola (a = b) has eccentricity:', '["1", "√2", "2", "1/√2"]', 1, 'c² = a² + a² = 2a², so e = c/a = √2.', '{"0": "That is a parabola.", "2": "That is c²/a².", "3": "e > 1 for a hyperbola."}'),
  ('MTH-0930', 'Conic sections', 'Hyperbola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5)', 'The asymptotes of the rectangular hyperbola x² − y² = a² are:', '["perpendicular, y = ±x", "parallel", "y = ±2x", "the coordinate axes"]', 0, 'With a = b, the asymptotes y = ±x meet at right angles.', '{"1": "Asymptotes of a hyperbola always meet at the centre.", "2": "b/a = 1, not 2.", "3": "That is for xy = c²."}'),
  ('MTH-0931', 'Conic sections', 'Hyperbola', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5.3)', 'The tangent to x²/a² − y²/b² = 1 at (x₁, y₁) is:', '["xx₁/a² + yy₁/b² = 1", "xx₁ − yy₁ = a²", "x/x₁ − y/y₁ = 1", "xx₁/a² − yy₁/b² = 1"]', 3, 'Replace x² by xx₁ and y² by yy₁.', '{"0": "That is for an ellipse.", "1": "Only when a = b.", "2": "That ignores a and b altogether."}'),
  ('MTH-0932', 'Conic sections', 'Hyperbola', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.5)', 'Which equation represents a hyperbola?', '["4x² + 9y² = 36", "y² = 4x + 1", "4x² − 9y² + 8x = 32", "x² + y² − 2x = 3"]', 2, 'x² and y² terms of opposite signs give a hyperbola.', '{"0": "Same-sign different coefficients: an ellipse.", "1": "Only one square term: a parabola.", "3": "Equal coefficients: a circle."}'),
  ('MTH-0933', 'Conic sections', 'Conics', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.4)', 'The conic is an ellipse when its eccentricity e satisfies:', '["e = 1", "e > 1", "0 < e < 1", "e = 0"]', 2, 'Ellipse: 0 < e < 1; parabola: e = 1; hyperbola: e > 1; circle: e = 0.', '{"0": "That is a parabola.", "1": "That is a hyperbola.", "3": "That is a circle."}'),
  ('MTH-0934', 'Conic sections', 'Applications of conics', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.6)', 'A satellite dish is a paraboloid; its cross-section is y² = 12x (in cm). The receiver should be placed at:', '["(0, 0), the vertex", "(12, 0)", "(6, 0)", "(3, 0), the focus"]', 3, 'Signals parallel to the axis reflect through the focus, (a, 0) with a = 3.', '{"0": "The vertex does not collect the reflected rays.", "1": "4a = 12, so a = 3.", "2": "That is 2a."}'),
  ('MTH-0935', 'Conic sections', 'Applications of conics', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.6)', 'A parabolic arch is 8 m high and 12 m wide at the base. With the vertex at (0, 8), its height 3 m from the centre is:', '["4 m", "6 m", "2 m", "7 m"]', 1, 'y = 8 − kx² with y = 0 at x = 6: k = 8/36 = 2/9. At x = 3: y = 8 − 2 = 6 m.', '{"0": "That is half the height, as if the arch were linear.", "2": "That is 8 − 6.", "3": "That uses k = 1/9."}'),
  ('MTH-0936', 'Conic sections', 'Applications of conics', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.6)', 'A planet moves on an ellipse with the Sun at a focus; a = 5 and c = 3 (in astronomical units). Its closest distance to the Sun is:', '["2", "3", "5", "8"]', 0, 'The nearest point is the vertex on the Sun''s side: a − c = 2.', '{"1": "That is c.", "2": "That is a.", "3": "That is the farthest distance, a + c."}'),
  ('MTH-0937', 'Conic sections', 'Applications of conics', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 6 Conic Section (§6.6)', 'In a whispering gallery shaped like an ellipse, a whisper at one focus is heard clearly at:', '["the other focus", "the centre", "the end of the minor axis", "a vertex"]', 0, 'Sound from one focus reflects off the ellipse to the other focus.', '{"1": "Reflected sound does not gather at the centre.", "2": "Reflected sound does not gather at the end of the minor axis.", "3": "Reflected sound does not gather at a vertex."}'),
  ('MTH-0938', 'Kinematics', 'Scalars and vectors', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.1)', 'Which of these is a vector quantity?', '["Distance", "Displacement", "Speed", "Time"]', 1, 'Displacement has both size and direction.', '{"0": "Distance has size only.", "2": "Speed is the size of velocity, with no direction.", "3": "Time has no direction."}'),
  ('MTH-0939', 'Kinematics', 'Scalars and vectors', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.3)', 'A runner completes one full lap of a 400 m circular track. Her displacement is:', '["400 m", "200 m", "0 m", "400π m"]', 2, 'She ends where she started, so the displacement is zero; the distance is 400 m.', '{"0": "That is the distance.", "1": "That is half the distance.", "3": "The lap length is already 400 m."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0940', 'Kinematics', 'Displacement and velocity', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.3)', 'A man walks 30 m east and then 40 m north in 50 s. His average velocity has magnitude:', '["1.4 m/s", "0.6 m/s", "50 m/s", "1 m/s"]', 3, 'Displacement = √(30² + 40²) = 50 m; 50/50 = 1 m/s. (Average speed is 70/50 = 1.4 m/s.)', '{"0": "That is the average speed.", "1": "That uses 30 m only.", "2": "That is the displacement, not divided by time."}'),
  ('MTH-0941', 'Kinematics', 'Displacement and velocity', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.3)', 'A car travels 60 km in the first hour and 40 km in the next hour along a straight road in the same direction. Its average speed is:', '["100 km/h", "48 km/h", "20 km/h", "50 km/h"]', 3, 'Total distance 100 km in 2 h.', '{"0": "That is the distance, not divided by time.", "1": "That is the harmonic mean, used for equal distances, not equal times.", "2": "That is the difference in distances."}'),
  ('MTH-0942', 'Kinematics', 'Displacement and velocity', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.3)', 'A car goes 60 km at 30 km/h and returns the same 60 km at 60 km/h. Its average speed for the round trip is:', '["45 km/h", "0 km/h", "40 km/h", "30 km/h"]', 2, 'Times: 2 h and 1 h. Total 120 km in 3 h = 40 km/h.', '{"0": "The plain average of the speeds ignores the time spent at each.", "1": "That is the average velocity, since the displacement is 0.", "3": "That is the slower speed only."}'),
  ('MTH-0943', 'Kinematics', 'Displacement-time graphs', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.4)', 'On a displacement–time graph, the slope gives the:', '["acceleration", "velocity", "distance", "time"]', 1, 'Slope = change in displacement / change in time.', '{"0": "Acceleration is the slope of a velocity–time graph.", "2": "Distance is read from the axis.", "3": "Time is the horizontal axis."}'),
  ('MTH-0944', 'Kinematics', 'Displacement-time graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.4)', 'A horizontal line on a displacement–time graph means the body is:', '["at rest", "moving with constant velocity", "accelerating uniformly", "moving back"]', 0, 'Displacement does not change, so velocity is 0.', '{"1": "That is a sloping straight line.", "2": "That gives a curve.", "3": "That gives a falling line."}'),
  ('MTH-0945', 'Kinematics', 'Velocity-time graphs', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.5)', 'On a velocity–time graph, the area under the graph gives the:', '["acceleration", "velocity", "speed", "displacement"]', 3, 'Area = velocity × time = displacement.', '{"0": "Acceleration is the slope.", "1": "Velocity is read from the axis.", "2": "Speed is the size of the velocity."}'),
  ('MTH-0946', 'Kinematics', 'Velocity-time graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.5)', 'A body''s speed rises uniformly from 0 to 20 m/s in 10 s. The distance covered is:', '["200 m", "20 m", "100 m", "2 m"]', 2, 'Area of the triangle under the v–t graph: (1/2)(10)(20) = 100 m.', '{"0": "The 1/2 is missing.", "1": "That is the final speed.", "3": "That is the acceleration."}'),
  ('MTH-0947', 'Kinematics', 'Velocity-time graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.5)', 'A velocity–time graph is a straight line from (0, 4) to (5, 14) (t in s, v in m/s). The acceleration is:', '["2.8 m/s²", "2 m/s²", "10 m/s²", "0.5 m/s²"]', 1, 'Slope = (14 − 4)/5 = 2 m/s².', '{"0": "That uses 14/5.", "2": "That is the change in velocity.", "3": "That is the reciprocal."}'),
  ('MTH-0948', 'Kinematics', 'Velocity-time graphs', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.5)', 'A car moves at 10 m/s for 4 s, then slows uniformly to rest in the next 6 s. The total distance covered is:', '["70 m", "100 m", "40 m", "60 m"]', 0, 'Rectangle 10 × 4 = 40 m plus triangle (1/2)(6)(10) = 30 m.', '{"1": "That treats all 10 s at 10 m/s.", "2": "Only the first part.", "3": "The braking triangle needs a factor 1/2."}'),
  ('MTH-0949', 'Kinematics', 'Equations of motion', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'For uniform acceleration, v = u + at. Here u is the:', '["initial velocity", "final velocity", "displacement", "time"]', 0, 'u is the velocity at t = 0.', '{"1": "That is v.", "2": "That is s.", "3": "That is t."}'),
  ('MTH-0950', 'Kinematics', 'Equations of motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A car starts from rest with acceleration 3 m/s². Its velocity after 6 s is:', '["9 m/s", "18 m/s", "54 m/s", "2 m/s"]', 1, 'v = u + at = 0 + 3 × 6.', '{"0": "That is half of it.", "2": "That is (1/2)at², the distance.", "3": "That divides instead of multiplies."}'),
  ('MTH-0951', 'Kinematics', 'Equations of motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A body accelerates uniformly from 5 m/s to 25 m/s in 4 s. The distance covered is:', '["100 m", "80 m", "60 m", "120 m"]', 2, 's = (u + v)t/2 = (5 + 25)(4)/2 = 60 m.', '{"0": "That is 25 × 4, the final speed times time.", "1": "That is (25 − 5) × 4.", "3": "That forgets to halve."}'),
  ('MTH-0952', 'Kinematics', 'Equations of motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A car moving at 20 m/s brakes with deceleration 4 m/s². The distance it needs to stop is:', '["100 m", "5 m", "80 m", "50 m"]', 3, 'v² = u² + 2as: 0 = 400 − 8s, so s = 50 m.', '{"0": "The factor 2 is missing.", "1": "That is the time to stop.", "2": "That is u × a."}'),
  ('MTH-0953', 'Kinematics', 'Equations of motion', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A body moves with uniform acceleration. It covers 12 m in the 1st second and 20 m in the 2nd second. Its acceleration is:', '["4 m/s²", "16 m/s²", "8 m/s²", "32 m/s²"]', 2, 'Distances in successive equal intervals differ by aT²; with T = 1 s, a = 20 − 12 = 8 m/s².', '{"0": "That halves the difference.", "1": "That doubles it.", "3": "That adds the two distances."}'),
  ('MTH-0954', 'Kinematics', 'Kinematics with calculus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'The position of a particle is s(t) = t³ − 6t² + 9t (m). Its velocity at t = 2 s is:', '["2 m/s", "3 m/s", "9 m/s", "−3 m/s"]', 3, 'v = 3t² − 12t + 9 = 12 − 24 + 9 = −3 m/s.', '{"0": "That is s(2).", "1": "The sign is lost.", "2": "That is v(0)."}'),
  ('MTH-0955', 'Kinematics', 'Kinematics with calculus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'For s(t) = t³ − 6t² + 9t, the particle is momentarily at rest at:', '["t = 0 and t = 3 s", "t = 1 s and t = 3 s", "t = 2 s", "t = 3 s only"]', 1, 'v = 3(t − 1)(t − 3) = 0.', '{"0": "v(0) = 9.", "2": "That is when acceleration is 0.", "3": "v(1) = 0 too."}'),
  ('MTH-0956', 'Kinematics', 'Kinematics with calculus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'If v(t) = 4t − t² (m/s), the acceleration at t = 1 s is:', '["2 m/s²", "3 m/s²", "4 m/s²", "−2 m/s²"]', 0, 'a = dv/dt = 4 − 2t = 2.', '{"1": "That is v(1).", "2": "That is a(0).", "3": "The sign is wrong."}'),
  ('MTH-0957', 'Kinematics', 'Kinematics with calculus', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A particle has acceleration a = 6t (m/s²), starts at s = 0 with v = 2 m/s. Its position at t = 2 s is:', '["8 m", "16 m", "14 m", "12 m"]', 3, 'v = 3t² + 2, s = t³ + 2t. At t = 2: 8 + 4 = 12 m.', '{"0": "The initial velocity term 2t was left out.", "1": "That uses v(2) + 2.", "2": "That is v(2) = 14 m/s."}'),
  ('MTH-0958', 'Kinematics', 'Kinematics with calculus', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A particle''s velocity is v = 3t² − 3 (m/s). The distance it covers from t = 0 to t = 2 s is:', '["2 m", "4 m", "6 m", "9 m"]', 2, 'v < 0 until t = 1. Distance = |∫₀¹ v dt| + ∫₁² v dt = 2 + 4 = 6 m. (Displacement = 2 m.)', '{"0": "That is the displacement.", "1": "That is only the second part.", "3": "That is v(2)."}'),
  ('MTH-0959', 'Kinematics', 'Kinematics with calculus', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'If s = 5 sin t, the acceleration of the particle equals:', '["s", "−s", "5 cos t", "−5 cos t"]', 1, 'v = 5 cos t, a = −5 sin t = −s.', '{"0": "The sign is lost.", "2": "That is the velocity.", "3": "That is −v."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0960', 'Kinematics', 'Vertical motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.7)', 'A stone is dropped from rest. Taking g = 9.8 m/s², its speed after 3 s is:', '["29.4 m/s", "44.1 m/s", "9.8 m/s", "3.27 m/s"]', 0, 'v = gt = 9.8 × 3.', '{"1": "That is the distance fallen, (1/2)gt².", "2": "That is after 1 s.", "3": "That divides by 3."}'),
  ('MTH-0961', 'Kinematics', 'Vertical motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.7)', 'A stone is dropped from a cliff and hits the water after 2 s. Taking g = 9.8 m/s², the height of the cliff is:', '["39.2 m", "19.6 m", "9.8 m", "4.9 m"]', 1, 'h = (1/2)gt² = (1/2)(9.8)(4).', '{"0": "The 1/2 is missing.", "2": "That uses t instead of t².", "3": "That is the fall in the first second."}'),
  ('MTH-0962', 'Kinematics', 'Vertical motion', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.7)', 'A ball is thrown straight up at 19.6 m/s. Taking g = 9.8 m/s², the greatest height reached is:', '["39.2 m", "9.8 m", "2 m", "19.6 m"]', 3, 'At the top v = 0: 0 = u² − 2gh, so h = 19.6²/(2 × 9.8) = 19.6 m.', '{"0": "The factor 2 is missing.", "1": "That halves the height.", "2": "That is the time to the top, in seconds."}'),
  ('MTH-0963', 'Kinematics', 'Vertical motion', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.7)', 'A ball thrown straight up at 14.7 m/s returns to the thrower''s hand after (g = 9.8 m/s²):', '["3 s", "1.5 s", "6 s", "0.67 s"]', 0, 'Time up = u/g = 1.5 s; the time down is the same, so 3 s in all.', '{"1": "That is only the time to the top.", "2": "That doubles once too often.", "3": "That is g/u."}'),
  ('MTH-0964', 'Kinematics', 'Vertical motion', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.7)', 'At the highest point of a ball thrown straight up, which is true?', '["Velocity and acceleration are both 0", "Acceleration is 0, velocity is greatest", "Velocity is 0, acceleration is g downward", "Both are greatest"]', 2, 'Gravity acts throughout, so a = g downward even at the top; only the velocity is momentarily 0.', '{"0": "Gravity does not switch off at the top.", "1": "Acceleration is never 0 here.", "3": "Speed is least at the top."}'),
  ('MTH-0965', 'Kinematics', 'Kinematics with calculus', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A particle starts from rest at the origin and its acceleration is a = 12 − 6t (m/s²). Its velocity is greatest at:', '["t = 0", "t = 4 s", "t = 6 s", "t = 2 s"]', 3, 'v is greatest when a = dv/dt = 0: 12 − 6t = 0 gives t = 2 s.', '{"0": "v(0) = 0 is the least.", "1": "That is when v returns to 0.", "2": "Then v = 72 − 108 = −36 m/s."}'),
  ('MTH-0966', 'Kinematics', 'Displacement and velocity', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.3)', 'Which statement is always true?', '["Distance travelled = size of displacement", "Distance travelled ≤ size of displacement", "Distance travelled ≥ size of displacement", "Displacement is never zero"]', 2, 'Displacement is the straight-line change in position; any path is at least that long.', '{"0": "Only for motion in one direction along a line.", "1": "A path cannot be shorter than the straight line.", "3": "A round trip has zero displacement."}'),
  ('MTH-0967', 'Kinematics', 'Equations of motion', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 7 Kinematics (§7.1.6)', 'A train starts from rest and accelerates at 0.5 m/s² for 20 s, then moves at constant speed for 30 s. The total distance is:', '["300 m", "400 m", "100 m", "500 m"]', 1, 'Phase 1: s = (1/2)(0.5)(20²) = 100 m, final speed 10 m/s. Phase 2: 10 × 30 = 300 m. Total 400 m.', '{"0": "Only the constant-speed part.", "2": "Only the accelerating part.", "3": "That treats the first phase at 10 m/s too."}'),
  ('MTH-0968', 'Numerical methods', 'Locating roots', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.1.1)', 'If f is continuous on [a, b] and f(a) and f(b) have opposite signs, then:', '["f has at least one root between a and b", "f has exactly one root between a and b", "f has no root between a and b", "f(a) + f(b) = 0"]', 0, 'A continuous graph that goes from below the axis to above (or the reverse) must cross it at least once.', '{"1": "There may be more than one root.", "2": "A sign change guarantees a root.", "3": "The values need not be equal and opposite."}'),
  ('MTH-0969', 'Numerical methods', 'Locating roots', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.1.1)', 'For f(x) = x³ − x − 1, a root lies in the interval:', '["(0, 1)", "(2, 3)", "(−1, 0)", "(1, 2)"]', 3, 'f(1) = −1 < 0 and f(2) = 5 > 0.', '{"0": "f(0) = −1 and f(1) = −1: no sign change.", "1": "f(2) = 5 and f(3) = 23: no sign change.", "2": "f(−1) = −1 and f(0) = −1: no sign change."}'),
  ('MTH-0970', 'Numerical methods', 'Locating roots', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.1.1)', 'For f(x) = eˣ − 3x, which interval contains a root?', '["(1, 1.2)", "(0, 1)", "(2, 2.5)", "(−1, 0)"]', 1, 'f(0) = 1 > 0 and f(1) = e − 3 ≈ −0.28 < 0.', '{"0": "f(1) ≈ −0.28 and f(1.2) ≈ −0.28: both negative.", "2": "f(2) ≈ 1.39 and f(2.5) ≈ 4.68: both positive.", "3": "f(−1) ≈ 3.37 and f(0) = 1: both positive."}'),
  ('MTH-0971', 'Numerical methods', 'Locating roots', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.2)', 'The roots of x = cos x can be found graphically as the x-coordinates of the intersections of:', '["y = x and y = cos x", "y = x and y = sin x", "y = cos x and the x-axis", "y = x cos x and the x-axis"]', 0, 'Each intersection of the two graphs satisfies x = cos x.', '{"1": "That solves x = sin x.", "2": "Those are the roots of cos x = 0.", "3": "Those are the roots of x cos x = 0."}'),
  ('MTH-0972', 'Numerical methods', 'Locating roots', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.2)', 'The equation x = cos x has how many real roots?', '["None", "Two", "Exactly one", "Infinitely many"]', 2, 'y = cos x stays between −1 and 1, and y = x crosses that band only once, near x ≈ 0.739.', '{"0": "The graphs do meet.", "1": "For x < 0, cos x > 0 > x, so there is no second crossing.", "3": "Only one crossing, since |cos x| ≤ 1."}'),
  ('MTH-0973', 'Numerical methods', 'Bisection method', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.2)', 'In the bisection method on [a, b], the next estimate of the root is:', '["a − f(a)/f′(a)", "(a + b)/2", "(a f(b) − b f(a))/(f(b) − f(a))", "√(ab)"]', 1, 'Bisection halves the interval each time.', '{"0": "That is Newton–Raphson.", "2": "That is regula falsi.", "3": "That is a geometric mean, not the midpoint."}'),
  ('MTH-0974', 'Numerical methods', 'Bisection method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.2)', 'Applying bisection to f(x) = x³ − x − 1 on [1, 2], after the first step the root lies in:', '["[1, 1.5]", "[1.5, 2]", "[1, 2]", "[1.25, 1.5]"]', 0, 'f(1.5) = 0.875 > 0 and f(1) < 0, so the sign change is in [1, 1.5].', '{"1": "f(1.5) and f(2) are both positive.", "2": "The interval must halve.", "3": "That needs a second step."}'),
  ('MTH-0975', 'Numerical methods', 'Bisection method', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.2)', 'Continuing bisection for x³ − x − 1 = 0 from [1, 1.5], the next interval is:', '["[1, 1.25]", "[1.5, 2]", "[1.25, 1.375]", "[1.25, 1.5]"]', 3, 'f(1.25) ≈ −0.297 < 0 and f(1.5) > 0, so the root is in [1.25, 1.5].', '{"0": "f(1) and f(1.25) are both negative.", "1": "The root was already shown to be below 1.5.", "2": "That needs another step."}'),
  ('MTH-0976', 'Numerical methods', 'Bisection method', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.2)', 'Starting with an interval of length 1, how many bisection steps are needed before the interval length is below 0.01?', '["10", "5", "7", "100"]', 2, 'After n steps the length is 1/2ⁿ. 1/2⁶ = 1/64 > 0.01 but 1/2⁷ = 1/128 < 0.01.', '{"0": "That gives 1/1024, more steps than needed.", "1": "1/32 is still above 0.01.", "3": "That would be if the interval shrank by 0.01 each step."}'),
  ('MTH-0977', 'Numerical methods', 'Bisection method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.2)', 'A main advantage of the bisection method is that it:', '["always converges once a sign change is found", "converges faster than Newton–Raphson", "needs the derivative", "needs no starting interval"]', 0, 'Each step keeps the root trapped in an interval half as long.', '{"1": "It is usually slower.", "2": "It uses only function values.", "3": "It needs an interval with a sign change."}'),
  ('MTH-0978', 'Numerical methods', 'Regula falsi method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.3)', 'The regula falsi (false position) estimate on [a, b] is:', '["(a + b)/2", "a − f(a)/f′(a)", "(a f(b) − b f(a))/(f(b) − f(a))", "(f(a) + f(b))/2"]', 2, 'It takes the x-intercept of the chord joining (a, f(a)) and (b, f(b)).', '{"0": "That is bisection.", "1": "That is Newton–Raphson.", "3": "That averages function values, not x-values."}'),
  ('MTH-0979', 'Numerical methods', 'Regula falsi method', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.3)', 'One step of regula falsi for f(x) = x² − 2 on [1, 2] gives:', '["3/2", "4/3", "17/12", "5/3"]', 1, 'f(1) = −1, f(2) = 2: c = (1·2 − 2·(−1))/(2 − (−1)) = 4/3.', '{"0": "That is bisection.", "2": "That is two Newton steps from 1.", "3": "Sign slip: (2·2 − 1·(−1))/3."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-0980', 'Numerical methods', 'Regula falsi method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.3)', 'Regula falsi replaces the curve between a and b by:', '["the tangent at a", "the midpoint", "a parabola", "the chord joining (a, f(a)) and (b, f(b))"]', 3, 'The chord''s x-intercept is the next estimate.', '{"0": "That is Newton–Raphson.", "1": "That is bisection.", "2": "Fitting parabolas is the idea behind Simpson''s rule."}'),
  ('MTH-0981', 'Numerical methods', 'Newton-Raphson method', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'The Newton–Raphson formula is:', '["xₙ₊₁ = xₙ + f(xₙ)/f′(xₙ)", "xₙ₊₁ = xₙ − f(xₙ)/f′(xₙ)", "xₙ₊₁ = xₙ − f′(xₙ)/f(xₙ)", "xₙ₊₁ = (xₙ + f(xₙ))/2"]', 1, 'It takes the x-intercept of the tangent at xₙ.', '{"0": "The correction is subtracted.", "2": "The fraction is upside down.", "3": "That averages x and f(x), which has no meaning here."}'),
  ('MTH-0982', 'Numerical methods', 'Newton-Raphson method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'Newton–Raphson for x² − 2 = 0 with x₀ = 1 gives x₁ =', '["4/3", "1/2", "2", "3/2"]', 3, 'x₁ = 1 − (1 − 2)/(2·1) = 1 + 1/2 = 3/2.', '{"0": "That is regula falsi on [1, 2].", "1": "The sign of the correction is wrong.", "2": "That overshoots: the correction is 1/2, not 1."}'),
  ('MTH-0983', 'Numerical methods', 'Newton-Raphson method', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'Continuing Newton–Raphson for x² − 2 = 0 from x₁ = 3/2 gives x₂ =', '["17/12", "7/5", "3/2", "41/29"]', 0, 'x₂ = 3/2 − (9/4 − 2)/3 = 3/2 − 1/12 = 17/12 ≈ 1.4167.', '{"1": "That is a continued-fraction estimate, not this step.", "2": "The iteration does change.", "3": "That is a later approximation of √2, not the next step."}'),
  ('MTH-0984', 'Numerical methods', 'Newton-Raphson method', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'Using Newton–Raphson to find ∛10 from x₀ = 2 (with f(x) = x³ − 10), x₁ equals:', '["2", "7/3", "13/6", "11/6"]', 2, 'x₁ = 2 − (8 − 10)/(3·4) = 2 + 1/6 = 13/6 ≈ 2.167.', '{"0": "The iterate moves.", "1": "Correction 1/3 instead of 1/6.", "3": "The sign of the correction is wrong."}'),
  ('MTH-0985', 'Numerical methods', 'Newton-Raphson method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'Newton–Raphson fails at a step where:', '["f(xₙ) = 0", "xₙ = 0", "f(xₙ) > 0", "f′(xₙ) = 0"]', 3, 'The formula divides by f′(xₙ); a horizontal tangent never meets the x-axis.', '{"0": "Then xₙ is already a root.", "1": "x = 0 is not a problem in itself.", "2": "The sign of f does not matter."}'),
  ('MTH-0986', 'Numerical methods', 'Newton-Raphson method', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.4)', 'Compared with bisection, Newton–Raphson usually:', '["always converges", "does not need f′", "converges much faster near a simple root", "needs a sign-changing interval"]', 2, 'Near a simple root the number of correct digits roughly doubles each step.', '{"0": "It can diverge from a poor start.", "1": "It does need f′.", "3": "It needs only a starting point."}'),
  ('MTH-0987', 'Numerical methods', 'Accuracy and tolerance', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.1)', 'To give a root correct to 3 decimal places using the function-value test, iterate until:', '["|f(c)| < 0.005", "|f(c)| < 0.0005", "|f(c)| < 0.05", "|f(c)| = 0"]', 1, 'For n decimal places the tolerance is 0.5 × 10⁻ⁿ.', '{"0": "That is for 2 decimal places.", "2": "That is for 1 decimal place.", "3": "Exact zero is rarely reached."}'),
  ('MTH-0988', 'Numerical methods', 'Accuracy and tolerance', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.3.1)', 'When a numerical method involves trigonometric functions, the calculator should be in:', '["radian mode", "degree mode", "grad mode", "either mode"]', 0, 'The derivatives and series behind these methods assume radians.', '{"1": "Degrees give wrong values for sin x near a root in radians.", "2": "Not used.", "3": "The mode changes every value."}'),
  ('MTH-0989', 'Numerical methods', 'Trapezium rule', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'With n strips of width h, the trapezium rule estimates ∫ₐᵇ f(x) dx as:', '["h[y₀ + y₁ + … + yₙ]", "(h/2)[y₀ + 2(y₁ + … + yₙ₋₁) + yₙ]", "(h/3)[y₀ + 4y₁ + yₙ]", "(h/2)[y₀ + yₙ]"]', 1, 'Each strip is a trapezium; inner ordinates are shared by two strips.', '{"0": "That counts every ordinate once with no halving.", "2": "That is a Simpson-type rule.", "3": "That uses one strip only."}'),
  ('MTH-0990', 'Numerical methods', 'Trapezium rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'Using the trapezium rule with 4 strips, ∫₀² x² dx is estimated as:', '["8/3", "3", "5/2", "11/4"]', 3, 'h = 0.5; ordinates 0, 0.25, 1, 2.25, 4. Estimate = 0.25[0 + 2(3.5) + 4] = 11/4.', '{"0": "That is the exact value.", "1": "That rounds up.", "2": "That misses the end ordinate."}'),
  ('MTH-0991', 'Numerical methods', 'Trapezium rule', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'The trapezium rule with 2 strips gives ∫₁² dx/x ≈ 17/24 ≈ 0.708. The exact value ln 2 ≈ 0.693. Why is the estimate too large?', '["1/x is concave up, so the chords lie above the curve", "1/x is decreasing", "Too many strips were used", "The function is negative"]', 0, 'For a curve that bends upward, every trapezium top lies above the curve, so the rule overestimates.', '{"1": "Decreasing alone does not decide over- or under-estimate.", "2": "More strips would improve the estimate.", "3": "1/x > 0 on [1, 2]."}'),
  ('MTH-0992', 'Numerical methods', 'Trapezium rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'The trapezium rule with strip width h = 1 and ordinates y = 2, 5, 7, 4 gives:', '["18", "30", "15", "9"]', 2, '(1/2)[2 + 2(5 + 7) + 4] = (1/2)(30) = 15.', '{"0": "That just adds the ordinates.", "1": "The factor h/2 is missing.", "3": "That halves the plain sum of the ordinates."}'),
  ('MTH-0993', 'Numerical methods', 'Trapezium rule', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'The trapezium rule with 2 strips for ∫₀^π sin x dx gives:', '["2", "π", "π/2 ≈ 1.571", "0"]', 2, 'h = π/2; ordinates 0, 1, 0. Estimate = (π/4)(0 + 2 + 0) = π/2. The exact value is 2.', '{"0": "That is the exact value.", "1": "The factor 1/2 is missing.", "3": "The middle ordinate sin(π/2) = 1."}'),
  ('MTH-0994', 'Numerical methods', 'Trapezium rule', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.4.1)', 'The trapezium rule is exact for:', '["linear functions", "all quadratics", "all polynomials", "no function"]', 0, 'A straight line coincides with its chords.', '{"1": "A quadratic bends away from its chords.", "2": "Only degree 0 and 1.", "3": "It is exact for straight lines."}'),
  ('MTH-0995', 'Numerical methods', 'Applications of numerical methods', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.5)', 'An equation like x = e⁻ˣ (from a reaction rate model) cannot be solved by algebra. A suitable approach is:', '["the quadratic formula", "factorising", "the trapezium rule", "Newton–Raphson on f(x) = x − e⁻ˣ"]', 3, 'Transcendental equations are solved approximately by iteration.', '{"0": "It is not a quadratic.", "1": "It does not factorise.", "2": "That estimates integrals, not roots."}'),
  ('MTH-0996', 'Numerical methods', 'Applications of numerical methods', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 8 Numerical Methods (§8.5)', 'For f(x) = x − e⁻ˣ, Newton–Raphson from x₀ = 0 gives x₁ =', '["1", "1/2", "0", "1/e"]', 1, 'f(0) = −1, f′(x) = 1 + e⁻ˣ so f′(0) = 2. x₁ = 0 − (−1)/2 = 1/2.', '{"0": "That uses f′(0) = 1.", "2": "The iterate moves.", "3": "That is e⁻¹, the value of e⁻ˣ at 1."}'),
  ('MTH-0997', 'Inverse trigonometric functions', 'Domain and range', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'The domain of y = sin⁻¹x is:', '["[−1, 1]", "[−π/2, π/2]", "all real numbers", "[0, π]"]', 0, 'sin x only takes values from −1 to 1, so only those can be inputs to sin⁻¹.', '{"1": "That is the range of sin⁻¹x.", "2": "sin⁻¹2 is not defined.", "3": "That is the range of cos⁻¹x."}'),
  ('MTH-0998', 'Inverse trigonometric functions', 'Domain and range', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'The range (principal values) of y = cos⁻¹x is:', '["[−π/2, π/2]", "[0, π]", "[−1, 1]", "(0, π)"]', 1, 'cos x is restricted to [0, π], where it is one-to-one.', '{"0": "That is the range of sin⁻¹x.", "2": "That is the domain.", "3": "The endpoints 0 and π are included."}'),
  ('MTH-0999', 'Inverse trigonometric functions', 'Domain and range', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.3)', 'The range of y = tan⁻¹x is:', '["[−π/2, π/2]", "(0, π)", "(−π/2, π/2)", "all real numbers"]', 2, 'tan x on (−π/2, π/2) takes every real value; the endpoints are excluded since tan is undefined there.', '{"0": "tan(±π/2) is not defined.", "1": "That is the range of cot⁻¹x.", "3": "That is the domain."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-1000', 'Inverse trigonometric functions', 'Domain and range', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.3)', 'The domain of y = tan⁻¹x is:', '["[−1, 1]", "(−π/2, π/2)", "x ≠ 0", "all real numbers"]', 3, 'tan takes every real value, so tan⁻¹ accepts any real input.', '{"0": "That is the domain of sin⁻¹ and cos⁻¹.", "1": "That is the range.", "2": "tan⁻¹0 = 0 is defined."}'),
  ('MTH-1001', 'Inverse trigonometric functions', 'Domain and range', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.5)', 'The domain of y = sec⁻¹x is:', '["−1 ≤ x ≤ 1", "all real numbers", "x > 0", "x ≤ −1 or x ≥ 1"]', 3, '|sec x| ≥ 1 always, so only such values have an inverse secant.', '{"0": "That is the domain of cos⁻¹x.", "1": "sec⁻¹(1/2) is not defined.", "2": "sec⁻¹(−2) = 2π/3 is defined."}'),
  ('MTH-1002', 'Inverse trigonometric functions', 'Domain and range', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.6)', 'The range of y = cot⁻¹x is:', '["(−π/2, π/2)", "(0, π)", "[0, π]", "[−π/2, π/2] − {0}"]', 1, 'cot is one-to-one on (0, π), with cot → ±∞ at the ends.', '{"0": "That is the range of tan⁻¹x.", "2": "cot 0 and cot π are undefined.", "3": "That is the range of cosec⁻¹x."}'),
  ('MTH-1003', 'Inverse trigonometric functions', 'Domain and range', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.4)', 'The range of y = cosec⁻¹x is:', '["[−π/2, π/2] − {0}", "[0, π] − {π/2}", "(0, π)", "[−π/2, π/2]"]', 0, 'cosec is restricted to [−π/2, π/2] without 0, where it is undefined.', '{"1": "That is the range of sec⁻¹x.", "2": "That is the range of cot⁻¹x.", "3": "cosec 0 is undefined, so 0 is excluded."}'),
  ('MTH-1004', 'Inverse trigonometric functions', 'Domain and range', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'The domain of f(x) = sin⁻¹(2x − 1) is:', '["[−1, 1]", "[−1/2, 1/2]", "[0, 1]", "[1/2, 1]"]', 2, 'Need −1 ≤ 2x − 1 ≤ 1, i.e. 0 ≤ 2x ≤ 2.', '{"0": "That is for sin⁻¹x.", "1": "The 1 was not added.", "3": "Only half of the interval."}'),
  ('MTH-1005', 'Inverse trigonometric functions', 'Principal values', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'sin⁻¹(1/2) equals:', '["π/3", "π/6", "5π/6", "π/4"]', 1, 'sin(π/6) = 1/2, and π/6 is in [−π/2, π/2].', '{"0": "sin(π/3) = √3/2.", "2": "5π/6 is outside the principal range.", "3": "sin(π/4) = 1/√2."}'),
  ('MTH-1006', 'Inverse trigonometric functions', 'Principal values', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'cos⁻¹(−1) equals:', '["π", "−π", "0", "π/2"]', 0, 'cos π = −1, and π is in [0, π].', '{"1": "−π is outside [0, π].", "2": "cos 0 = 1.", "3": "cos(π/2) = 0."}'),
  ('MTH-1007', 'Inverse trigonometric functions', 'Principal values', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.3)', 'tan⁻¹(−√3) equals:', '["2π/3", "−π/6", "π/3", "−π/3"]', 3, 'tan(−π/3) = −√3, and −π/3 is in (−π/2, π/2).', '{"0": "2π/3 is outside the principal range.", "1": "tan(−π/6) = −1/√3.", "2": "The sign is lost."}'),
  ('MTH-1008', 'Inverse trigonometric functions', 'Principal values', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'cos⁻¹(−1/2) equals:', '["−π/3", "π/3", "2π/3", "4π/3"]', 2, 'cos⁻¹(−x) = π − cos⁻¹x = π − π/3.', '{"0": "−π/3 is outside [0, π].", "1": "That is cos⁻¹(1/2).", "3": "4π/3 is outside [0, π]."}'),
  ('MTH-1009', 'Inverse trigonometric functions', 'Principal values', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.5)', 'sec⁻¹(2) equals:', '["π/6", "2π/3", "π/3", "π/4"]', 2, 'sec⁻¹2 = cos⁻¹(1/2) = π/3.', '{"0": "sec(π/6) = 2/√3.", "1": "sec(2π/3) = −2.", "3": "sec(π/4) = √2."}'),
  ('MTH-1010', 'Inverse trigonometric functions', 'Principal values', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.6)', 'cot⁻¹(−1) equals:', '["−π/4", "π/4", "5π/4", "3π/4"]', 3, 'cot⁻¹ has range (0, π); cot(3π/4) = −1.', '{"0": "−π/4 is outside (0, π).", "1": "cot(π/4) = 1.", "2": "5π/4 is outside (0, π)."}'),
  ('MTH-1011', 'Inverse trigonometric functions', 'Principal values', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'sin⁻¹(sin 2π/3) equals:', '["2π/3", "π/3", "−π/3", "π/6"]', 1, 'sin(2π/3) = √3/2, and the principal angle with that sine is π/3.', '{"0": "2π/3 is outside [−π/2, π/2].", "2": "The sine is positive.", "3": "sin(π/6) = 1/2."}'),
  ('MTH-1012', 'Inverse trigonometric functions', 'Principal values', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'cos⁻¹(cos 7π/6) equals:', '["5π/6", "7π/6", "π/6", "−5π/6"]', 0, 'cos(7π/6) = cos(5π/6) = −√3/2, and 5π/6 is in [0, π].', '{"1": "7π/6 is outside [0, π].", "2": "cos(π/6) is positive.", "3": "Negative angles are outside [0, π]."}'),
  ('MTH-1013', 'Inverse trigonometric functions', 'Principal values', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.3)', 'tan⁻¹(tan 3π/4) equals:', '["3π/4", "π/4", "−3π/4", "−π/4"]', 3, 'tan(3π/4) = −1, and the principal angle with tangent −1 is −π/4.', '{"0": "3π/4 is outside (−π/2, π/2).", "1": "The tangent is negative.", "2": "Outside (−π/2, π/2)."}'),
  ('MTH-1014', 'Inverse trigonometric functions', 'Principal values', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1)', 'sin(cos⁻¹(3/5)) equals:', '["3/5", "4/5", "3/4", "5/4"]', 1, 'If cos θ = 3/5 with θ in [0, π], then sin θ = √(1 − 9/25) = 4/5 (positive).', '{"0": "That is cos θ.", "2": "That is cot θ.", "3": "Sine never exceeds 1."}'),
  ('MTH-1015', 'Inverse trigonometric functions', 'Principal values', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1)', 'tan(sin⁻¹(5/13)) equals:', '["5/12", "12/5", "5/13", "13/12"]', 0, 'sin θ = 5/13 gives cos θ = 12/13 (θ in the principal range), so tan θ = 5/12.', '{"1": "That is cot θ.", "2": "That is sin θ.", "3": "That is sec θ."}'),
  ('MTH-1016', 'Inverse trigonometric functions', 'Principal values', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1)', 'cos(tan⁻¹(3/4)) equals:', '["3/5", "4/3", "4/5", "5/4"]', 2, 'tan θ = 3/4 gives a 3-4-5 triangle with θ acute, so cos θ = 4/5.', '{"0": "That is sin θ.", "1": "That is cot θ.", "3": "That is sec θ."}'),
  ('MTH-1017', 'Inverse trigonometric functions', 'Identities', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'sin⁻¹x + cos⁻¹x equals (for −1 ≤ x ≤ 1):', '["π/2", "π", "0", "1"]', 0, 'If sin⁻¹x = θ, then cos(π/2 − θ) = x, so cos⁻¹x = π/2 − θ.', '{"1": "That is cos⁻¹x + cos⁻¹(−x).", "2": "That would need cos⁻¹x = −sin⁻¹x, but cos⁻¹x ≥ 0 and the two differ.", "3": "The sum is the angle π/2 ≈ 1.571 rad, not 1."}'),
  ('MTH-1018', 'Inverse trigonometric functions', 'Identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'tan⁻¹x + cot⁻¹x equals (for all real x):', '["π", "0", "π/2", "π/4"]', 2, 'Complementary angles: cot⁻¹x = π/2 − tan⁻¹x.', '{"0": "That is cot⁻¹x + cot⁻¹(−x).", "1": "They are complementary, not opposite.", "3": "Only tan⁻¹1 = π/4."}'),
  ('MTH-1019', 'Inverse trigonometric functions', 'Identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'sin⁻¹(−x) equals:', '["π − sin⁻¹x", "−sin⁻¹x", "sin⁻¹x", "π/2 − sin⁻¹x"]', 1, 'sin⁻¹ is an odd function.', '{"0": "That is the rule for cos⁻¹(−x).", "2": "The sign changes.", "3": "That is cos⁻¹x."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-1020', 'Inverse trigonometric functions', 'Identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'cos⁻¹(−x) equals:', '["−cos⁻¹x", "cos⁻¹x", "π/2 + cos⁻¹x", "π − cos⁻¹x"]', 3, 'cos(π − θ) = −cos θ, and π − θ stays in [0, π].', '{"0": "−cos⁻¹x would be negative, outside [0, π].", "1": "cos⁻¹ is not even.", "2": "At x = 1 it gives π/2, but cos⁻¹(−1) = π."}'),
  ('MTH-1021', 'Inverse trigonometric functions', 'Identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'tan⁻¹x + tan⁻¹y equals (when xy < 1):', '["tan⁻¹[(x + y)/(1 + xy)]", "tan⁻¹(x + y)", "tan⁻¹[(x + y)/(1 − xy)]", "tan⁻¹[(x − y)/(1 + xy)]"]', 2, 'From tan(α + β) = (tan α + tan β)/(1 − tan α tan β).', '{"0": "The denominator is 1 − xy.", "1": "tan⁻¹ is not additive.", "3": "That is tan⁻¹x − tan⁻¹y."}'),
  ('MTH-1022', 'Inverse trigonometric functions', 'Identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'tan⁻¹(1/2) + tan⁻¹(1/3) equals:', '["π/4", "π/3", "π/6", "π/2"]', 0, '(1/2 + 1/3)/(1 − 1/6) = (5/6)/(5/6) = 1, and tan⁻¹1 = π/4.', '{"1": "tan(π/3) = √3.", "2": "tan(π/6) = 1/√3.", "3": "The sum would need xy = 1."}'),
  ('MTH-1023', 'Inverse trigonometric functions', 'Identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', '2 tan⁻¹x equals (for |x| < 1):', '["tan⁻¹(2x)", "tan⁻¹[2x/(1 + x²)]", "tan⁻¹(x²)", "tan⁻¹[2x/(1 − x²)]"]', 3, 'Put y = x in the sum formula.', '{"0": "tan⁻¹ is not linear.", "1": "The denominator is 1 − x².", "2": "That squares x instead of doubling the angle."}'),
  ('MTH-1024', 'Inverse trigonometric functions', 'Identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'tan⁻¹3 − tan⁻¹(1/2) equals:', '["π/3", "π/4", "tan⁻¹(5/2)", "π/6"]', 1, '(3 − 1/2)/(1 + 3/2) = (5/2)/(5/2) = 1.', '{"0": "tan(π/3) = √3.", "2": "That subtracts the arguments.", "3": "tan(π/6) = 1/√3."}'),
  ('MTH-1025', 'Inverse trigonometric functions', 'Identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'sin⁻¹(3/5) + sin⁻¹(4/5) equals:', '["π/2", "π/4", "π", "sin⁻¹(7/5)"]', 0, 'sin⁻¹(4/5) = cos⁻¹(3/5), and sin⁻¹x + cos⁻¹x = π/2.', '{"1": "That would need equal angles of π/8.", "2": "Each angle is less than π/2.", "3": "sin⁻¹ is not additive; 7/5 > 1 anyway."}'),
  ('MTH-1026', 'Inverse trigonometric functions', 'Identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'If sin⁻¹x = π/5, then cos⁻¹x equals:', '["π/5", "3π/10", "4π/5", "π/10"]', 1, 'cos⁻¹x = π/2 − π/5 = 3π/10.', '{"0": "They are complementary, not equal.", "2": "That is π − π/5.", "3": "Half the difference."}'),
  ('MTH-1027', 'Inverse trigonometric functions', 'Identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.2)', 'The solution of tan⁻¹(2x) + tan⁻¹(3x) = π/4 (x > 0) is:', '["x = 1", "x = 1/5", "x = 1/6", "x = −1"]', 2, '(5x)/(1 − 6x²) = 1 gives 6x² + 5x − 1 = 0, so x = 1/6 or x = −1; only x = 1/6 is positive (and keeps 6x² < 1).', '{"0": "Then 6x² > 1 and the formula changes.", "1": "Then 5x = 1 but 1 − 6x² = 19/25, so the ratio is not 1.", "3": "Rejected: it is negative and gives −3π/4."}'),
  ('MTH-1028', 'Inverse trigonometric functions', 'Graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'The graph of y = sin⁻¹x is the reflection, in the line y = x, of:', '["y = sin x for 0 ≤ x ≤ π", "y = cos x for 0 ≤ x ≤ π", "the whole graph of y = sin x", "y = sin x for −π/2 ≤ x ≤ π/2"]', 3, 'An inverse graph mirrors the restricted (one-to-one) part of the original.', '{"0": "sin x is not one-to-one on [0, π].", "1": "That gives cos⁻¹x.", "2": "The whole sine graph is not one-to-one."}'),
  ('MTH-1029', 'Inverse trigonometric functions', 'Graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.3)', 'The graph of y = tan⁻¹x has horizontal asymptotes:', '["x = π/2 and x = −π/2", "y = 0 and y = π", "y = π/2 and y = −π/2", "y = 1 and y = −1"]', 2, 'tan⁻¹x → ±π/2 as x → ±∞.', '{"0": "Those are vertical asymptotes of tan x.", "1": "Those are for cot⁻¹x.", "3": "Those bound sin x, not tan⁻¹x."}'),
  ('MTH-1030', 'Inverse trigonometric functions', 'Graphs', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.2)', 'Which inverse trigonometric function is decreasing on its whole domain?', '["cos⁻¹x", "sin⁻¹x", "tan⁻¹x", "sec⁻¹x on x ≥ 1"]', 0, 'cos⁻¹x falls from π at x = −1 to 0 at x = 1.', '{"1": "It increases from −π/2 to π/2.", "2": "It increases.", "3": "It increases from 0 towards π/2."}'),
  ('MTH-1031', 'Inverse trigonometric functions', 'Graphs', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 9 Inverse Trigonometric Functions and Their Graphs (§9.1.1)', 'The graph of y = sin⁻¹x passes through:', '["(π/2, 1)", "(0, π/2)", "(1, π)", "(1, π/2)"]', 3, 'sin⁻¹1 = π/2.', '{"0": "That is a point on y = sin x.", "1": "sin⁻¹0 = 0.", "2": "π is outside the range."}'),
  ('MTH-1032', 'Trigonometric equations', 'Basic trigonometric equations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of sin x = 1/2 in [0, 2π) are:', '["π/6 and 7π/6", "π/6 and 5π/6", "π/3 and 2π/3", "π/6 only"]', 1, 'Sine is positive in quadrants I and II: x = π/6 and π − π/6.', '{"0": "sin(7π/6) = −1/2.", "2": "sin(π/3) = √3/2.", "3": "The second-quadrant solution is missing."}'),
  ('MTH-1033', 'Trigonometric equations', 'Basic trigonometric equations', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of cos x = −1 in [0, 2π) are:', '["0 and π", "π only", "π/2 and 3π/2", "π and 2π"]', 1, 'cos x = −1 only at x = π in one period.', '{"0": "cos 0 = 1.", "2": "cos(π/2) = 0.", "3": "2π is outside [0, 2π), and cos 2π = 1."}'),
  ('MTH-1034', 'Trigonometric equations', 'Basic trigonometric equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of tan x = −1 in [0, 2π) are:', '["π/4 and 5π/4", "3π/4 and 5π/4", "−π/4 only", "3π/4 and 7π/4"]', 3, 'Tangent is negative in quadrants II and IV; the reference angle is π/4.', '{"0": "tan(π/4) = 1.", "1": "tan(5π/4) = 1.", "2": "−π/4 is outside [0, 2π)."}'),
  ('MTH-1035', 'Trigonometric equations', 'Basic trigonometric equations', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of sin x = −√3/2 in [0, 2π) are:', '["4π/3 and 5π/3", "π/3 and 2π/3", "2π/3 and 4π/3", "7π/6 and 11π/6"]', 0, 'Sine is negative in quadrants III and IV with reference angle π/3: π + π/3 and 2π − π/3.', '{"1": "There the sine is positive.", "2": "sin(2π/3) is positive.", "3": "Those give sin x = −1/2."}'),
  ('MTH-1036', 'Trigonometric equations', 'General solutions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The general solution of cos x = 1/2 is:', '["x = nπ + π/3, n ∈ ℤ", "x = 2nπ + π/3 only", "x = 2nπ ± π/3, n ∈ ℤ", "x = nπ ± π/6, n ∈ ℤ"]', 2, 'Principal solutions π/3 and 5π/3 = 2π − π/3; cosine has period 2π.', '{"0": "nπ + π/3 includes 4π/3, where cos = −1/2.", "1": "Misses the family 2nπ − π/3.", "3": "Those angles have cos = √3/2 or −√3/2."}'),
  ('MTH-1037', 'Trigonometric equations', 'General solutions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The general solution of tan x = √3 is:', '["x = 2nπ + π/3, n ∈ ℤ", "x = nπ + π/3, n ∈ ℤ", "x = nπ + π/6, n ∈ ℤ", "x = 2nπ ± π/3, n ∈ ℤ"]', 1, 'Tangent has period π, and tan(π/3) = √3.', '{"0": "That misses 4π/3, where tan = √3 too.", "2": "tan(π/6) = 1/√3.", "3": "2nπ − π/3 gives tan = −√3."}'),
  ('MTH-1038', 'Trigonometric equations', 'General solutions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The general solution of sin x = 0 is:', '["x = 2nπ, n ∈ ℤ", "x = nπ + π/2, n ∈ ℤ", "x = nπ/2, n ∈ ℤ", "x = nπ, n ∈ ℤ"]', 3, 'sin x = 0 at every multiple of π.', '{"0": "That misses π, 3π, ….", "1": "Those are the zeros of cos x.", "2": "That includes π/2, where sin = 1."}'),
  ('MTH-1039', 'Trigonometric equations', 'General solutions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The general solution of sin 2x = 1 is:', '["x = nπ + π/4, n ∈ ℤ", "x = 2nπ + π/4, n ∈ ℤ", "x = nπ + π/2, n ∈ ℤ", "x = 2nπ + π/2, n ∈ ℤ"]', 0, '2x = 2nπ + π/2, so x = nπ + π/4.', '{"1": "Dividing 2nπ by 2 gives nπ.", "2": "At x = π/2, sin 2x = sin π = 0.", "3": "That solves sin x = 1, not sin 2x = 1."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-1040', 'Trigonometric equations', 'Equations reducible to quadratics', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of 2sin²x − sin x = 0 in [0, 2π) are:', '["π/6 and 5π/6", "0 and π", "0, π/6, 5π/6, π", "0, π/6, π"]', 2, 'sin x(2 sin x − 1) = 0: sin x = 0 gives 0, π; sin x = 1/2 gives π/6, 5π/6.', '{"0": "Dividing by sin x loses 0 and π.", "1": "Misses sin x = 1/2.", "3": "Misses 5π/6."}'),
  ('MTH-1041', 'Trigonometric equations', 'Equations reducible to quadratics', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of 2cos²x − 3cos x + 1 = 0 in [0, 2π) are:', '["π/3 and 5π/3", "0 and π", "0, π/3, 5π/3", "π/3, 2π/3, 0"]', 2, '(2 cos x − 1)(cos x − 1) = 0: cos x = 1/2 or 1.', '{"0": "Misses cos x = 1 at x = 0.", "1": "cos π = −1.", "3": "cos(2π/3) = −1/2."}'),
  ('MTH-1042', 'Trigonometric equations', 'Equations reducible to quadratics', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of 2cos²x + sin x − 1 = 0 in [0, 2π) are:', '["π/2, 7π/6, 11π/6", "π/6 and 5π/6", "π/2 only", "3π/2, π/6, 5π/6"]', 0, 'Use cos²x = 1 − sin²x: 2 − 2sin²x + sin x − 1 = 0, i.e. 2sin²x − sin x − 1 = 0, so (2 sin x + 1)(sin x − 1) = 0: sin x = 1 or −1/2.', '{"1": "Those give sin x = +1/2.", "2": "Misses sin x = −1/2.", "3": "Signs of both roots reversed."}'),
  ('MTH-1043', 'Trigonometric equations', 'Equations reducible to quadratics', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'Solving 2sec²x − 5 tan x = 0 gives tan x =', '["−2 or −1/2", "2 or −1/2", "5/2 or 1", "2 or 1/2"]', 3, 'Using sec²x = 1 + tan²x: 2tan²x − 5 tan x + 2 = 0, i.e. (2 tan x − 1)(tan x − 2) = 0.', '{"0": "The signs are reversed.", "1": "One sign is wrong.", "2": "t = 1 gives 2 − 5 + 2 = −1, not 0."}'),
  ('MTH-1044', 'Trigonometric equations', 'Equations reducible to quadratics', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of 4sin²x = 3 in [0, π] are:', '["π/6 and 5π/6", "π/3 and 2π/3", "π/3 only", "π/3, 2π/3, 4π/3"]', 1, 'sin x = ±√3/2; in [0, π] only sin x = √3/2 has solutions.', '{"0": "Those give sin x = 1/2.", "2": "Misses 2π/3.", "3": "4π/3 is outside [0, π]."}'),
  ('MTH-1045', 'Trigonometric equations', 'Using identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of sin x + cos x = 0 in [0, 2π) are:', '["π/4 and 5π/4", "3π/4 only", "3π/4 and 7π/4", "π/2 and π"]', 2, 'Divide by cos x (cos x ≠ 0 here): tan x = −1.', '{"0": "Those give sin x = cos x.", "1": "Misses 7π/4.", "3": "sin(π/2) + cos(π/2) = 1."}'),
  ('MTH-1046', 'Trigonometric equations', 'Using identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of sin 2x = sin x in [0, 2π) are:', '["0 and π", "π/3 and 5π/3", "0, π/3, 2π/3, π", "0, π/3, π, 5π/3"]', 3, '2 sin x cos x − sin x = sin x(2 cos x − 1) = 0: sin x = 0 or cos x = 1/2.', '{"0": "Only the sin x = 0 roots; cos x = 1/2 is missing.", "1": "Misses sin x = 0.", "2": "cos(2π/3) = −1/2."}'),
  ('MTH-1047', 'Trigonometric equations', 'Using identities', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of cos 2x = cos x in [0, 2π) are:', '["0 and π", "0, 2π/3, 4π/3", "π/3 and 5π/3", "2π/3 and 4π/3"]', 1, '2cos²x − 1 − cos x = 0 gives (2 cos x + 1)(cos x − 1) = 0: cos x = 1 or −1/2.', '{"0": "At x = π, cos 2x = 1 but cos x = −1.", "2": "Those give cos x = 1/2.", "3": "Misses cos x = 1 at 0."}'),
  ('MTH-1048', 'Trigonometric equations', 'Using identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The solutions of √3 tan x − 1 = 0 in [0, 2π) are:', '["π/6 and 7π/6", "π/3 and 4π/3", "π/6 and 5π/6", "π/6 only"]', 0, 'tan x = 1/√3; period π.', '{"1": "tan(π/3) = √3.", "2": "tan(5π/6) = −1/√3.", "3": "Misses 7π/6."}'),
  ('MTH-1049', 'Trigonometric equations', 'Using identities', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'The number of solutions of sin 3x = 0 in [0, 2π) is:', '["3", "2", "6", "4"]', 2, '3x = nπ, so x = nπ/3 for n = 0, 1, …, 5.', '{"0": "That counts [0, π).", "1": "That is for sin x = 0.", "3": "That is the count for sin 2x = 0."}'),
  ('MTH-1050', 'Trigonometric equations', 'Graphical solutions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.2)', 'To solve sin x = x/2 graphically, we look for intersections of:', '["y = sin x and y = 2x", "y = sin(x/2) and y = x", "y = sin x and y = 1/2", "y = sin x and y = x/2"]', 3, 'Each intersection gives a value of x that satisfies both.', '{"0": "That is sin x = 2x.", "1": "That is sin(x/2) = x.", "2": "That is sin x = 1/2."}'),
  ('MTH-1051', 'Trigonometric equations', 'Graphical solutions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.2)', 'How many real solutions does sin x = x/2 have?', '["1", "3", "2", "Infinitely many"]', 1, 'y = x/2 meets y = sin x at 0 and at about ±1.9; for |x| > 2, |x/2| > 1 ≥ |sin x|.', '{"0": "The positive and negative crossings are missed.", "2": "The curves are both odd, so solutions come in ± pairs plus 0.", "3": "The line leaves the band −1 ≤ y ≤ 1."}'),
  ('MTH-1052', 'Trigonometric equations', 'Graphical solutions', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.2)', 'The number of solutions of cos x = x² is:', '["2", "1", "0", "4"]', 0, 'y = x² meets y = cos x at about x = ±0.82; for |x| > 1, x² > 1 ≥ cos x.', '{"1": "Both curves are even, so solutions come in ± pairs.", "2": "They meet near x = ±0.82.", "3": "Only one pair of crossings."}'),
  ('MTH-1053', 'Trigonometric equations', 'General solutions', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.1)', 'Solutions of a trigonometric equation that lie in [0, 2π] are called:', '["general solutions", "trivial solutions", "particular integrals", "principal solutions"]', 3, 'Adding multiples of the period to them gives the general solution.', '{"0": "The general solution covers all periods.", "1": "Not the term used.", "2": "That belongs to differential equations."}'),
  ('MTH-1054', 'Trigonometric equations', 'Real-life problems', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.3)', 'A pole of height h casts a shadow of length h√3. The sun''s angle of elevation θ satisfies tan θ = 1/√3, so θ is:', '["60°", "30°", "45°", "90°"]', 1, 'tan θ = height/shadow = 1/√3.', '{"0": "tan 60° = √3.", "2": "tan 45° = 1.", "3": "No shadow at 90°."}'),
  ('MTH-1055', 'Trigonometric equations', 'Real-life problems', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.3)', 'The height of a tide (m) is h = 3 + 2 sin(πt/6), t in hours. In 0 ≤ t < 12, h = 4 m at:', '["t = 1 and t = 5", "t = 2 and t = 4", "t = 1 only", "t = 3"]', 0, 'sin(πt/6) = 1/2, so πt/6 = π/6 or 5π/6.', '{"1": "There sin(πt/6) = √3/2.", "2": "Misses t = 5.", "3": "At t = 3, h = 5 m (high tide)."}'),
  ('MTH-1056', 'Trigonometric equations', 'Real-life problems', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 10 Solution of Trigonometric Equations (§10.3)', 'An alternating voltage is V = 10 sin(100πt). The first positive time at which V = 5 is:', '["1/200 s", "1/300 s", "1/600 s", "1/100 s"]', 2, '100πt = π/6 gives t = 1/600 s.', '{"0": "That gives 100πt = π/2, where V = 10.", "1": "That gives 100πt = π/3, where V = 5√3.", "3": "That gives 100πt = π, where V = 0."}'),
  ('MTH-1057', 'Vector-valued functions', 'Scalar and vector functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.3)', 'Which of these is a vector-valued function of t?', '["r(t) = t²i + (sin t)j", "f(t) = t² + sin t", "g(t) = |ti + j|", "h(t) = (ti + j)·(i + j)"]', 0, 'Its output is a vector with components t² and sin t.', '{"1": "Its output is a number.", "2": "A magnitude is a number.", "3": "A dot product is a number."}'),
  ('MTH-1058', 'Vector-valued functions', 'Scalar and vector functions', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.1.2)', 'For r(t) = (3t)i + (t − 1)j + t²k, r(2) is:', '["6i − j + 4k", "6i + j + 4k", "3i + j + 2k", "6i + j + 2k"]', 1, 'Substitute t = 2 in each component.', '{"0": "2 − 1 = 1.", "2": "Those are the coefficients, not the values.", "3": "t² at 2 is 4."}'),
  ('MTH-1059', 'Vector-valued functions', 'Domain', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.2.1)', 'The domain of r(t) = √(t − 1) i + (1/(t − 3)) j is:', '["t > 1", "t ≠ 3", "t ≥ 1, t ≠ 3", "1 ≤ t ≤ 3"]', 2, 'Intersection of the components'' domains: t ≥ 1 and t ≠ 3.', '{"0": "t = 1 is allowed, and t = 3 must go.", "1": "t < 1 makes the root undefined.", "3": "t > 3 is allowed."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Mathematics', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('MTH-1060', 'Vector-valued functions', 'Domain', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.2.1)', 'The domain of r(t) = (ln t) i + √(4 − t²) j is:', '["−2 ≤ t ≤ 2", "t > 0", "0 ≤ t ≤ 2", "0 < t ≤ 2"]', 3, 'ln t needs t > 0; √(4 − t²) needs −2 ≤ t ≤ 2.', '{"0": "ln t is undefined for t ≤ 0.", "1": "√(4 − t²) fails for t > 2.", "2": "ln 0 is undefined."}'),
  ('MTH-1061', 'Vector-valued functions', 'Domain', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.2.1)', 'The domain of r(t) = (tan t) i + eᵗ j, for 0 ≤ t < 2π, excludes:', '["t = 0 and t = π", "t = π only", "nothing", "t = π/2 and t = 3π/2"]', 3, 'tan t is undefined where cos t = 0; eᵗ is defined everywhere.', '{"0": "tan 0 = tan π = 0.", "1": "tan π = 0.", "2": "tan t is undefined at π/2 and 3π/2."}'),
  ('MTH-1062', 'Vector-valued functions', 'Derivatives', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'If r(t) = t³ i + 2t j, then r′(t) is:', '["3t² i + 2t j", "t² i + 2 j", "3t² i + 2 j", "3t² + 2"]', 2, 'Differentiate each component.', '{"0": "2t differentiates to 2.", "1": "The 3 must come down.", "3": "The result is a vector, not a number."}'),
  ('MTH-1063', 'Vector-valued functions', 'Derivatives', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'If r(t) = (sin t) i + (cos t) j + t k, then r′(t) is:', '["(cos t) i + (sin t) j + k", "(cos t) i − (sin t) j + k", "−(cos t) i + (sin t) j", "(cos t) i − (sin t) j + t k"]', 1, 'd/dt sin t = cos t, d/dt cos t = −sin t, d/dt t = 1.', '{"0": "d/dt cos t = −sin t.", "2": "Signs swapped, and the k component is lost.", "3": "d/dt t = 1."}'),
  ('MTH-1064', 'Vector-valued functions', 'Derivatives', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'If r(t) = e²ᵗ i + ln(t) j, then r′(1) is:', '["2e² i + j", "e² i + j", "2e² i", "2e i + j"]', 0, 'r′(t) = 2e²ᵗ i + (1/t) j; at t = 1: 2e² i + j.', '{"1": "The chain factor 2 is missing.", "2": "1/t at 1 is 1, not 0.", "3": "e²ᵗ at t = 1 is e²."}'),
  ('MTH-1065', 'Vector-valued functions', 'Derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'For r(t) = t i + t² j, the unit tangent vector at t = 1 is:', '["i + 2j", "(i + j)/√2", "(i + 2j)/√5", "(2i + j)/√5"]', 2, 'r′(1) = i + 2j with length √5; dividing gives a unit vector.', '{"0": "Not of length 1.", "1": "r′(1) is i + 2j, not i + j.", "3": "Components swapped."}'),
  ('MTH-1066', 'Vector-valued functions', 'Derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'If u(t) = t i + j and v(t) = i + t² j, then d/dt [u·v] is:', '["2t", "1 + t²", "i + 2t j", "1 + 2t"]', 3, 'u·v = t + t², whose derivative is 1 + 2t.', '{"0": "Missing the derivative of t.", "1": "That differentiates t but leaves t² as it is.", "2": "A dot product is a scalar."}'),
  ('MTH-1067', 'Vector-valued functions', 'Derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'The rule for the derivative of a dot product is:', '["(u·v)′ = u′·v′", "(u·v)′ = u′·v + u·v′", "(u·v)′ = u′ × v + u × v′", "(u·v)′ = u′·v − u·v′"]', 1, 'It mirrors the product rule.', '{"0": "That multiplies the derivatives only.", "2": "That mixes in cross products.", "3": "The terms are added."}'),
  ('MTH-1068', 'Vector-valued functions', 'Derivatives', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.4)', 'If |r(t)| is constant for all t, then r(t)·r′(t) equals:', '["0", "|r|²", "1", "|r′|²"]', 0, 'r·r = constant; differentiating gives 2 r·r′ = 0, so r′ is perpendicular to r.', '{"1": "That is r·r.", "2": "That is r·r for a unit vector, not r·r′.", "3": "That is r′·r′."}'),
  ('MTH-1069', 'Vector-valued functions', 'Velocity and acceleration', 'easy', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'If r(t) is a position vector, then the velocity vector is:', '["r″(t)", "|r(t)|", "∫r(t) dt", "r′(t)"]', 3, 'Velocity is the rate of change of position.', '{"0": "That is the acceleration.", "1": "That is the distance from the origin.", "2": "That integrates position instead of differentiating it."}'),
  ('MTH-1070', 'Vector-valued functions', 'Velocity and acceleration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'For r(t) = 3t² i + 2 sin t j (metres), the velocity at t = π/2 is:', '["3π i + 2 j", "3π i", "6 i", "3π i − 2 j"]', 1, 'v(t) = 6t i + 2 cos t j; at t = π/2: 3π i + 0 j.', '{"0": "cos(π/2) = 0.", "2": "That is the acceleration''s i component.", "3": "The j component is 2 cos(π/2) = 0."}'),
  ('MTH-1071', 'Vector-valued functions', 'Velocity and acceleration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'For r(t) = 3t² i + 2 sin t j, the acceleration at t = π/2 is:', '["6 i − 2 j", "6 i + 2 j", "3π i", "6t i − 2 sin t j"]', 0, 'a(t) = 6 i − 2 sin t j; sin(π/2) = 1.', '{"1": "The sign of the j component is wrong.", "2": "That is the velocity.", "3": "The derivative of 6t is 6, not 6t."}'),
  ('MTH-1072', 'Vector-valued functions', 'Velocity and acceleration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'The speed of a particle with velocity v = 3 i − 4 j is:', '["7", "−1", "5", "25"]', 2, 'Speed = |v| = √(9 + 16).', '{"0": "That adds the components.", "1": "Speed is never negative.", "3": "That is |v|²."}'),
  ('MTH-1073', 'Vector-valued functions', 'Velocity and acceleration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'For circular motion r(t) = 2 cos t i + 2 sin t j, the speed is:', '["2 (constant)", "2t", "4", "2 cos t"]', 0, 'v = −2 sin t i + 2 cos t j, so |v| = √(4 sin²t + 4 cos²t) = 2.', '{"1": "Speed does not grow with t.", "2": "That is |v|².", "3": "That is one component."}'),
  ('MTH-1074', 'Vector-valued functions', 'Velocity and acceleration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'For r(t) = 2 cos t i + 2 sin t j, the acceleration is:', '["r(t), pointing outward", "0", "−r(t), pointing towards the centre", "tangent to the circle"]', 2, 'a = −2 cos t i − 2 sin t j = −r(t).', '{"0": "The sign is negative.", "1": "Changing direction needs acceleration.", "3": "It points to the centre, at right angles to the tangent."}'),
  ('MTH-1075', 'Vector-valued functions', 'Velocity and acceleration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'A particle has r(t) = t² i + (t³ − 3t) j. It moves parallel to the x-axis when:', '["t = 0", "t = ±1", "t = ±√3", "never"]', 1, 'The velocity''s j component 3t² − 3 = 0, while the i component 2t ≠ 0.', '{"0": "At t = 0 the j component is −3.", "2": "Those are where y = 0.", "3": "It does at t = ±1."}'),
  ('MTH-1076', 'Vector-valued functions', 'Velocity and acceleration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'If the velocity is v(t) = 2t i + 3 j and r(0) = i, then r(t) is:', '["t² i + 3t j", "2 i", "(t² + 1) i + 3 j", "(t² + 1) i + 3t j"]', 3, 'Integrate each component and use r(0) = i.', '{"0": "The starting position is ignored.", "1": "That is the acceleration.", "2": "∫3 dt = 3t."}'),
  ('MTH-1077', 'Vector-valued functions', 'Velocity and acceleration', 'hard', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'For r(t) = eᵗ i + e⁻ᵗ j, the speed at t = 0 is:', '["2", "√2", "0", "1"]', 1, 'v = eᵗ i − e⁻ᵗ j; at t = 0, v = i − j, with length √2.', '{"0": "That adds the components without the minus sign.", "2": "v(0) is not 0.", "3": "That is one component."}'),
  ('MTH-1078', 'Vector-valued functions', 'Velocity and acceleration', 'moderate', 'Mathematics 12 (PECTAA, Punjab), Unit 11 Vector Valued Functions and Their Differentiations (§11.5)', 'The direction of motion at an instant is given by:', '["the acceleration vector", "the position vector", "the speed", "the velocity vector"]', 3, 'Velocity is tangent to the path in the direction of motion.', '{"0": "Acceleration can point elsewhere, e.g. inward in circular motion.", "1": "Position points from the origin.", "2": "Speed has no direction."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

